### Description

The Terraform program below configures AWS Route 53 to route traffic to different database endpoints based on whether the user is internal or external. The program sets up two Route 53 hosted zones named "private" and "public". It also creates two RDS instances, one for internal use and another for public access. The internal RDS instance is placed in a private subnet, while the public RDS instance is publicly accessible. The program ensures that internal DNS queries resolve to the internal RDS instance, and external DNS queries resolve to the public RDS instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instances will be deployed."
  type        = string
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the RDS instances will be deployed."
  type        = list(string)
}

variable "db_instance_class" {
  description = "The instance class for the RDS instances."
  type        = string
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "The database engine to use for the RDS instances."
  type        = string
  default     = "mysql"
}

variable "db_username" {
  description = "The username for the RDS instances."
  type        = string
  sensitive   = true
}

variable "db_password" {
  description = "The password for the RDS instances."
  type        = string
  sensitive   = true
}

resource "aws_route53_zone" "private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public" {
  name = "public.example.com"
}

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = var.subnet_ids
}

resource "aws_db_instance" "internal" {
  identifier              = "internal-db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = ["sg-0123456789abcdef0"] # Replace with your security group ID
  skip_final_snapshot     = true
  publicly_accessible     = false
}

resource "aws_db_instance" "public" {
  identifier              = "public-db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = ["sg-0123456789abcdef0"] # Replace with your security group ID
  skip_final_snapshot     = true
  publicly_accessible     = true
}

resource "aws_route53_record" "internal_db_record" {
  zone_id = aws_route53_zone.private.zone_id
  name    = "db"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.internal.endpoint]
}

resource "aws_route53_record" "public_db_record" {
  zone_id = aws_route53_zone.public.zone_id
  name    = "db"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.public.endpoint]
}
```

### Notes

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region. You can change this to your desired region.
2. **Variables**: The program uses several variables to allow customization, such as the VPC ID, subnet IDs, DB instance class, and database credentials.
3. **Security Groups**: Replace `"sg-0123456789abcdef0"` with the actual security group IDs that allow appropriate access to the RDS instances.
4. **Route 53 Records**: The program creates CNAME records in the "private" and "public" zones that point to the respective RDS instances' endpoints.

This configuration ensures that internal users querying the "private" zone will be directed to the internal RDS instance, while external users querying the "public" zone will be directed to the public RDS instance.

