The Terraform program below configures AWS Route 53 to manage a domain and directs traffic to an Elastic Beanstalk environment. The program includes the following components:

1. **AWS Provider Configuration**: Sets up the AWS provider with a specified region.
2. **Route 53 Hosted Zone**: Creates a hosted zone named "main".
3. **Elastic Beanstalk Application**: Creates an Elastic Beanstalk application named "myapp".
4. **Elastic Beanstalk Application Version**: Creates an application version named "version".
5. **IAM Role and Instance Profile**: Creates an IAM role and instance profile for the Elastic Beanstalk environment.
6. **S3 Bucket**: Creates an S3 bucket with a unique name.
7. **S3 Object**: Uploads an example object to the S3 bucket.
8. **Elastic Beanstalk Environment**: Creates an Elastic Beanstalk environment named "eb-env" and associates it with the previously created resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "domain_name" {
  description = "The domain name to manage with Route 53"
  type        = string
  default     = "example.com"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name"
  type        = string
  default     = "examplebucket"
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

resource "aws_s3_bucket" "examplebucket" {
  bucket = "${var.bucket_name_prefix}-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.examplebucket.bucket
  key    = "example.txt"
  content = "Hello, World!"
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.examplebucket.bucket
  key         = aws_s3_object.examplebucket_object.key
  version_label = "v1"
}

resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  version_label       = aws_elastic_beanstalk_application_version.version.version_label
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name
}
```

