variable "application_name" {
  description = "The name of the Elastic Beanstalk application"
  default     = "MyApp"
}

variable "environment_name_blue" {
  description = "The name of the blue Elastic Beanstalk environment"
  default     = "MyApp-blue"
}

variable "environment_name_green" {
  description = "The name of the green Elastic Beanstalk environment"
  default     = "MyApp-green"
}

variable "domain_name" {
  description = "The domain name to use for Route53"
  default     = "example.com"
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "${var.application_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_service_role_policy" {
  role       = aws_iam_role.beanstalk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = var.environment_name_blue
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
  instance_type       = "t2.micro"
  service_role        = aws_iam_role.beanstalk_service_role.name
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = var.environment_name_green
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
  instance_type       = "t2.micro"
  service_role        = aws_iam_role.beanstalk_service_role.name
}

resource "aws_route53_zone" "primary" {
  name = var.domain_name
}

resource "aws_route53_record" "weighted_blue" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  set_identifier = "blue"

  alias {
    name                   = aws_elastic_beanstalk_environment.blue.cname
    zone_id                = aws_elastic_beanstalk_environment.blue.elb
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "weighted_green" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  set_identifier = "green"

  alias {
    name                   = aws_elastic_beanstalk_environment.green.cname
    zone_id                = aws_elastic_beanstalk_environment.green.elb
    evaluate_target_health = true
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden by setting the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the application name, environment names, and domain name.

3. **IAM Role**: An IAM role is created for the Elastic Beanstalk service with the necessary permissions attached.

4. **Elastic Beanstalk Application and Environments**: Two Elastic Beanstalk environments, "blue" and "green", are created under the same application.

5. **Route53 Zone and Records**: A Route53 zone is created for the specified domain name. Two weighted records are set up for the "www" subdomain, each pointing to one of the Elastic Beanstalk environments. The weights are initially set to 50% to distribute traffic evenly between the two environments.

This configuration provides a basic setup for a Blue/Green deployment using AWS Elastic Beanstalk and Route53. You can adjust the weights and other parameters as needed to fit your specific deployment strategy.

