  default     = "my-elastic-beanstalk-env"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment"
  default     = "t3.micro"
}

variable "min_instances" {
  description = "Minimum number of instances in the autoscaling group"
  default     = 1
}

variable "max_instances" {
  description = "Maximum number of instances in the autoscaling group"
  default     = 4
}

variable "desired_capacity" {
  description = "Desired capacity of the autoscaling group"
  default     = 2
}

variable "db_instance_class" {
  description = "Instance class for the RDS database"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS database in GB"
  default     = 20
}

variable "db_username" {
  description = "Username for the RDS database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS database"
  sensitive   = true
  default     = "password123"
}

# IAM Role and Instance Profile
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

# RDS Database
resource "aws_db_subnet_group" "my_db_subnet_group" {
  name       = "my-db-subnet-group"
  subnet_ids = data.aws_subnet_ids.default.ids

  tags = {
    Name = "MyDBSubnetGroup"
  }
}

data "aws_subnet_ids" "default" {
  vpc_id = var.vpc_id
}

resource "aws_db_instance" "my_db1" {
  identifier           = "my_db1"
  instance_class       = var.db_instance_class
  allocated_storage    = var.db_allocated_storage
  engine               = "mysql"
  engine_version       = "8.0"
  username             = var.db_username
  password             = var.db_password
  db_subnet_group_name = aws_db_subnet_group.my_db_subnet_group.name
  skip_final_snapshot  = true
}

# Elastic Beanstalk Application and Environment
resource "aws_elastic_beanstalk_application" "my_app" {
  name        = var.application_name
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "my_env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = var.min_instances
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = var.max_instances
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "DesiredCapacity"
    value     = var.desired_capacity
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "SampleCount"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Period"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "EvaluationPeriods"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "BreachDuration"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "20"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "80"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Operator"
    value     = ">="
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Alarms"
    value     = "CPUHigh"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "AdjustmentType"
    value     = "ChangeInCapacity"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "ScalingAdjustment"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerAlarmNotification"
    value     = ""
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperAlarmNotification"
    value     = ""
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceTypes"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceIdentifier"
    value     = aws_db_instance.my_db1.identifier
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUsername"
    value     = var.db_username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = var.db_password
  }
}
```

### Notes:
- Ensure that the `vpc_id` variable is set to the appropriate VPC ID where your subnets are located.
- The `db_password` variable is marked as sensitive to protect the database password.
- The autoscaling triggers are set to scale based on CPU utilization, with thresholds at 20% and 80%.
- The Elastic Beanstalk environment uses a Python 3.9 solution stack. Adjust the `solution_stack_name` if you need a different runtime.

