LLM Output #0:
### Description

The Terraform program below provisions the necessary AWS infrastructure for deploying a web application using Elastic Beanstalk. This includes:

1. **IAM Roles**: Necessary IAM roles for access management.
2. **VPC**: A Virtual Private Cloud (VPC) with an Internet Gateway for network connectivity.
3. **Subnets**: Two subnets within the VPC.
4. **Route Configurations**: Proper routing configurations to allow internet access.
5. **RDS Instance**: An Amazon RDS instance for database requirements.
6. **Elastic Beanstalk Environment**: The main environment for deploying the web application.

All resources are created within a specified AWS region, and the configuration is designed to be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "Database engine for the RDS instance"
  default     = "mysql"
}

variable "db_username" {
  description = "Username for the RDS instance"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS instance"
  sensitive   = true
  default     = "password123"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS instance"
  default     = 20
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_service_policy" {
  role       = aws_iam_role.beanstalk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_subnet" "public" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_db_subnet_group" "main" {
  name       = "beanstalk-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id
}

resource "aws_db_instance" "main" {
  identifier           = "beanstalk-db-instance"
  instance_class       = var.db_instance_class
  engine               = var.db_engine
  username             = var.db_username
  password             = var.db_password
  allocated_storage    = var.db_allocated_storage
  db_subnet_group_name = aws_db_subnet_group.main.name
  skip_final_snapshot  = true
}

resource "aws_elastic_beanstalk_application" "main" {
  name        = "beanstalk-web-app"
  description = "Elastic Beanstalk Application for Web App"
}

resource "aws_elastic_beanstalk_environment" "main" {
  name                = "beanstalk-web-env"
  application         = aws_elastic_beanstalk_application.main.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
  instance_type       = "t2.micro"
  service_role        = aws_iam_role.beanstalk_service_role.name

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceClass"
    value     = var.db_instance_class
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBEngine"
    value     = var.db_engine
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = var.db_username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = var.db_password
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBAllocatedStorage"
    value     = tostring(var.db_allocated_storage)
  }
}
```

