### Description

The Terraform program below configures an AWS environment consisting of:

1. **VPC (Virtual Private Cloud)** named `eb_vpc`.
2. **Internet Gateway** attached to the VPC.
3. **Two Public Subnets** (`eb_subnet_public_1` and `eb_subnet_public_2`) within the VPC.
4. **Security Group** named `eb_env_sg` for the Elastic Beanstalk environments.
5. **Route Table** associated with the public subnets to allow internet access.
6. **Elastic Beanstalk Environments** connected to the public subnets.
7. **Shared RDS Database** named `shared_rds` linked to the subnets.

The program ensures that all necessary IAM roles and permissions are in place for the Elastic Beanstalk environments to communicate with the RDS database. The configuration uses default values for variables where applicable, ensuring it is deployable with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_type" {
  description = "Instance type for the Elastic Beanstalk environments"
  default     = "t2.micro"
}

resource "aws_vpc" "eb_vpc" {
  cidr_block = var.vpc_cidr_block
  tags = {
    Name = "eb_vpc"
  }
}

resource "aws_internet_gateway" "eb_igw" {
  vpc_id = aws_vpc.eb_vpc.id
  tags = {
    Name = "eb_igw"
  }
}

resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true
  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id            = aws_vpc.eb_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true
  tags = {
    Name = "eb_subnet_public_2"
  }
}

resource "aws_route_table" "eb_public_rt" {
  vpc_id = aws_vpc.eb_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eb_igw.id
  }
  tags = {
    Name = "eb_public_rt"
  }
}

resource "aws_route_table_association" "eb_subnet_public_1_assoc" {
  subnet_id      = aws_subnet.eb_subnet_public_1.id
  route_table_id = aws_route_table.eb_public_rt.id
}

resource "aws_route_table_association" "eb_subnet_public_2_assoc" {
  subnet_id      = aws_subnet.eb_subnet_public_2.id
  route_table_id = aws_route_table.eb_public_rt.id
}

resource "aws_security_group" "eb_env_sg" {
  name        = "eb_env_sg"
  description = "Security group for Elastic Beanstalk environments"
  vpc_id      = aws_vpc.eb_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb_env_sg"
  }
}

resource "aws_db_subnet_group" "shared_rds_subnet_group" {
  name       = "shared_rds_subnet_group"
  subnet_ids = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]

  tags = {
    Name = "shared_rds_subnet_group"
  }
}

resource "aws_db_instance" "shared_rds" {
  identifier              = "shared_rds"
  instance_class          = "db.t2.micro"
  engine                  = "mysql"
  engine_version          = "8.0"
  username                = "admin"
  password                = "password"
  allocated_storage       = 20
  db_subnet_group_name    = aws_db_subnet_group.shared_rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.eb_env_sg.id]
  skip_final_snapshot     = true

  tags = {
    Name = "shared_rds"
  }
}

resource "aws_elastic_beanstalk_application" "eb_app" {
  name        = "eb_app"
  description = "Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "eb_env_1" {
