### Description

This Terraform configuration sets up a multi-region application deployment using AWS services. It includes:

1. **Route 53 Resources**: To manage a domain and direct traffic to Elastic Beanstalk environments in two different regions (`us-east-1` and `eu-west-1`).
2. **Elastic Beanstalk Environments**: Two environments named `myenv_us_east` and `myenv_eu_west`, each associated with an application named `myapp_us_east` and `myapp_eu_west`.
3. **RDS Databases**: Two RDS databases named `main_db_us_east` and `main_db_eu_west`, one in each region.
4. **IAM Roles and Instance Profiles**: An IAM role and instance profile named `eb_ec2_profile3` for the EC2 instances in the Elastic Beanstalk environments.

The configuration ensures that all resources are properly provisioned and interconnected, with appropriate naming conventions and region-specific settings.

### Terraform Configuration

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The domain name to manage with Route 53"
  type        = string
  default     = "example.com"
}

variable "instance_type" {
  description = "The EC2 instance type for Elastic Beanstalk"
  type        = string
  default     = "t2.micro"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile3"
  roles = [aws_iam_role.eb_ec2_role.name]
}

resource "aws_rds_instance" "main_db_us_east" {
  count         = var.region == "us-east-1" ? 1 : 0
  identifier    = "main_db_us_east"
  engine        = "mysql"
  engine_version = "8.0"
  instance_class = "db.t2.micro"
  allocated_storage = 20
  username      = "admin"
  password      = "password"
  skip_final_snapshot = true
}

resource "aws_rds_instance" "main_db_eu_west" {
  count         = var.region == "eu-west-1" ? 1 : 0
  identifier    = "main_db_eu_west"
  engine        = "mysql"
  engine_version = "8.0"
  instance_class = "db.t2.micro"
  allocated_storage = 20
  username      = "admin"
  password      = "password"
  skip_final_snapshot = true
}

resource "aws_elastic_beanstalk_application" "myapp_us_east" {
  count = var.region == "us-east-1" ? 1 : 0
  name  = "myapp_us_east"
}

resource "aws_elastic_beanstalk_application" "myapp_eu_west" {
  count = var.region == "eu-west-1" ? 1 : 0
  name  = "myapp_eu_west"
}

resource "aws_elastic_beanstalk_environment" "myenv_us_east" {
  count             = var.region == "us-east-1" ? 1 : 0
  name              = "myenv_us_east"
  application       = aws_elastic_beanstalk_application.myapp_us_east[0].name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.8"
  instance_profile  = aws_iam_instance_profile.eb_ec2_profile.name
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }
}

resource "aws_elastic_beanstalk_environment" "myenv_eu_west" {
  count             = var.region == "eu-west-1" ? 1 : 0
  name              = "myenv_eu_west"
  application       = aws_elastic_beanstalk_application.myapp_eu_west[0].name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.8"
  instance_profile  = aws_iam_instance_profile.eb_ec2_profile.name
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }
}

resource "aws_route53_zone" "primary" {
  name = var.domain_name
}

resource "aws_route53_record" "us_east_alias" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "us-east-1.${var.domain_name}"
  type    = "A"
  alias {
    name                   = aws_elastic_beanstalk_environment.myenv_us_east[0].cname
    zone_id                = aws_elastic_beanstalk_environment.myenv_us_east[0].cname_prefix
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "eu_west_alias" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "eu-west-1.${var.domain_name}"
  type    = "A"
  alias {
    name                   = aws_elastic_beanstalk_environment.myenv_eu_west[0].cname
    zone_id                = aws_elastic_beanstalk_environment.myenv_eu_west[0].cname_prefix
    evaluate_target_health = false
  }
}
```

### Notes

- The `count` attribute is used to ensure that resources are only created in the specified region.
- The `aws_iam_role` and `aws_iam_instance_profile` resources are created once and reused across both regions.
- The `aws_route53_record` resources create CNAME records that point to the Elastic Beanstalk environments in their respective regions.
- Ensure that the `domain_name` variable is set to your actual domain name.
- The `password` for the RDS instances is hardcoded for simplicity; in a production environment, consider using AWS Secrets Manager or another secure method to manage database credentials.

