### Description

The Terraform program below configures a blue/green deployment using AWS Route 53 to direct traffic between two separate environments (`blue` and `green`). Both environments are connected to a shared Amazon RDS database named `myapp_db`. The configuration includes:

- **AWS Provider Configuration**: Sets up the AWS provider with a specified region.
- **IAM Role and Instance Profile**: Creates an IAM role and instance profile named `eb_ec2_profile`.
- **RDS Database**: Sets up a shared RDS database named `myapp_db`.
- **Route 53 Hosted Zone**: Creates a hosted zone for domain management.
- **Route 53 Health Checks**: Configures health checks for both environments.
- **Route 53 Record Sets**: Sets up weighted record sets with failover routing policies to manage traffic between the blue and green environments.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-west-2"
}

variable "domain_name" {
  description = "The domain name for the Route 53 hosted zone"
  default     = "example.com"
}

variable "db_instance_class" {
  description = "The instance class for the RDS database"
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "The database engine for the RDS database"
  default     = "mysql"
}

variable "db_username" {
  description = "The username for the RDS database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the RDS database"
  sensitive   = true
  default     = "password123"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

resource "aws_rds_instance" "myapp_db" {
  identifier              = "myapp_db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  username                = var.db_username
  password                = var.db_password
  allocated_storage       = 20
  skip_final_snapshot     = true
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds_subnet_group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_route53_hosted_zone" "main" {
  name = var.domain_name
}

resource "aws_route53_health_check" "blue_health_check" {
  fqdn                = "blue.${var.domain_name}"
  port                = 80
  type                = "HTTP"
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
  enable_sni          = true
  measure_latency     = true
  insufficient_data_health_status = "Healthy"
}

resource "aws_route53_health_check" "green_health_check" {
  fqdn                = "green.${var.domain_name}"
  port                = 80
  type                = "HTTP"
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
  enable_sni          = true
  measure_latency     = true
  insufficient_data_health_status = "Healthy"
}

resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_hosted_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  health_check_id = aws_route53_health_check.blue_health_check.id

  set_identifier = "blue"
  weight         = 100
  failover       = "PRIMARY"
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_hosted_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  health_check_id = aws_route53_health_check.green_health_check.id

  set_identifier = "green"
  weight         = 0
  failover       = "SECONDARY"
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured with a default region of `us-west-2`.
- **IAM Role and Instance Profile**: An IAM role and instance profile named `eb_ec2_profile` are created to allow EC2 instances to assume the role.
- **RDS Database**: A shared RDS MySQL database named `myapp_db` is set up with a default instance class of `db.t3.micro`.
- **Route 53 Hosted Zone**: A hosted zone for the domain `example.com` is created.
- **Route 53 Health Checks**: Health checks are configured for both the `blue` and `green` environments to monitor their availability.
- **Route 53 Record Sets**: Weighted record sets with failover routing policies are set up to manage traffic between the blue and green environments. The primary environment (`blue`) receives 100% of the traffic, while the secondary environment (`green`) is ready to take over if the primary fails.

This configuration ensures that traffic is directed to the healthy environment, providing a robust blue/green deployment strategy.

