### Description

The Terraform program below provisions a scalable web application using AWS services. It includes the following components:

1. **AWS Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Role and Policy**: Creates an IAM role with necessary permissions for the EC2 instances to access other AWS services.
3. **Security Group**: Sets up a security group to allow HTTP and SSH traffic.
4. **Auto Scaling Group**: Deploys and scales EC2 instances running the web application.
5. **Launch Template**: Defines the configuration for the EC2 instances, including the AMI ID, instance type, and user data script to install and run the web application.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to use"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2
}

variable "key_name" {
  description = "The name of the SSH key pair to use for the EC2 instances"
  default     = ""
}

variable "web_app_url" {
  description = "The URL of the web application package to download and install"
  default     = "https://example.com/webapp.tar.gz"
}

resource "aws_iam_role" "ec2_role" {
  name = "webapp-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "ec2_policy" {
  name = "webapp-ec2-policy"
  role = aws_iam_role.ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_security_group" "webapp_sg" {
  name        = "webapp-sg"
  description = "Security group for web application"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "webapp_lt" {
  name          = "webapp-launch-template"
  image_id      = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name

  iam_instance_profile {
    name = aws_iam_role.ec2_role.name
  }

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y wget
              wget ${var.web_app_url}
              tar -xzf webapp.tar.gz
              cd webapp
              ./install.sh
              ./start.sh
              EOF
}

resource "aws_autoscaling_group" "webapp_asg" {
  name                 = "webapp-asg"
  launch_template      = aws_launch_template.webapp_lt.id
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2
  vpc_zone_identifier  = [var.subnet_id]
  target_group_arns    = [aws_lb_target_group.webapp_tg.arn]
  health_check_type    = "ELB"
  health_check_grace_period = 300
}

resource "aws_lb" "webapp_lb" {
  name               = "webapp-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [var.subnet_id]
}

resource "aws_lb_target_group" "webapp_tg" {
  name     = "webapp-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "webapp_listener" {
  load_balancer_arn = aws_lb.webapp_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.webapp_tg.arn
  }
}
```

### Notes

- **Variables**: The configuration uses several variables to make it flexible. Default values are provided for most variables, but some, like `key_name`, `vpc_id`, and `subnet_id`, need to be set according to your AWS environment.
- **Security**: Ensure that the security group rules are appropriate for your use case. The example allows HTTP and SSH access from anywhere (`0.0.0.0/0`), which is not recommended for production environments.
- **User Data**: The user data script assumes that the web application package can be downloaded via `wget` and that there are `install.sh` and `start.sh` scripts to set up and start the application. Adjust these commands based on your application's requirements.
- **IAM Role**: The IAM role provides basic logging permissions. You may need to adjust the policies based on the specific AWS services your application interacts with.

