### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "github_owner" {
  description = "The owner of the GitHub repository"
  default     = "your-github-owner"
}

variable "github_repo" {
  description = "The name of the GitHub repository"
  default     = "your-github-repo"
}

variable "github_oauth_token" {
  description = "The OAuth token for accessing the GitHub repository"
  type        = string
  sensitive   = true
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
  role       = aws_iam_role.codebuild_role.name
}

resource "aws_s3_bucket" "codebuild_cache" {
  bucket = "codebuild-cache-${random_string.cache_suffix.result}"
  acl    = "private"
}

resource "random_string" "cache_suffix" {
  length  = 8
  special = false
}

resource "aws_codebuild_project" "example" {
  name         = "example-codebuild-project"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_owner}/${var.github_repo}.git"
    auth {
      type     = "OAUTH"
      resource = var.github_oauth_token
    }
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:6.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    environment_variable {
      name  = "EXAMPLE_VAR"
      value = "example-value"
    }
  }

  cache {
    type  = "S3"
    location = "${aws_s3_bucket.codebuild_cache.bucket}/cache"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  logs_config {
    cloudwatch_logs {
      status   = "ENABLED"
      group_name = "/aws/codebuild/example-codebuild-project"
      stream_name = "logs"
    }
  }
}
```

