### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "project_name" {
  description = "The name of the CodeBuild project"
  type        = string
  default     = "example-codebuild-project"
}

variable "source_location" {
  description = "The location of the source code (e.g., S3 bucket)"
  type        = string
  default     = "my-s3-bucket/my-source-code.zip"
}

variable "service_role_arn" {
  description = "The ARN of the IAM role for CodeBuild"
  type        = string
  default     = ""
}

resource "aws_iam_role" "codebuild_role" {
  name = "${var.project_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
  role       = aws_iam_role.codebuild_role.name
}

resource "aws_codebuild_project" "example" {
  name         = var.project_name
  service_role = var.service_role_arn != "" ? var.service_role_arn : aws_iam_role.codebuild_role.arn

  source {
    type            = "S3"
    location        = var.source_location
    buildspec       = "buildspec.yml"
    auth {
      type = "OAUTH"
