  description = "Indicates if the bot is child-directed"
  type        = bool
  default     = true
}

resource "aws_iam_role" "lex_role" {
  name = "${var.bot_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lex_policy" {
  role       = aws_iam_role.lex_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonLexRunBotsOnly"
}

resource "aws_lex_slot_type" "pizza_size" {
  name        = "PizzaSize"
  enumeration_value {
    value = "Small"
  }
  enumeration_value {
    value = "Medium"
  }
  enumeration_value {
    value = "Large"
  }
}

resource "aws_lex_slot_type" "pizza_topping" {
  name        = "PizzaTopping"
  enumeration_value {
    value = "Pepperoni"
  }
  enumeration_value {
    value = "Mushrooms"
  }
  enumeration_value {
    value = "Cheese"
  }
}

resource "aws_lex_intent" "order_pizza" {
  name           = "OrderPizza"
  sample_utterance = ["I want a pizza", "Can I have a pizza please"]
  fulfillment_activity {
    type = "ReturnIntent"
  }
  slot {
    name               = "PizzaSize"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.pizza_size.name
    sample_utterances  = ["I want a small pizza", "Medium pizza sounds good", "Large pizza please"]
    elicitation_prompt {
      messages {
        content_type = "PlainText"
        content      = "What size pizza would you like?"
      }
      max_attempts = 2
    }
  }
  slot {
    name               = "PizzaTopping"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.pizza_topping.name
    sample_utterances  = ["With pepperoni", "Add mushrooms", "Just cheese"]
    elicitation_prompt {
      messages {
        content_type = "PlainText"
        content      = "What toppings would you like?"
      }
      max_attempts = 2
    }
  }
}

resource "aws_lex_bot" "kids_pizza_bot" {
  name                  = var.bot_name
  locale                = var.locale
  child_directed        = var.child_directed
  abort_statement {
    message {
      content_type = "PlainText"
      content      = "I'm sorry, I didn't understand that."
    }
  }
  clarification_prompt {
    messages {
      content_type = "PlainText"
      content      = "Can you please repeat that?"
    }
    max_attempts = 2
  }
  intent {
    intent_name = aws_lex_intent.order_pizza.name
    intent_version = "$LATEST"
  }
  voice_id            = "Joanna"
  process_behavior    = "BUILD"
  idle_session_ttl_in_seconds = 300
  clarification_prompt {
    messages {
      content_type = "PlainText"
      content      = "I didn't understand that. Can you please repeat?"
    }
    max_attempts = 2
  }
  abort_statement {
    messages {
      content_type = "PlainText"
      content      = "I'm sorry, I didn't understand that."
    }
  }
  conversation_logs {
    log_settings {
      destination = "CLOUDWATCH_LOGS"
      log_type    = "TEXT_LOG"
    }
    log_settings {
      destination = "CLOUDWATCH_LOGS"
      log_type    = "AUDIO_LOG"
    }
  }
  role_arn = aws_iam_role.lex_role.arn
}
```

