  source_code_hash = filebase64sha256("path/to/your/deployment/package.zip")

  environment {
    variables = {
      PIZZA_API_URL = "https://api.example.com/pizza"
    }
  }
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "OrderPizzaBotRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "OrderPizzaBotPolicy"
  description = "Policy for OrderPizza Lex bot"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "lambda:InvokeFunction"
        ]
        Effect   = "Allow"
        Resource = aws_lambda_function.order_pizza_lambda.arn
      },
    ]
  })
}

# Attach IAM Policy to Lex Bot Role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

# Lex Bot
resource "aws_lex_bot" "order_pizza_bot" {
  name                  = "OrderPizzaBot"
  locale                = "en-US"
  child_directed        = false
  voice_id              = "Joanna"
  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Sorry, I can't help with that."
    }
  }
  clarification_prompt {
    max_attempts = 2
    messages {
      content_type = "PlainText"
      content      = "I didn't understand that. Can you please repeat?"
    }
  }
  intents {
    intent_name     = "OrderPizzaIntent"
    intent_version  = "$LATEST"
  }
  process_behavior = "BUILD"
  role_arn         = aws_iam_role.lex_bot_role.arn
}

# Lex Intent
resource "aws_lex_intent" "order_pizza_intent" {
  name               = "OrderPizzaIntent"
  sample_utterances  = ["I want to order a pizza", "Can I order a pizza?"]
  fulfillment_activity {
    type = "ReturnIntent"
  }
  confirmation_prompt {
    max_attempts = 2
    messages {
      content_type = "PlainText"
      content      = "Is this correct?"
    }
  }
  rejection_statement {
    message {
      content_type = "PlainText"
      content      = "Okay, let's try again."
    }
  }
  follow_up_prompt {
    prompt {
      max_attempts = 2
      messages {
        content_type = "PlainText"
        content      = "Do you have any other requests?"
      }
    }
    rejection_statement {
      message {
        content_type = "PlainText"
        content      = "No problem, we'll proceed without that."
      }
    }
  }
  slots {
    name            = "PizzaType"
    slot_type       = "AMAZON.FoodItem"
    value_elicitation_prompt {
      max_attempts = 2
      messages {
        content_type = "PlainText"
        content      = "What type of pizza would you like?"
      }
    }
    sample_utterances = ["Margherita", "Pepperoni", "Veggie"]
  }
  slots {
    name            = "Quantity"
    slot_type       = "AMAZON.NUMBER"
    value_elicitation_prompt {
      max_attempts = 2
      messages {
        content_type = "PlainText"
        content      = "How many pizzas would you like?"
      }
    }
  }
}
```

### Notes
- Replace `"path/to/your/deployment/package.zip"` with the actual path to your Lambda deployment package.
- Ensure that the Lambda function code is correctly packaged and uploaded.
- Adjust the `PIZZA_API_URL` environment variable in the Lambda function to point to your actual pizza ordering API endpoint.
- The Lex bot and intent are configured to handle basic pizza ordering. You may need to customize the intents, slots, and fulfillment logic based on your specific requirements.

