  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_ids" {
  description = "A list of security group IDs for the Elasticsearch domain"
  type        = list(string)
  default     = ["sg-12345678"]
}

resource "aws_iam_role" "firehose_role" {
  name = "${var.firehose_name}-role"

