  default     = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the delivery stream will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "A list of subnet IDs within the VPC"
  type        = list(string)
}

variable "security_group_ids" {
  description = "A list of security group IDs for the delivery stream"
  type        = list(string)
}

variable "opensearch_domain_arn" {
  description = "The ARN of the OpenSearch domain"
  type        = string
}

variable "iam_role_name" {
  description = "The name of the IAM role for the delivery stream"
  type        = string
  default     = "firehose-delivery-stream-role"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_delivery_stream_policy" {
  name = "${aws_iam_role.firehose_delivery_stream_role.name}-policy"
  role = aws_iam_role.firehose_delivery_stream_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet"
        ],
        Effect = "Allow",
        Resource = var.opensearch_domain_arn
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ],
        Effect = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-to-opensearch"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn         = var.opensearch_domain_arn
    index_name         = "firehose-index"
    type_name          = "_doc"
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    buffering_hints {
      interval_in_seconds = 60
      size_in_mbs         = 5
    }
    s3_configuration {
      role_arn = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn = "arn:aws:s3:::your-backup-bucket"
      prefix   = "firehose-backup/"
    }
    vpc_configuration {
      subnet_ids         = var.subnet_ids
      security_group_ids = var.security_group_ids
      role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    }
  }

  tags = {
    Name = "FirehoseToOpenSearch"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), but it can be overridden using the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the deployment:
   - `vpc_id`: The ID of the VPC where the delivery stream will be deployed.
   - `subnet_ids`: A list of subnet IDs within the VPC.
   - `security_group_ids`: A list of security group IDs for the delivery stream.
   - `opensearch_domain_arn`: The ARN of the OpenSearch domain.
   - `iam_role_name`: The name of the IAM role for the delivery stream.

3. **IAM Role and Policy**: An IAM role is created for the Kinesis Firehose delivery stream with a trust relationship allowing Firehose to assume the role. An attached policy grants necessary permissions for Firehose to interact with OpenSearch and CloudWatch Logs.

4. **Kinesis Firehose Delivery Stream**: The delivery stream is configured to deliver data to an OpenSearch destination. It includes:
   - Elasticsearch configuration with buffering hints and S3 backup configuration.
   - VPC configuration specifying subnets, security groups, and the IAM role for VPC access.

5. **Tags**: A tag is added to the delivery stream for easy identification.

This configuration ensures that the Kinesis Firehose delivery stream is properly set up to deliver data to an OpenSearch destination within a specified VPC, with appropriate IAM roles and policies in place.

