### Description

The Terraform program below configures an Active-Active Failover policy using AWS Route 53 resources. It includes two health checks named "primary_health_check" and "secondary_health_check" for two different FQDNs. The DNS records will be managed under a Route 53 hosted zone named "main". The program also creates necessary IAM roles and policies to allow Route 53 to perform health checks.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "primary_fqdn" {
  description = "FQDN for the primary resource"
  default     = "primary.example.com"
}

variable "secondary_fqdn" {
  description = "FQDN for the secondary resource"
  default     = "secondary.example.com"
}

resource "aws_iam_role" "route53_health_check_role" {
  name = "Route53HealthCheckRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "route53_health_check_policy" {
  name        = "Route53HealthCheckPolicy"
  description = "Policy allowing Route 53 to perform health checks"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "elasticloadbalancing:DescribeInstanceHealth",
          "elasticloadbalancing:DescribeLoadBalancers",
          "route53:GetHealthCheckStatus"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "route53_health_check_policy_attachment" {
  role       = aws_iam_role.route53_health_check_role.name
  policy_arn = aws_iam_policy.route53_health_check_policy.arn
}

resource "aws_route53_hosted_zone" "main" {
  name          = "example.com"
  caller_reference = "main-zone-${timestamp()}"
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn                = var.primary_fqdn
  port                = 80
  type                = "HTTP"
  resource_path       = "/"
  request_interval    = 30
  failure_threshold   = 3
  measure_latency     = true
  enable_sni          = true
  insufficient_data_health_status = "Healthy"
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn                = var.secondary_fqdn
  port                = 80
  type                = "HTTP"
  resource_path       = "/"
  request_interval    = 30
  failure_threshold   = 3
  measure_latency     = true
  enable_sni          = true
  insufficient_data_health_status = "Healthy"
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_hosted_zone.main.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.primary_health_check.id

  target_failover {
    type              = "PRIMARY"
    on_failure        = "ROUTE"
  }

  target_failover {
    type              = "SECONDARY"
    on_failure        = "ROUTE"
  }

  records = ["192.168.1.1"]
}

resource "aws_route53_record" "secondary_record" {
  zone_id = aws_route53_hosted_zone.main.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.secondary_health_check.id

  target_failover {
    type              = "PRIMARY"
    on_failure        = "ROUTE"
  }

  target_failover {
    type              = "SECONDARY"
    on_failure        = "ROUTE"
  }

  records = ["192.168.1.2"]
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **Variables**: Two variables, `primary_fqdn` and `secondary_fqdn`, are defined with default values.
3. **IAM Role and Policy**: An IAM role (`Route53HealthCheckRole`) and policy (`Route53HealthCheckPolicy`) are created to allow Route 53 to perform health checks.
4. **Route 53 Hosted Zone**: A Route 53 hosted zone named `example.com` is created.
5. **Health Checks**: Two health checks (`primary_health_check` and `secondary_health_check`) are configured for the specified FQDNs.
6. **DNS Records**: Two DNS records (`primary_record` and `secondary_record`) are created with failover routing policies to achieve active-active failover.

This configuration ensures that if the primary resource becomes unhealthy, traffic will automatically be routed to the secondary resource, and vice versa.

