### Description

The Terraform program defined below will create a Route 53 traffic policy that can be used to manage DNS traffic routing. The traffic policy will be of type "simple" and will direct traffic to two different health-checked endpoints based on their health status. The program includes the necessary AWS provider configuration, IAM role creation for Route 53 operations, and the definition of the traffic policy itself.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "traffic_policy_name" {
  description = "The name of the Route 53 traffic policy"
  default     = "example-traffic-policy"
}

variable "endpoint1_domain_name" {
  description = "The domain name of the first endpoint"
  default     = "endpoint1.example.com"
}

variable "endpoint2_domain_name" {
  description = "The domain name of the second endpoint"
  default     = "endpoint2.example.com"
}

resource "aws_iam_role" "route53_traffic_policy_role" {
  name = "Route53TrafficPolicyRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "route53_traffic_policy_policy" {
  name        = "Route53TrafficPolicyPolicy"
  description = "Policy for Route 53 traffic policy operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "route53:GetHostedZone",
          "route53:ListResourceRecordSets",
          "route53:ChangeResourceRecordSets",
          "route53:CreateHealthCheck",
          "route53:GetHealthCheck",
          "route53:UpdateHealthCheck",
          "route53:DeleteHealthCheck"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "route53_traffic_policy_policy_attachment" {
  role       = aws_iam_role.route53_traffic_policy_role.name
  policy_arn = aws_iam_policy.route53_traffic_policy_policy.arn
}

resource "aws_route53_traffic_policy" "example" {
  name     = var.traffic_policy_name
  document = jsonencode({
    AWSPolicyFormatVersion = "2015-10-01"
    RecordType             = "A"
    StartEndpoint          = "PrimaryEndpoint"
    Endpoints              = {
      PrimaryEndpoint = {
        Type = "simple"
        RecordType = "A"
        TTL = 300
        Region = "us-east-1"
        HealthCheck = {
          FullyQualifiedDomainName = var.endpoint1_domain_name
        }
      }
      SecondaryEndpoint = {
        Type = "simple"
        RecordType = "A"
        TTL = 300
        Region = "us-east-1"
        HealthCheck = {
          FullyQualifiedDomainName = var.endpoint2_domain_name
        }
      }
    }
    Rules = {
      DefaultRule = {
        Type = "failover"
        Primary = {
          EndpointReference = "PrimaryEndpoint"
        }
        Secondary = {
          EndpointReference = "SecondaryEndpoint"
        }
      }
    }
  })
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-east-1`), which can be overridden using the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the traffic policy name, endpoint domain names, and region.

3. **IAM Role and Policy**: An IAM role (`Route53TrafficPolicyRole`) is created with a trust policy allowing Route 53 to assume it. An IAM policy (`Route53TrafficPolicyPolicy`) is defined to grant necessary permissions for Route 53 operations, and this policy is attached to the IAM role.

4. **Route 53 Traffic Policy**: A Route 53 traffic policy is created with a simple failover rule. The policy directs traffic to two endpoints (`PrimaryEndpoint` and `SecondaryEndpoint`) based on their health status. Each endpoint has a health check associated with it.

This Terraform configuration is deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

