### Description

The Terraform program below sets up an AWS provider for a specified region and retrieves the current caller identity. It optionally fetches the latest stable ECR image tagged as 'stable' from a specified repository. Local variables for image tag, AWS tags, and workspace name are defined. An EKS module is instantiated with configurations for cluster setup, IAM policies, instance types, and node count. Information about the created EKS cluster and its authentication data is retrieved. Finally, Helm and Kubernetes providers are configured using the EKS cluster's details for cluster communication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "ecr_repository_name" {
  description = "The name of the ECR repository"
  default     = ""
}

variable "eks_cluster_name" {
  description = "The name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "eks_node_group_name" {
  description = "The name of the EKS node group"
  default     = "my-eks-node-group"
}

variable "eks_instance_type" {
  description = "The instance type for the EKS nodes"
  default     = "t3.medium"
}

variable "eks_min_size" {
  description = "The minimum size of the EKS node group"
  default     = 1
}

variable "eks_max_size" {
  description = "The maximum size of the EKS node group"
  default     = 3
}

variable "eks_desired_size" {
  description = "The desired size of the EKS node group"
  default     = 2
}

locals {
  image_tag = "stable"
  aws_tags  = {
    Environment = "production"
    Workspace   = var.workspace_name
  }
  workspace_name = "default"
}

data "aws_caller_identity" "current" {}

data "aws_ecr_image" "latest_stable" {
  count = var.ecr_repository_name != "" ? 1 : 0
  repository_name = var.ecr_repository_name
  image_tag       = local.image_tag
}

module "eks_cluster" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 18.0"

  cluster_name    = var.eks_cluster_name
  cluster_version = "1.24"
  subnets         = ["subnet-12345678", "subnet-87654321"]
  vpc_id          = "vpc-12345678"
  manage_iam_policies = true

  worker_groups = [
    {
      name                 = var.eks_node_group_name
      instance_type        = var.eks_instance_type
      asg_min_size         = var.eks_min_size
      asg_max_size         = var.eks_max_size
      asg_desired_capacity = var.eks_desired_size
      iam_role_name        = "eks-worker-role"
    },
  ]

  tags = local.aws_tags
}

data "aws_eks_cluster" "cluster" {
  name = module.eks_cluster.cluster_name
}

data "aws_eks_cluster_auth" "cluster" {
  name = module.eks_cluster.cluster_name
}

provider "helm" {
  kubernetes {
    host                   = data.aws_eks_cluster.cluster.endpoint
    token                  = data.aws_eks_cluster_auth.cluster.token
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.cluster.certificate_authority[0].data)
  }
}

provider "kubernetes" {
  host                   = data.aws_eks_cluster.cluster.endpoint
  token                  = data.aws_eks_cluster_auth.cluster.token
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.cluster.certificate_authority[0].data)
}
```

### Explanation

1. **AWS Provider Configuration**: The AWS provider is configured with a specified region.
2. **Variables**: Variables are defined for the region, ECR repository name, EKS cluster name, node group name, instance type, and node counts.
3. **Local Variables**: Local variables for the image tag, AWS tags, and workspace name are defined.
4. **Caller Identity**: The `aws_caller_identity` data source retrieves the current caller identity.
5. **ECR Image**: The `aws_ecr_image` data source fetches the latest stable ECR image if the repository name is provided.
6. **EKS Module**: The EKS module is instantiated with configurations for cluster setup, IAM policies, instance types, and node count.
7. **EKS Cluster Data**: The `aws_eks_cluster` data source retrieves information about the created EKS cluster.
8. **EKS Cluster Auth Data**: The `aws_eks_cluster_auth` data source retrieves the authentication data for the EKS cluster.
9. **Helm and Kubernetes Providers**: The Helm and Kubernetes providers are configured using the EKS cluster's details for cluster communication.

