2. **IAM Role**: Creates an IAM role with a trust relationship allowing the EKS cluster to assume this role.
3. **IAM Policy**: Defines an IAM policy with permissions to access the EKS cluster and a specific namespace.
4. **IAM Role Policy Attachment**: Attaches the defined policy to the IAM role.

### Terraform HCL Script

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "eks_cluster_name" {
  description = "The name of the EKS cluster"
  type        = string
  default     = "example-cluster"
}

variable "policy_arn" {
  description = "The ARN of the IAM policy to attach to the role"
  type        = string
  default     = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

variable "principal_arn" {
  description = "The ARN of the principal (e.g., another IAM role or user)"
  type        = string
  default     = "arn:aws:iam::123456789012:role/example-principal-role"
}

variable "namespace" {
  description = "The namespace to which the policy is scoped"
  type        = string
  default     = "default"
}

resource "aws_iam_role" "eks_access_role" {
  name = "eks-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = var.principal_arn
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eks_namespace_policy" {
  name        = "eks-namespace-policy"
  description = "Policy to access a specific namespace in the EKS cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "eks:DescribeCluster",
          "eks:ListClusters"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "kubernetes:Describe*",
          "kubernetes:Get*",
          "kubernetes:List*",
          "kubernetes:Watch*"
        ]
        Resource = [
          "arn:aws:eks:${var.region}:${data.aws_caller_identity.current.account_id}:cluster/${var.eks_cluster_name}",
          "arn:aws:eks:${var.region}:${data.aws_caller_identity.current.account_id}:namespace/${var.namespace}"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_access_policy_attachment" {
  role       = aws_iam_role.eks_access_role.name
  policy_arn = aws_iam_policy.eks_namespace_policy.arn
}

data "aws_caller_identity" "current" {}
```

### Explanation

- **Provider Configuration**: Sets the AWS region to `us-west-2`. You can change this to your preferred region.
- **Variables**: 
  - `eks_cluster_name`: The name of the EKS cluster.
  - `policy_arn`: The ARN of the IAM policy to attach to the role.
  - `principal_arn`: The ARN of the principal (e.g., another IAM role or user).
  - `namespace`: The namespace to which the policy is scoped.
- **IAM Role**: Creates an IAM role named `eks-access-role` with a trust relationship allowing both the EKS service and the specified principal to assume the role.
- **IAM Policy**: Defines an IAM policy named `eks-namespace-policy` that grants permissions to describe and list clusters, and to perform Kubernetes actions on the specified namespace.
- **IAM Role Policy Attachment**: Attaches the defined policy to the IAM role.
- **Data Source**: Retrieves the current AWS account ID using `aws_caller_identity`.

This script ensures that the IAM role has the necessary permissions to access the specified EKS cluster and namespace, and it can be assumed by the specified principal.

