### Description

The Terraform script provided below sets up an AWS EKS (Elastic Kubernetes Service) cluster with pod identity management. The script includes the following components:

1. **IAM Policy Document**: A policy document named "example" that allows EKS pods to assume a specific IAM role.
2. **IAM Role**: An IAM role named "example" that uses the policy document created above.
3. **S3 Read-Only Access Policy**: Attaches an AWS-managed policy for S3 read-only access to the IAM role.
4. **EKS Pod Identity Association**: Links the IAM role to a specific EKS cluster, namespace, and service account.

This setup ensures that pods running in the specified EKS cluster can assume the IAM role and access AWS resources like S3 with the permissions defined in the attached policies.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# Define the IAM policy document for assuming a role by EKS pods
data "aws_iam_policy_document" "example" {
  statement {
    effect = "Allow"

    actions = [
      "sts:AssumeRoleWithWebIdentity",
    ]

    resources = ["arn:aws:iam::*:role/example"]

    condition {
      test     = "StringEquals"
      variable = "eks.amazonaws.com/role-arn"
      values   = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/example"]
    }

    condition {
      test     = "StringLike"
      variable = "eks.amazonaws.com/principal"
      values   = ["system:serviceaccount:example:example"]
    }
  }
}

# Create the IAM role
resource "aws_iam_role" "example" {
  name               = "example"
  assume_role_policy = data.aws_iam_policy_document.example.json
}

# Attach the S3 read-only access policy to the IAM role
resource "aws_iam_role_policy_attachment" "s3_read_only" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.example.name
}

# Define the EKS pod identity association
resource "aws_iam_openid_connect_provider" "example" {
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [data.aws_eks_cluster.example.identity[0].oidc[0].issuer[0].split("://")[1].split("/")[0]]
