### Description

The Terraform configuration below sets up an AWS IAM role named `demo_eks` specifically for an Amazon EKS cluster. This role will have the necessary permissions to assume roles for EKS services and will have the `AmazonEKSClusterPolicy` and `AmazonEKSVPCResourceController` policies attached. Additionally, the configuration creates an AWS EKS cluster named `demo_eks` with specified VPC configurations. Proper dependency handling ensures that the IAM role permissions are correctly applied before managing the EKS cluster.

### Terraform Configuration

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "eks_cluster_name" {
  description = "The name of the EKS cluster"
  default     = "demo_eks"
}

resource "aws_iam_role" "demo_eks" {
  name = var.eks_cluster_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.demo_eks.name
}

resource "aws_iam_role_policy_attachment" "AmazonEKSVPCResourceController" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.demo_eks.name
}

resource "aws_vpc" "demo_eks" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "demo_eks" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.demo_eks.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_eks_cluster" "demo_eks" {
  name     = var.eks_cluster_name
  role_arn = aws_iam_role.demo_eks.arn

  vpc_config {
    subnet_ids = aws_subnet.demo_eks[*].id
  }

  depends_on = [
    aws_iam_role_policy_attachment.AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.AmazonEKSVPCResourceController,
  ]
}
```

