### Description

The Terraform program below will create an IAM policy document that allows the `s3.amazonaws.com` service to publish to an SNS topic for S3 event notifications. The policy will specify the actions as `SNS:Publish` and set the resource to the ARN of the SNS topic `s3-event-notification-topic`. A condition will be applied to allow this action only if the source ARN matches the ARN of the specified S3 bucket.

Next, the program will create an SNS topic named `s3-event-notification-topic` with the generated IAM policy. It will also set up an S3 bucket named `your-bucket-name` and configure it to send notifications to the SNS topic for `s3:ObjectCreated:*` events with a filter for `.log` suffix.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket"
  default     = "your-bucket-name"
}

variable "sns_topic_name" {
  description = "The name of the SNS topic"
  default     = "s3-event-notification-topic"
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = var.sns_topic_name
}

resource "aws_iam_policy_document" "s3_to_sns_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "SNS:Publish",
    ]

    resources = [
      aws_sns_topic.s3_event_notification_topic.arn,
    ]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.your_bucket.arn]
    }
  }
}

resource "aws_sns_topic_policy" "s3_to_sns_policy_attachment" {
  arn    = aws_sns_topic.s3_event_notification_topic.arn
  policy = data.aws_iam_policy_document.s3_to_sns_policy.json
}

resource "aws_s3_bucket" "your_bucket" {
  bucket = var.bucket_name
}

resource "aws_s3_bucket_notification" "your_bucket_notification" {
  bucket = aws_s3_bucket.your_bucket.id

  topic {
    topic_arn     = aws_sns_topic.s3_event_notification_topic.arn
    events      = ["s3:ObjectCreated:*"]
    filter_suffix = ".log"
  }
}
```

