### Description

The Terraform program defined below will create a custom Virtual Private Cloud (VPC) with a CIDR block of `10.0.0.0/16`. It will then create two subnets in the availability zones `us-east-1a` and `us-east-1b`. Finally, it will launch an EC2 instance in each subnet using the latest Amazon Linux 2 AMI, with a `t2.micro` instance type and an attached EBS volume of 50 GB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_type" {
  description = "Instance type for the EC2 instances"
  default     = "t2.micro"
}

variable "volume_size" {
  description = "Size of the EBS volume in GB"
  default     = 50
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyCustomVPC"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = "us-east-1a"

  tags = {
    Name = "SubnetA"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = "us-east-1b"

  tags = {
    Name = "SubnetB"
  }
}

resource "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "instance_a" {
  ami           = aws_ami.latest_amazon_linux_2.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_a.id

  root_block_device {
    volume_size = var.volume_size
  }

  tags = {
    Name = "InstanceA"
  }
}

resource "aws_instance" "instance_b" {
  ami           = aws_ami.latest_amazon_linux_2.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_b.id

  root_block_device {
    volume_size = var.volume_size
  }

  tags = {
    Name = "InstanceB"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **Variables**: Several variables are defined to allow customization of the VPC CIDR block, subnet CIDR blocks, instance type, and EBS volume size.
3. **VPC Resource**: A VPC is created with the specified CIDR block.
4. **Subnet Resources**: Two subnets are created in `us-east-1a` and `us-east-1b` with the specified CIDR blocks.
5. **AMI Data Source**: The latest Amazon Linux 2 AMI is fetched using a data source.
6. **EC2 Instance Resources**: Two EC2 instances are launched in each subnet using the latest Amazon Linux 2 AMI, with a `t2.micro` instance type and an attached EBS volume of 50 GB.

This configuration is fully deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

