### Description

The Terraform program defined below sets up a Virtual Private Cloud (VPC) with both public and private subnets. It then creates an EC2 Fleet consisting of 5 On-Demand instances and 4 Spot instances using the latest Amazon Linux 2 AMI. The configuration uses Launch Templates to ensure consistency across the fleet.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "Instance type for the EC2 Fleet"
  default     = "t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_block
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2-fleet-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_fleet_policy" {
  role       = aws_iam_role.ec2_fleet_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_launch_template" "fleet_template" {
  name          = "ec2-fleet-template"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "ec2-fleet-instance"
    }
  }
}

resource "aws_iam_instance_profile" "ec2_fleet_profile" {
  name = "ec2-fleet-profile"
  roles = [aws_iam_role.ec2_fleet_role.name]
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_ec2_fleet" "example" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.fleet_template.id
    }

    override {
      instance_type = var.instance_type
      availability_zone = "us-west-2a"
      weighted_capacity = 1
    }

    override {
      instance_type = var.instance_type
      availability_zone = "us-west-2b"
      weighted_capacity = 1
    }

    override {
      instance_type = var.instance_type
      availability_zone = "us-west-2c"
      weighted_capacity = 1
    }
  }

  spot_options {
    allocation_strategy = "lowest-price"
    instance_interruption_behavior = "terminate"
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  target_capacity_specification {
    total_target_capacity = 9
    default_target_capacity_type = "spot"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Variables are defined for the VPC CIDR block, public and private subnet CIDR blocks, and the instance type.
3. **VPC and Subnets**: A VPC is created with a public and private subnet.
4. **Internet Gateway and Route Table**: An internet gateway is attached to the VPC, and a route table is configured to route traffic to the internet through the gateway.
5. **IAM Role and Policy**: An IAM role and policy attachment are created to allow EC2 instances to perform necessary actions.
6. **Launch Template**: A launch template is defined to specify the AMI, instance type, IAM instance profile, and tags.
7. **EC2 Fleet**: An EC2 fleet is created with a mix of 5 On-Demand and 4 Spot instances using the launch template.

This configuration ensures that the infrastructure is consistent and can be easily deployed using Terraform.

