### Description

The Terraform program below will create a Virtual Private Cloud (VPC) with two private subnets. It will also launch two EC2 instances using the latest Amazon Linux 2 AMI in one of the private subnets. These instances will mount an Elastic File System (EFS) for shared storage.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr_blocks" {
  description = "The CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_type" {
  description = "The instance type for the EC2 instances"
  default     = "t3.micro"
}

variable "key_name" {
  description = "The key pair name for SSH access to the EC2 instances"
  type        = string
  default     = ""
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "PrivateSubnet-${count.index + 1}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_iam_role" "ec2_instance_role" {
  name = "EC2InstanceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemClient"
}

resource "aws_security_group" "ec2_instance_sg" {
  name        = "EC2InstanceSG"
  description = "Security group for EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "EC2InstanceSG"
  }
}

resource "aws_efs_file_system" "shared_storage" {
  creation_token = "MySharedStorage"

  tags = {
    Name = "SharedStorage"
  }
}

resource "aws_efs_mount_target" "mount_target" {
  count      = length(aws_subnet.private)
  file_system_id = aws_efs_file_system.shared_storage.id
  subnet_id    = element(aws_subnet.private[*].id, count.index)
  security_groups = [aws_security_group.ec2_instance_sg.id]
}

resource "aws_instance" "web" {
  count         = 2
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type
  subnet_id     = element(aws_subnet.private[*].id, count.index)
  key_name      = var.key_name
  iam_instance_profile = aws_iam_role.ec2_instance_role.name
  vpc_security_group_ids = [aws_security_group.ec2_instance_sg.id]

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y amazon-efs-utils
              mkdir /mnt/efs
              mount -t efs ${aws_efs_file_system.shared_storage.dns_name}:/ /mnt/efs
              EOF

  tags = {
    Name = "WebInstance-${count.index + 1}"
  }
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`).
2. **Variables**: Several variables are defined to allow customization of the VPC CIDR block, private subnet CIDR blocks, instance type, and key pair name.
3. **VPC and Subnets**: A VPC is created with the specified CIDR block. Two private subnets are created within this VPC.
4. **IAM Role and Policy**: An IAM role is created for the EC2 instances, allowing them to access EFS. The necessary policy attachment is also included.
5. **Security Group**: A security group is created to allow SSH access to the EC2 instances.
6. **EFS File System and Mount Targets**: An EFS file system is created, and mount targets are set up for each private subnet.
7. **EC2 Instances**: Two EC2 instances are launched in the private subnets, using the latest Amazon Linux 2 AMI. They are configured to mount the EFS file system at `/mnt/efs`.

This configuration ensures that the EC2 instances have access to shared storage via EFS and are securely placed within a private subnet.

