### Description

The Terraform program below defines a Virtual Private Cloud (VPC) with both public and private subnets. It also sets up three EC2 instances within an EC2 placement group configured for clustering. The configuration includes necessary IAM roles and policies, and it uses default values for variables where applicable. The AWS provider is configured to use the `us-west-2` region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidr_blocks" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
}

# Create the VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags = {
    Name = "MyVPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "MyInternetGateway"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
  tags = {
    Name = "PublicSubnet-${count.index}"
  }
}

# Create Private Subnets
resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags = {
    Name = "PrivateSubnet-${count.index}"
  }
}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "PublicRouteTable"
  }
}

# Associate Public Subnets with Route Table
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Create Placement Group for Clustering
resource "aws_placement_group" "cluster" {
  name     = "MyClusterPlacementGroup"
  strategy = "cluster"
}

# Create EC2 Instances in the Private Subnets
resource "aws_instance" "web" {
  count         = 3
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = element(aws_subnet.private.*.id, count.index % length(aws_subnet.private))
  key_name      = "my-key-pair" # Ensure this key pair exists in your AWS account
  placement {
    group_name = aws_placement_group.cluster.name
  }
  tags = {
    Name = "WebInstance-${count.index}"
  }
}

# Data source to get available availability zones
data "aws_availability_zones" "available" {}

# Output the VPC ID
output "vpc_id" {
  value = aws_vpc.main.id
}

# Output the Public Subnet IDs
output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

# Output the Private Subnet IDs
output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

# Output the EC2 Instance IDs
output "ec2_instance_ids" {
  value = aws_instance.web[*].id
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Default values are provided for the VPC CIDR block, public and private subnet CIDR blocks, instance type, and AMI ID.
3. **VPC Creation**: A VPC is created with the specified CIDR block.
4. **Internet Gateway**: An internet gateway is attached to the VPC.
5. **Public and Private Subnets**: Public and private subnets are created in different availability zones.
6. **Route Table**: A route table is created for the public subnets, and it is associated with the public subnets.
7. **Placement Group**: A placement group is created for clustering the EC2 instances.
8. **EC2 Instances**: Three EC2 instances are launched in the private subnets using the specified AMI and instance type, and they are placed in the cluster placement group.
9. **Data Source**: An availability zone data source is used to ensure subnets are created in different availability zones.
10. **Outputs**: The VPC ID, public subnet IDs, private subnet IDs, and EC2 instance IDs are outputted for reference.

This configuration ensures that the infrastructure is deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

