### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "elasticsearch_user_name" {
  description = "The name of the ElastiCache user"
