  description = "The access string for the ElastiCache user"
  type        = string
  default     = "on ~app::* -@allusers"
}

resource "aws_iam_role" "elasticsearch_role" {
  name = "elasticsearch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "elasticsearch_policy" {
  name = "elasticsearch-policy"
  role = aws_iam_role.elasticsearch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:DescribeUsers",
          "elasticache:CreateUser",
          "elasticache:ModifyUser",
          "elasticache:DeleteUser"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_elasticache_user" "redis_user" {
  user_id         = var.elasticsearch_user_name
  engine          = "REDIS"
  access_string   = var.elasticsearch_user_access_string
  no_passwords    = false
  passwords       = ["yourStrongPassword123"]
  authentication_token_enabled = false
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **IAM Role**: An IAM role named `elasticsearch-role` is created with a trust policy allowing ElastiCache to assume the role.
- **IAM Role Policy**: A policy attached to the IAM role grants permissions for ElastiCache user management operations.
- **ElastiCache User**: An ElastiCache user is created with the specified name, engine (`REDIS`), and access string. The user is configured with a password (`yourStrongPassword123`).

This configuration ensures that the ElastiCache user is properly set up with the necessary permissions and settings. Adjust the `access_string` and `passwords` as needed for your specific use case.

