    Statement = [
      {
        Action = [
          "elasticache:Describe*",
          "elasticache:List*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "elasti_cache_user_policy_attachment" {
  role       = aws_iam_role.elasti_cache_user_role.name
  policy_arn = aws_iam_policy.elasti_cache_user_policy.arn
}

resource "aws_elasticache_user" "elasti_cache_user" {
  user_name = var.elasti_cache_user_name
  engine    = "redis"
  access_string = "on ~app::* -@allusers"
  no_password_required = false
  passwords = ["MySecurePassword123"]

  tags = {
    Name = var.elasti_cache_user_name
  }
}

resource "aws_elasticache_user_group" "elasti_cache_user_group" {
  user_group_id = "${var.elasti_cache_user_name}-group"
  engine        = "redis"

  user_names = [aws_elasticache_user.elasti_cache_user.user_name]
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **IAM Role**: An IAM role named `elasti_cache_user_role` is created, allowing the ElastiCache service to assume this role.
- **IAM Policy**: An IAM policy named `elasti_cache_user_policy` is defined, granting permissions to describe and list ElastiCache resources.
- **ElastiCache User**: An ElastiCache user named `my-elasti-cache-user` is created with the specified IAM role. The user has an access string that allows full access to all applications (`~app::*`) but denies access to all users (`-@allusers`). A password is required for this user.
- **ElastiCache User Group**: An ElastiCache user group is created to manage the user, associating it with the previously created user.

This configuration ensures that the ElastiCache user is properly set up with the necessary permissions and IAM role.

