### Description

The Terraform program below sets up a highly available Amazon Redshift cluster across two availability zones (`us-east-1a` and `us-east-1b`) in the `us-east-1` region. The configuration includes:

1. **VPC and Subnets**: A VPC with public and private subnets spread across the two availability zones.
2. **Security Groups**: Security groups to control inbound and outbound traffic for the Redshift cluster.
3. **IAM Roles**: An IAM role with the necessary permissions for the Redshift cluster to access other AWS services.
4. **Redshift Cluster**: A Redshift cluster configured for high availability with a node type of `dc2.large`, using the specified subnets and security groups.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidr_blocks" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "redshift_node_type" {
  description = "Node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "redshift_cluster_identifier" {
  description = "Identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "redshift_master_username" {
  description = "Master username for the Redshift cluster"
  default     = "admin"
}

variable "redshift_master_user_password" {
  description = "Master user password for the Redshift cluster"
  sensitive   = true
  default     = "SecurePassword123!"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  availability_zone = element(["us-east-1a", "us-east-1b"], count.index)
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidr_blocks, count.index)
  availability_zone = element(["us-east-1a", "us-east-1b"], count.index)
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Allow Redshift traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier      = var.redshift_cluster_identifier
  master_username         = var.redshift_master_username
  master_user_password    = var.redshift_master_user_password
  node_type               = var.redshift_node_type
  cluster_type            = "multi-node"
  number_of_nodes         = 2
  iam_roles               = [aws_iam_role.redshift_role.arn]
  publicly_accessible     = false
  enhanced_vpc_routing    = true
  elastic_ip              = null
  automated_snapshot_retention_period = 7
  port                    = 5439
  vpc_security_group_ids  = [aws_security_group.redshift_sg.id]
  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **Variables**: Several variables are defined to allow customization of the VPC, subnets, Redshift cluster, and credentials.
- **VPC and Subnets**: A VPC is created with public and private subnets in `us-east-1a` and `us-east-1b`.
- **Internet Gateway and Route Table**: An internet gateway is attached to the VPC, and a public route table is associated with the public subnets.
- **Security Group**: A security group is created to allow inbound traffic on port 5439 (Redshift's default port).
- **IAM Role**: An IAM role is created with the necessary permissions for the Redshift cluster to access S3.
- **Redshift Cluster**: A multi-node Redshift cluster is created with two nodes, using the specified subnets, security groups, and IAM role.

This configuration ensures that the Redshift cluster is highly available and can handle failover between the two availability zones.

