### Description

The Terraform program below sets up a 2-node Amazon Redshift cluster in the `us-east-1` region and replicates it to the `us-east-2` region. The program includes the necessary IAM roles and policies for Redshift to access other AWS services. It also configures the required network components such as VPCs, subnets, and security groups.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The type of nodes in the Redshift cluster"
  default     = "dc2.large"
}

variable "master_username" {
  description = "The username for the master database user"
  default     = "admin"
}

variable "master_user_password" {
  description = "The password for the master database user"
  default     = "SecurePassword123!"
}

variable "cluster_subnet_group_name" {
  description = "The name of the Redshift subnet group"
  default     = "my-redshift-subnet-group"
}

variable "security_group_name" {
  description = "The name of the security group for the Redshift cluster"
  default     = "my-redshift-sg"
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "redshift_sg" {
  name        = var.security_group_name
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

