  preferred_maintenance_window = "sun:07:00-sun:07:30"
  snapshot_identifier     = aws_redshift_cluster.primary.snapshot_identifier
  availability_zone       = element(data.aws_availability_zones.available.names, 1)
}

provider "aws" {
  alias  = "secondary"
  region = "us-east-2"
}

resource "aws_redshift_cluster" "replica_us_east_2" {
  provider                  = aws.secondary
  cluster_identifier        = "${var.cluster_identifier}-replica-us-east-2"
  node_type                 = var.node_type
  master_username           = var.master_username
