### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "master_username" {
  description = "The username for the Redshift master user"
  default     = "admin"
}

variable "master_user_password" {
  description = "The password for the Redshift master user"
  type        = string
  sensitive   = true
}

variable "database_name" {
  description = "The name of the database to create on the Redshift cluster"
  default     = "mydb"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "cluster_type" {
  description = "The type of the Redshift cluster (single-node or multi-node)"
  default     = "multi-node"
}

variable "number_of_nodes" {
  description = "The number of nodes in the Redshift cluster"
  default     = 2
}

resource "aws_iam_role" "redshift_role" {
  name = "${var.cluster_identifier}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "redshift_policy" {
  name = "${var.cluster_identifier}-policy"
  role = aws_iam_role.redshift_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:Get*",
          "s3:List*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier = var.cluster_identifier
  master_username    = var.master_username
  master_user_password = var.master_user_password
  database_name      = var.database_name
  node_type          = var.node_type
  cluster_type       = var.cluster_type
  number_of_nodes    = var.number_of_nodes
  iam_roles          = [aws_iam_role.redshift_role.arn]

  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  publicly_accessible  = false
}

resource "aws_security_group" "redshift_sg" {
  name        = "${var.cluster_identifier}-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
  default = true
}

resource "aws_redshift_cluster_parameter_group" "example" {
  name        = "${var.cluster_identifier}-parameter-group"
  family      = "redshift-1.x"
  description = "Custom parameter group for Redshift cluster"

  parameter {
    name  = "query_group"
    value = "example"
  }
}

resource "aws_redshift_cluster_iam_roles" "example" {
  cluster_identifier = aws_redshift_cluster.example.cluster_identifier
  iam_roles          = [aws_iam_role.redshift_role.arn]
}

resource "aws_redshift_resource_policy" "example" {
  resource_arn = aws_redshift_cluster.example.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:DescribeClusters",
          "redshift:DescribeClusterParameters",
          "redshift:DescribeClusterSecurityGroups",
          "redshift:DescribeClusterSnapshots",
          "redshift:DescribeClusterSubnetGroups",
          "redshift:DescribeClusterTracks",
          "redshift:DescribeDefaultClusterParameters",
          "redshift:DescribeEvents",
          "redshift:DescribeHsmClientCertificates",
          "redshift:DescribeHsmConfigurations",
          "redshift:DescribeLoggingStatus",
          "redshift:DescribeNodeConfigurationOptions",
          "redshift:DescribeOrderableClusterOptions",
          "redshift:DescribeReservedNodeOfferings",
          "redshift:DescribeReservedNodes",
          "redshift:DescribeResize",
          "redshift:DescribeScheduledActions",
          "redshift:DescribeSnapshotCopyGrants",
          "redshift:DescribeSnapshotSchedules",
          "redshift:DescribeTableRestoreStatus",
          "redshift:DescribeTags",
          "redshift:DescribeUsageLimits"
        ]
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::123456789012:user/example-user"
        }
      }
    ]
  })
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to customize the Redshift cluster settings, such as the cluster identifier, master username, password, database name, node type, cluster type, and number of nodes.
3. **IAM Role and Policy**: An IAM role and policy are created to allow the Redshift cluster to access S3 resources.
4. **Redshift Cluster**: A Redshift cluster is created with the specified parameters, including the IAM role and security group.
5. **Security Group**: A security group is created to allow inbound traffic on port 5439 (the default Redshift port).
6. **VPC Data Source**: The default VPC is retrieved using a data source.
7. **Parameter Group**: A custom parameter group is created for the Redshift cluster.
8. **IAM Roles Association**: The IAM role is associated with the Redshift cluster.
9. **Resource Policy**: A resource policy is attached to the Redshift cluster to allow specific actions from a specified principal.

This configuration ensures that the Redshift cluster is properly set up with the necessary permissions and security settings.

