  })
}

resource "aws_iam_policy" "cloudwatch_alarm_policy" {
  name        = "cloudwatch-alarm-policy"
  description = "Policy for CloudWatch Alarm"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DeleteAlarms"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_alarm_policy_attachment" {
  role       = aws_iam_role.cloudwatch_alarm_role.name
  policy_arn = aws_iam_policy.cloudwatch_alarm_policy.arn
}

resource "aws_cloudwatch_metric_alarm" "example_alarm" {
  alarm_name          = "ExampleAlarm"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 300
  statistic           = "Average"
  threshold           = 80
  alarm_description   = "This metric monitors CPU utilization."
  alarm_actions       = [aws_sns_topic.example_topic.arn]
  ok_actions          = [aws_sns_topic.example_topic.arn]
  insufficient_data_actions = [aws_sns_topic.example_topic.arn]

  dimensions = {
    InstanceId = "i-1234567890abcdef0"
  }
}

resource "aws_sns_topic" "example_topic" {
  name = "example-topic"
}
```

### Explanation

- **Provider Configuration**: The AWS provider is set up to use the `us-west-2` region.
- **IAM Role**: An IAM role named `cloudwatch-alarm-role` is created with a trust policy allowing CloudWatch to assume it.
- **IAM Policy**: An IAM policy named `cloudwatch-alarm-policy` is created with permissions to manage CloudWatch alarms.
- **IAM Role Policy Attachment**: The policy is attached to the IAM role.
- **CloudWatch Metric Alarm**: A CloudWatch metric alarm is created to monitor the `CPUUtilization` metric for an EC2 instance. The alarm triggers if the average CPU utilization exceeds 80% over two evaluation periods of 5 minutes each.
- **SNS Topic**: An SNS topic is created to handle the alarm actions (alarm, OK, and insufficient data).

This configuration ensures that the CloudWatch alarm is properly set up with the necessary permissions and actions.

