  name = "KinesisToDynamoDBPolicy"
  role = aws_iam_role.kinesis_to_dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:DescribeStream",
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:ListStreams"
        ]
        Effect = "Allow"
        Resource = aws_dynamodb_table.example.arn
      }
    ]
  })
}

resource "aws_kinesis_stream_consumer" "example" {
  stream_arn = aws_kinesis_stream.example.arn
  name       = "MyDynamoDBConsumer"
}

resource "aws_dynamodb_stream" "example" {
  table_name               = aws_dynamodb_table.example.name
  stream_view_type         = "NEW_AND_OLD_IMAGES"
  enable_dynamodb_streaming = true
}

resource "aws_kinesis_stream_to_firehose_delivery_stream" "example" {
  destination_id = "MyDynamoDBDestination"
  delivery_stream_name = aws_kinesis_stream_consumer.example.name
  kinesis_stream_arn = aws_kinesis_stream.example.arn
  iam_role_arn = aws_iam_role.kinesis_to_dynamodb_role.arn
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Two variables are defined for the DynamoDB table name and the Kinesis Data Stream name, with default values provided.
3. **DynamoDB Table**: A DynamoDB table is created with a simple schema.
4. **Kinesis Data Stream**: A Kinesis Data Stream is created with one shard and a retention period of 24 hours.
5. **IAM Role and Policy**: An IAM role is created for the Kinesis Data Stream to access the DynamoDB table. The role has a policy attached that allows the necessary DynamoDB actions.
6. **Kinesis Stream Consumer**: A Kinesis Stream Consumer is created to consume records from the Kinesis Data Stream.
7. **DynamoDB Stream**: The DynamoDB table is configured to have a stream enabled with the view type set to `NEW_AND_OLD_IMAGES`.
8. **Kinesis Stream to Firehose Delivery Stream**: A resource is created to deliver data from the Kinesis Data Stream to the DynamoDB table using the IAM role.

This configuration ensures that the Kinesis Data Stream is properly set up as a streaming destination for the specified DynamoDB table.

