  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
  role       = aws_iam_role.sagemaker_user_role.name
}

resource "aws_sagemaker_user_profile" "example" {
  domain_id             = var.domain_id
  user_profile_name     = var.sagemaker_user_profile_name
  single_sign_on_user_identifier = var.single_sign_on_user_identifier
  single_sign_on_user_value     = var.single_sign_on_user_value

