### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "sagemaker_pipeline_name" {
  description = "The name of the SageMaker pipeline"
  type        = string
  default     = "my-sagemaker-pipeline"
}

variable "role_arn" {
  description = "The ARN of the IAM role that SageMaker will assume"
  type        = string
  default     = ""
}

resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-pipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
  role       = aws_iam_role.sagemaker_role.name
}

resource "aws_sagemaker_pipeline" "example" {
  pipeline_name = var.sagemaker_pipeline_name
  role_arn      = var.role_arn != "" ? var.role_arn : aws_iam_role.sagemaker_role.arn

  pipeline_definition = jsonencode({
    Version = "2020-12-01"
    Steps = [
      {
        Name = "DataProcessingStep"
        Arguments = {
          ProcessingInputs = [
            {
              InputName = "InputData"
              AppManaged = false
              S3Input = {
                S3Uri = "s3://my-bucket/input-data"
                LocalPath = "/opt/ml/processing/input"
                S3DataType = "S3Prefix"
                S3InputMode = "File"
                S3DataDistributionType = "FullyReplicated"
              }
            }
          ]
          ProcessingOutputConfig = {
            Outputs = [
              {
                OutputName = "ProcessedData"
                S3Output = {
                  S3Uri = "s3://my-bucket/processed-data"
                  LocalPath = "/opt/ml/processing/output"
                }
              }
            ]
          }
          ProcessingResources = {
            ClusterConfig = {
              InstanceCount = 1
              InstanceType = "ml.m5.large"
              VolumeSizeInGB = 20
            }
          }
          RoleArn = aws_iam_role.sagemaker_role.arn
        }
        Type = "ProcessingStep"
      },
      {
        Name = "TrainingStep"
        Arguments = {
          TrainingJobDefinition = {
            AlgorithmSpecification = {
              TrainingImage = "763104351884.dkr.ecr.us-west-2.amazonaws.com/xgboost:1.5-1"
              TrainingInputMode = "File"
            }
            InputDataConfig = [
              {
                ChannelName = "train"
                DataSource = {
                  S3DataSource = {
                    S3DataType = "S3Prefix"
                    S3Uri = "s3://my-bucket/processed-data/train"
                    S3DataDistributionType = "FullyReplicated"
                  }
                }
              }
            ]
            OutputDataConfig = {
              S3OutputPath = "s3://my-bucket/model-output"
            }
            ResourceConfig = {
              InstanceCount = 1
              InstanceType = "ml.m5.large"
              VolumeSizeInGB = 20
            }
            RoleArn = aws_iam_role.sagemaker_role.arn
            StoppingCondition = {
              MaxRuntimeInSeconds = 3600
            }
          }
        }
        Type = "TrainingStep"
      },
      {
        Name = "EvaluationStep"
        Arguments = {
          ModelApprovalStatus = "Approved"
          TransformJobDefinition = {
            ModelName = "my-model"
            TransformInput = {
              ContentType = "text/csv"
              DataSource = {
                S3DataSource = {
                  S3DataType = "S3Prefix"
                  S3Uri = "s3://my-bucket/processed-data/test"
                }
              }
            }
            TransformOutput = {
              S3OutputPath = "s3://my-bucket/evaluation-output"
            }
            TransformResources = {
              InstanceCount = 1
              InstanceType = "ml.m5.large"
            }
          }
        }
        Type = "TransformStep"
      }
    ]
  })

  tags = {
    Environment = "production"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Two variables are defined:
   - `sagemaker_pipeline_name`: The name of the SageMaker pipeline.
   - `role_arn`: The ARN of the IAM role that SageMaker will assume. If not provided, it defaults to the created IAM role.
3. **IAM Role**: An IAM role named `sagemaker-pipeline-role` is created with a trust policy allowing SageMaker to assume the role.
4. **IAM Role Policy Attachment**: The `AmazonSageMakerFullAccess` policy is attached to the IAM role.
5. **SageMaker Pipeline**: A SageMaker pipeline is created with three steps:
   - **DataProcessingStep**: Processes input data.
   - **TrainingStep**: Trains a model using the processed data.
   - **EvaluationStep**: Evaluates the trained model.

This configuration ensures that the SageMaker pipeline is set up with the necessary permissions and steps to process, train, and evaluate a model.

