```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "model_name" {
  description = "The name of the SageMaker model"
  type        = string
}

variable "endpoint_config_name" {
  description = "The name of the SageMaker endpoint configuration"
  type        = string
}

variable "instance_type" {
  description = "The instance type for the endpoint"
  type        = string
  default     = "ml.m5.large"
}

variable "initial_instance_count" {
  description = "The initial number of instances for the endpoint"
  type        = number
  default     = 1
}

resource "aws_iam_role" "sagemaker_endpoint_execution_role" {
  name = "${var.endpoint_config_name}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_full_access" {
  role       = aws_iam_role.sagemaker_endpoint_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}

resource "aws_sagemaker_endpoint_configuration" "sagemaker_endpoint_config" {
  name = var.endpoint_config_name

  production_variants {
    initial_instance_count = var.initial_instance_count
    instance_type          = var.instance_type
    model_name             = var.model_name
    variant_name           = "AllTraffic"
  }
}

resource "aws_sagemaker_endpoint" "sagemaker_endpoint" {
