### Description

The Terraform program below will create an Amazon Machine Image (AMI) based on the latest Amazon Linux 2 release. The instance used to create this AMI will have 2 CPUs and 2 cores per thread per core (i.e., hyperthreading enabled). The program includes the necessary AWS provider configuration, IAM roles, and resources to launch an EC2 instance, create an AMI from it, and clean up the instance after the AMI creation.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "c5.large"  # Instance type with 2 vCPUs and supports hyperthreading
}

variable "ami_name" {
  description = "Name for the created AMI"
  default     = "latest-amazon-linux2-ami"
}

variable "key_name" {
  description = "SSH key name for the EC2 instance"
  type        = string
  default     = ""  # Replace with your existing key pair name
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_instance" "ami_builder" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type
  key_name      = var.key_name
  iam_instance_profile = aws_iam_instance_profile.ec2_instance_profile.name

  tags = {
    Name = "AMI-Build-Instance"
  }
}

resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "ec2-instance-profile"
  roles = [aws_iam_role.ec2_instance_role.name]
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_ebs_volume" "root_volume" {
  availability_zone = aws_instance.ami_builder.availability_zone
  size              = 20  # Adjust size as needed
  type              = "gp3"
}

resource "aws_volume_attachment" "root_volume_attachment" {
  device_name = "/dev/sda1"
  volume_id   = aws_ebs_volume.root_volume.id
  instance_id = aws_instance.ami_builder.id
}

resource "aws_ami_from_instance" "ami_from_instance" {
  name               = var.ami_name
  source_instance_id = aws_instance.ami_builder.id
  wait_for_completion = true

  tags = {
    Name = var.ami_name
  }
}

resource "null_resource" "cleanup_instance" {
  provisioner "local-exec" {
    command = "aws ec2 terminate-instances --instance-ids ${aws_instance.ami_builder.id}"
  }

  depends_on = [aws_ami_from_instance.ami_from_instance]
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region. You can change this to any other region as needed.

2. **Variables**:
   - `instance_type`: Specifies the EC2 instance type. The default is `c5.large`, which has 2 vCPUs and supports hyperthreading.
   - `ami_name`: The name for the created AMI.
   - `key_name`: The SSH key name for the EC2 instance. Replace the default value with your existing key pair name.

3. **IAM Role and Policy Attachment**: An IAM role is created for the EC2 instance, and the `AmazonSSMManagedInstanceCore` policy is attached to allow Systems Manager access.

4. **EC2 Instance**: An EC2 instance is launched using the latest Amazon Linux 2 AMI. The instance is associated with the IAM role and profile.

5. **EBS Volume**: An EBS volume is created and attached to the instance to ensure the root volume is properly configured.

6. **AMI Creation**: An AMI is created from the running instance.

7. **Cleanup**: A `null_resource` is used to terminate the instance after the AMI is created.

This configuration ensures that the AMI is created with the specified CPU and core configurations and cleans up the resources afterward.

