### Description

The Terraform program below will create a VPC with one public subnet and two private subnets in AWS. The public subnet will be configured to host a web server, while the private subnets will host an application server and a relational database. The necessary IAM roles and security groups will also be created to ensure proper access control.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  description = "The CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_1_cidr_block" {
  description = "The CIDR block for the first private subnet"
  default     = "10.0.2.0/24"
}

variable "private_subnet_2_cidr_block" {
  description = "The CIDR block for the second private subnet"
  default     = "10.0.3.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_1_cidr_block
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "PrivateSubnet1"
  }
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_2_cidr_block
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name = "PrivateSubnet2"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainInternetGateway"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "WebServerSG"
  description = "Security group for the web server"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "WebServerSG"
  }
}

resource "aws_security_group" "app_server" {
  name        = "AppServerSG"
  description = "Security group for the application server"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AppServerSG"
  }
}

resource "aws_security_group" "database" {
  name        = "DatabaseSG"
  description = "Security group for the database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from the entire VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseSG"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`).
2. **Variables**: Several variables are defined to allow customization of the VPC, subnet CIDR blocks, and region.
3. **VPC Creation**: A VPC is created with the specified CIDR block.
4. **Subnet Creation**: One public subnet and two private subnets are created within the VPC.
5. **Internet Gateway**: An internet gateway is attached to the VPC to allow outbound internet access from the public subnet.
6. **Route Table**: A route table is created for the public subnet to route traffic to the internet gateway.
7. **Security Groups**: Security groups are created for the web server, application server, and database to control inbound and outbound traffic.

This configuration ensures that the public subnet can host a web server accessible from the internet, while the private subnets can host an application server and a database with restricted access.

