LLM Output #0:
### Description

The Terraform program below will create two AWS EC2 instances running the latest Amazon Linux AMI in private subnets. These instances will share an Amazon Elastic File System (EFS) for persistent storage. The program includes necessary IAM roles and policies to allow the EC2 instances to access the EFS file system.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t3.micro"
}

variable "key_name" {
  description = "SSH key pair name"
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID where the subnets are located"
  default     = ""
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs"
  type        = list(string)
  default     = []
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "efs_access_policy" {
  name        = "efs-access-policy"
  description = "Policy to allow EC2 instances to access EFS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Effect   = "Allow"
        Resource = "*"
        Principal = {
          AWS = aws_iam_role.ec2_instance_role.arn
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_efs_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = aws_iam_policy.efs_access_policy.arn
}

resource "aws_efs_file_system" "shared_efs" {
  creation_token = "shared-efs"
}

resource "aws_security_group" "ec2_instance_sg" {
  name        = "ec2-instance-sg"
  description = "Security group for EC2 instances"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "ec2_instance" {
  count         = 2
  ami           = data.aws_ami.latest_amazon_linux.id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = element(var.private_subnet_ids, count.index)
  iam_instance_profile = aws_iam_instance_profile.ec2_instance_profile.name
  security_groups = [aws_security_group.ec2_instance_sg.name]

  tags = {
    Name = "ec2-instance-${count.index + 1}"
  }
}

resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "ec2-instance-profile"
  roles = [aws_iam_role.ec2_instance_role.name]
}

data "aws_ami" "latest_amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Variables are defined for instance type, SSH key pair name, VPC ID, and private subnet IDs. Default values are provided where applicable.
3. **IAM Role and Policy**: An IAM role (`ec2-instance-role`) is created with a trust policy allowing EC2 to assume it. An IAM policy (`efs-access-policy`) is created to allow the EC2 instances to access the EFS file system. The policy is attached to the IAM role.
4. **EFS File System**: An EFS file system (`shared-efs`) is created.
5. **Security Group**: A security group (`ec2-instance-sg`) is created to allow SSH access and unrestricted egress.
