The Terraform program below will create an Amazon DynamoDB Accelerator (DAX) cluster using `dax.r4.large` nodes with a replication factor of 1. The program includes necessary IAM roles and policies required for DAX to function properly. It also sets up a VPC and subnets where the DAX cluster will reside. Default values are provided for variables to ensure the configuration is deployable without additional input.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_type" {
  description = "DAX instance type"
  default     = "dax.r4.large"
}

variable "replication_factor" {
  description = "Replication factor for the DAX cluster"
  default     = 1
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "main" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_iam_role" "dax_role" {
  name = "dax-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dax_policy" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXFullAccess"
}

resource "aws_dax_cluster" "example" {
  cluster_name       = "my-dax-cluster"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = var.instance_type
  replication_factor = var.replication_factor
  subnet_group_name  = aws_dax_subnet_group.example.name
}

resource "aws_dax_subnet_group" "example" {
  name       = "my-dax-subnet-group"
  subnet_ids = aws_subnet.main[*].id
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden by setting the `region` variable.

2. **Variables**: Several variables are defined with default values to allow customization of the deployment:
   - `region`: The AWS region.
   - `vpc_cidr_block`: The CIDR block for the VPC.
   - `subnet_cidr_blocks`: A list of CIDR blocks for the subnets.
