### Description

The Terraform program below creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The configuration includes setting up the necessary IAM roles and policies required for MSK to operate. The MSK cluster is configured to use a publicly accessible endpoint, and SSL encryption is enabled for data in transit. The program also sets up a VPC with subnets and security groups to ensure proper network isolation and access control.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "security_group_ingress_rules" {
  description = "Ingress rules for the security group"
  type        = list(map(string))
  default     = [
    {
      from_port   = 9092
      to_port     = 9092
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      from_port   = 2181
      to_port     = 2181
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  ]
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "msk_subnets" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "msk_sg" {
  name        = "${var.cluster_name}-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    for_each = var.security_group_ingress_rules
    from_port   = each.value.from_port
    to_port     = each.value.to_port
    protocol    = each.value.protocol
    cidr_blocks = each.value.cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    client_subnets = aws_subnet.msk_subnets[*].id
    instance_type  = var.instance_type
    security_groups = [aws_security_group.msk_sg.id]
    ebs_volume_size  = 100
  }
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }
  enhanced_monitoring = "PER_BROKER"
  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/${var.cluster_name}"
      }
      firehose {
        enabled         = false
        delivery_stream = ""
      }
      s3 {
        enabled = false
        bucket  = ""
        prefix  = ""
      }
    }
  }
  tags = {
    Name = var.cluster_name
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the cluster name, instance type, VPC CIDR block, subnet CIDR blocks, and security group ingress rules.
3. **VPC and Subnets**: A VPC and three subnets are created within the specified CIDR blocks.
4. **Security Group**: A security group is set up to allow inbound traffic on ports 9092 and 2181 for Kafka and Zookeeper respectively.
5. **IAM Role**: An IAM role is created with the necessary permissions for MSK to operate.
6. **MSK Cluster**: The MSK cluster is created with 3 broker nodes, using the specified instance type, subnets, and security group. SSL encryption is enabled for data in transit, and logging is configured to send logs to CloudWatch.

This configuration ensures that the MSK cluster is properly set up with the necessary networking and security configurations.

