### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "msk_kafka_version" {
  description = "The version of Kafka to use"
  default     = "2.8.0"
}

variable "msk_number_of_broker_nodes" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"]
}

variable "security_group_ids" {
  description = "A list of security group IDs for the MSK cluster"
  type        = list(string)
  default     = ["sg-12345678"]
}

resource "aws_iam_role" "msk_role" {
  name = "${var.msk_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_security_group" "msk_sg" {
  name        = "${var.msk_cluster_name}-sg"
  description = "Security group for MSK cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.msk_kafka_version
  number_of_broker_nodes = var.msk_number_of_broker_nodes
  broker_node_group_info {
    client_subnets         = var.subnet_ids
    instance_type          = var.msk_instance_type
    security_groups        = var.security_group_ids
