        enabled_in_broker = true
      }
    }
  }
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/${var.msk_cluster_name}"
      }
      firehose {
        enabled         = false
        delivery_stream = ""
      }
      s3 {
        enabled = false
        bucket  = ""
        prefix  = ""
      }
    }
  }
  tags = {
    Name = var.msk_cluster_name
  }
}
```

