I apologize for any confusion, but it appears there might be a mix-up in your request. Amazon Managed Streaming for Apache Kafka (MSK) is a service provided by AWS, not Google Cloud Platform. Therefore, I will create a Terraform configuration to set up an MSK cluster in AWS using CloudWatch for logging.

### Description:
The Terraform program below will create an Amazon MSK cluster in the `us-east-1` region. The cluster will be configured to log to a CloudWatch log group. The necessary IAM roles and policies will be created to allow MSK to send logs to CloudWatch. The configuration includes:

- An MSK cluster with a single broker.
- A CloudWatch log group for storing MSK logs.
- An IAM role and policy that grant MSK permissions to write logs to CloudWatch.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "client_subnets" {
  description = "A list of subnets where the MSK cluster will be deployed"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

variable "security_groups" {
  description = "A list of security groups for the MSK cluster"
  type        = list(string)
  default     = ["sg-0123456789abcdef0"]
}

resource "aws_iam_role" "msk_cloudwatch_role" {
  name = "${var.cluster_name}-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "msk_cloudwatch_policy" {
  name        = "${var.cluster_name}-cloudwatch-policy"
  description = "Policy to allow MSK to write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cloudwatch_policy_attachment" {
  policy_arn = aws_iam_policy.msk_cloudwatch_policy.arn
  role       = aws_iam_role.msk_cloudwatch_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 1

  broker_node_group_info {
    client_subnets = var.client_subnets
    instance_type  = var.instance_type
    security_groups = var.security_groups

    storage_info {
      ebs_storage_info {
        volume_size = 1000
      }
    }
  }

  logging_info {
    cloudwatch_logs {
      enabled   = true
      log_group = aws_cloudwatch_log_group.msk_logs.name
    }
  }

  tags = {
    Name = var.cluster_name
  }
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name              = "/aws/msk/${var.cluster_name}"
  retention_in_days = 30
}
```

### Notes:
- Ensure that the subnet IDs and security group IDs provided in the `client_subnets` and `security_groups` variables are valid and exist in your AWS account.
- The `kafka_version` can be updated to a different version if needed.
- The `storage_info` block specifies the EBS volume size for the brokers. Adjust this value based on your requirements.
- The `retention_in_days` for the CloudWatch log group can be adjusted as needed.

This configuration should be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

