LLM Output #0:
### Description

The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log its data to an S3 bucket. The necessary IAM roles and policies are created to allow the MSK cluster to write logs to the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "num_brokers" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket for logging"
  default     = "msk-logs-bucket"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "msk_logging_role" {
  name = "${var.cluster_name}-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_logging_policy" {
  name        = "${var.cluster_name}-logging-policy"
  description = "Policy to allow MSK to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.msk_logs_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_logging_policy_attachment" {
  role       = aws_iam_role.msk_logging_role.name
  policy_arn = aws_iam_policy.msk_logging_policy.arn
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = var.num_brokers

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"] # Replace with your subnet IDs
    instance_type  = var.instance_type
    security_groups = ["sg-12345678"] # Replace with your security group ID
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = false
      }
      firehose {
        enabled = false
      }
      s3 {
        enabled         = true
        bucket_arn      = aws_s3_bucket.msk_logs_bucket.arn
        prefix          = "msk-logs/"
        enabled         = true
        log_delivery_failure_topic_arn = "" # Optional: ARN of the topic for delivery failures
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }
}
```

### Notes:
1. **Subnet IDs and Security Group IDs**: Replace `"subnet-12345678"` and `"subnet-87654321"` with your actual subnet IDs and `"sg-12345678"` with your actual security group ID.
2. **Kafka Version**: Adjust the `kafka_version` as needed.
3. **IAM Role and Policy**: Ensure that the IAM role and policy have the necessary permissions to write to the S3 bucket.
4. **Logging Configuration**: The logging is configured to use S3. You can enable CloudWatch Logs or Firehose if needed.

This configuration should be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

