### Description

The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log its data to an Amazon Kinesis Data Firehose delivery stream. The program includes the necessary IAM roles and policies to allow the MSK cluster to send logs to Kinesis Firehose.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "num_brokers" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "kinesis_firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "msk-logs-delivery-stream"
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = var.kinesis_firehose_delivery_stream_name
  destination = "s3"

  s3_configuration {
    role_arn   = aws_iam_role.msk_role.arn
    bucket_arn = "arn:aws:s3:::your-s3-bucket-name"
    prefix     = "msk-logs/"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = var.num_brokers

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = var.instance_type
    security_groups  = ["sg-12345678"]

    ebs_storage_info {
      volume_size = 1000
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = false
      }
      firehose {
        delivery_stream = aws_kinesis_firehose_delivery_stream.firehose_delivery_stream.name
        enabled         = true
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }
}
```

### Notes:
- Replace `"arn:aws:s3:::your-s3-bucket-name"` with the ARN of your S3 bucket where you want to store the logs.
- Ensure that the subnets and security groups provided in the `broker_node_group_info` block are valid and exist in your AWS account.
- The `kafka_version` can be updated to a different version if needed.
- The `ebs_storage_info` block specifies the EBS volume size for the broker nodes. Adjust this value based on your requirements.

