### Description

The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with JMX Exporter and Node Exporter enabled. The program includes the necessary AWS provider configuration, IAM roles, and security groups to ensure proper access and monitoring.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the MSK cluster"
  default     = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "broker_count" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "vpc_id" {
  description = "The VPC ID where the MSK cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_ids" {
  description = "A list of security group IDs for the MSK cluster"
  type        = list(string)
  default     = ["sg-12345678"]
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_security_group" "msk_sg" {
  name        = "${var.cluster_name}-sg"
  description = "Security group for MSK cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 11098
    to_port     = 11098
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = var.broker_count
  broker_node_group_info {
    client_subnets = var.subnet_ids
    instance_type  = var.instance_type
    security_groups = [aws_security_group.msk_sg.id]
    ebs_volume_size = 100
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the MSK cluster, such as the cluster name, instance type, broker count, VPC ID, subnet IDs, and security group IDs.

3. **IAM Role**: An IAM role is created for the MSK cluster with permissions to assume roles for EC2 and MSK services. The `AmazonMSKFullAccess` policy is attached to this role.

4. **Security Group**: A security group is created to allow inbound traffic on ports 9092 (Kafka) and 11098 (JMX Exporter/Node Exporter). Outbound traffic is allowed to any destination.

5. **MSK Cluster**: The MSK cluster is created with the specified configuration, including enabling JMX Exporter and Node Exporter for monitoring.

This Terraform configuration is deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. Make sure to replace the default values with your specific requirements before deploying.

