### Description

The Terraform program below creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The configuration includes setting up the necessary AWS resources such as the MSK cluster, VPC, subnets, security groups, and IAM roles required for the MSK cluster to operate. The program also ensures that the MSK cluster is configured to be serverless, meaning it automatically scales based on the data throughput.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "msk_subnets" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "msk_sg" {
  name        = "${var.cluster_name}-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_msk_serverless_cluster" "msk_cluster" {
  cluster_name = var.cluster_name
  vpc_config {
    subnet_ids = aws_subnet.msk_subnets[*].id
  }
  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the cluster name, VPC CIDR block, subnet CIDR blocks, and instance type.
3. **VPC and Subnets**: A VPC and three subnets are created within the VPC.
4. **Security Group**: A security group is created to allow inbound traffic on port 9092 for Kafka communication.
5. **IAM Role**: An IAM role is created with policies attached to allow the MSK cluster to operate.
6. **MSK Serverless Cluster**: A serverless MSK cluster is created with the specified configurations, including VPC settings, client authentication, and encryption.

This configuration ensures that the MSK cluster is set up correctly and can be deployed using Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

