I'm sorry, but there seems to be a misunderstanding. AWS does not have a region named "us-east2". The correct region for the US East (N. Virginia) is "us-east-1". I will create a serverless MSK (Managed Streaming for Apache Kafka) cluster in the "us-east-1" region instead.

### Description:
The Terraform program below will create a serverless MSK cluster in the "us-east-1" region. It includes the necessary IAM roles and policies required for the MSK cluster to operate. The configuration also sets up a VPC with public and private subnets, which is required for the MSK cluster.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "The CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidr_blocks" {
  description = "The CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "availability_zones" {
  description = "The availability zones for the subnets"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b"]
}

resource "aws_vpc" "msk_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "msk_public_subnets" {
  count             = length(var.public_subnet_cidr_blocks)
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  availability_zone = element(var.availability_zones, count.index)
  map_public_ip_on_launch = true
}

resource "aws_subnet" "msk_private_subnets" {
  count             = length(var.private_subnet_cidr_blocks)
  vpc_id            = aws_vpc.msk_vpc.id
  cidr_block        = element(var.private_subnet_cidr_blocks, count.index)
  availability_zone = element(var.availability_zones, count.index)
}

resource "aws_internet_gateway" "msk_igw" {
  vpc_id = aws_vpc.msk_vpc.id
}

resource "aws_route_table" "msk_public_route_table" {
  vpc_id = aws_vpc.msk_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.msk_igw.id
  }
}

resource "aws_route_table_association" "msk_public_subnet_associations" {
  count          = length(aws_subnet.msk_public_subnets)
  subnet_id      = element(aws_subnet.msk_public_subnets[*].id, count.index)
  route_table_id = aws_route_table.msk_public_route_table.id
}

resource "aws_security_group" "msk_sg" {
  name        = "${var.cluster_name}-sg"
  description = "Security group for MSK cluster"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_role_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_msk_serverless_cluster" "msk_cluster" {
  cluster_name = var.cluster_name
  vpc_config {
    subnet_ids = aws_subnet.msk_private_subnets[*].id
  }
  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }
  tags = {
    Name = var.cluster_name
  }
}
```

This Terraform configuration sets up a VPC with public and private subnets, creates an MSK serverless cluster, and configures the necessary IAM roles and policies. The MSK cluster is configured to use SASL/IAM authentication and TLS encryption in transit.

