LLM Output #0:
### Description

The Terraform program below creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes. It also sets up a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream to handle the output from the MSK cluster. The MSK cluster is configured with encryption at rest and open monitoring.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "msk_cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "msk_kafka_version" {
  description = "The Kafka version for the MSK cluster"
  default     = "2.8.0"
}

variable "msk_min_insync_replicas" {
  description = "The minimum number of in-sync replicas"
  default     = 2
}

variable "msk_num_broker_nodes" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "cloudwatch_log_group_name" {
  description = "The name of the CloudWatch log group"
  default     = "msk-logs"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket"
  default     = "msk-s3-bucket"
}

variable "firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "msk-firehose-stream"
}

resource "aws_iam_role" "msk_role" {
  name = "${var.msk_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.msk_kafka_version
  number_of_broker_nodes = var.msk_num_broker_nodes
  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = var.msk_instance_type
    security_groups  = ["sg-12345678"]
    ebs_volume_size  = 100
  }
  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }
  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.cloudwatch_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.firehose_delivery_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.s3_bucket.bucket
      }
    }
  }
  tags = {
    Name = var.msk_cluster_name
  }
}

resource "aws_cloudwatch_log_group" "cloudwatch_log_group" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 30
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = var.s3_bucket_name
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = var.firehose_delivery_stream_name
  destination = "s3"

  s3_configuration {
    role_arn   = aws_iam_role.msk_role.arn
    bucket_arn = aws_s3_bucket.s3_bucket.arn
    prefix     = "msk-logs/"
  }
}
```

### Notes:
- Replace `"subnet-12345678"`, `"subnet-87654321"`, and `"sg-12345678"` with your actual subnet IDs and security group IDs.
- Replace `"arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"` with your actual KMS key ARN.
- Ensure that the IAM role has the necessary permissions to access the S3 bucket and CloudWatch log group.
- Adjust the `retention_in_days` for the CloudWatch log group as needed.

