### Description

This Terraform program sets up an Amazon Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes, configured for encryption at rest and open monitoring. It also creates a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream to handle the output from the MSK cluster. Additionally, it creates an MSK Connect custom plugin using a provided "debezium.zip" file and sets up an MSK Connect connector that utilizes this custom plugin to connect to the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "msk_cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "msk_number_of_broker_nodes" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "msk_kafka_version" {
  description = "The Kafka version for the MSK cluster"
  default     = "2.8.0"
}

variable "msk_security_group_name" {
  description = "The name of the security group for the MSK cluster"
  default     = "msk-sg"
}

variable "msk_subnet_ids" {
  description = "A list of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
}

variable "cloudwatch_log_group_name" {
  description = "The name of the CloudWatch log group"
  default     = "msk-log-group"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket"
  default     = "my-msk-s3-bucket"
}

variable "firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "my-msk-firehose-stream"
}

variable "msk_connect_plugin_name" {
  description = "The name of the MSK Connect custom plugin"
  default     = "debezium-plugin"
}

variable "msk_connect_connector_name" {
  description = "The name of the MSK Connect connector"
  default     = "my-msk-connector"
}

resource "aws_iam_role" "msk_role" {
  name = "${var.msk_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  role       = aws_iam_role.msk_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.msk_kafka_version
  number_of_broker_nodes = var.msk_number_of_broker_nodes
  broker_node_group_info {
    client_subnets = var.msk_subnet_ids
    instance_type  = var.msk_instance_type
    security_groups = [aws_security_group.msk_sg.id]
    ebs_volume_size = 100
  }
  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:${var.region}:${data.aws_caller_identity.current.account_id}:key/${data.aws_kms_key.default.key_id}"
  }
  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
  logging_info {
    cloudwatch_logs {
      enabled   = true
      log_group = aws_cloudwatch_log_group.msk_log_group.name
    }
    s3 {
      enabled = true
      bucket  = aws_s3_bucket.msk_bucket.bucket
    }
    firehose {
      enabled         = true
      delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose.name
    }
  }
}

resource "aws_security_group" "msk_sg" {
  name        = var.msk_security_group_name
  description = "Security group for MSK cluster"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 30
}

resource "aws_s3_bucket" "msk_bucket" {
  bucket = var.s3_bucket_name
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name        = var.firehose_delivery_stream_name
  destination = "s3"

  s3_configuration {
    role_arn           = aws_iam_role.msk_role.arn
    bucket_arn         = aws_s3_bucket.msk_bucket.arn
    prefix             = "logs/"
    buffering_hints {
      size_in_mBs = 5
      interval_in_seconds = 300
    }
  }
}

resource "aws_iam_role" "msk_connect_role" {
  name = "${var.msk_connect_connector_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_connect_policy" {
  role       = aws_iam_role.msk_connect_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_MSK_Connect"
}

resource "aws_mskconnect_custom_plugin" "msk_connect_plugin" {
  name            = var.msk_connect_plugin_name
  content_type    = "ZIP"
  location {
    s3_location {
      bucket_arn = aws_s3_bucket.msk_bucket.arn
      file_key   = "debezium.zip"
    }
  }
}

resource "aws_mskconnect_connector" "msk_connect_connector" {
  name            = var.msk_connect_connector_name
  connector_type  = "source"
  kafkaconnect_version = "2.8.0"
  capacity {
    auto_scaling {
      max_worker_count = 10
      min_worker_count = 1
      mcu_count        = 1
    }
  }
  connector_configuration = {
    "connector.class" = "io.debezium.connector.kafka.KafkaSourceConnector"
    "tasks.max"       = "1"
    "topics"          = "my-topic"
    "kafka.bootstrap.servers" = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
    "key.converter"   = "org.apache.kafka.connect.storage.StringConverter"
    "value.converter" = "org.apache.kafka.connect.json.JsonConverter"
  }
  kafkacluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
      vpc {
        security_groups = [aws_security_group.msk_sg.id]
        subnets         = var.msk_subnet_ids
      }
    }
    authentication {
      sasl_scram {
        enabled = true
        scram = {
          username = "admin"
          password = "admin-secret"
        }
      }
    }
  }
  plugins {
    custom_plugin {
      arn = aws_mskconnect_custom_plugin.msk_connect_plugin.arn
    }
  }
  service_execution_role_arn = aws_iam_role.msk_connect_role.arn
}

data "aws_caller_identity" "current" {}

data "aws_kms_key" "default" {
  key_id = "alias/aws/msk"
}

data "aws_vpc" "default" {
  default = true
}
```

### Explanation

1. **Provider Configuration**: Configures the AWS provider with a default region.
2. **Variables**: Defines various variables with default values for resource names, types, and configurations.
3. **IAM Roles**: Creates IAM roles for the MSK cluster and MSK Connect with necessary policies.
4. **MSK Cluster**: Sets up an MSK cluster with three broker nodes, encryption at rest, and open monitoring.
5. **Security Group**: Creates a security group for the MSK cluster.
6. **CloudWatch Log Group**: Creates a CloudWatch log group for logging.
