### Description

The Terraform program below creates an Amazon Aurora PostgreSQL cluster in the `us-west-2` region. The configuration includes:

1. **Provider Configuration**: Configures the AWS provider with the specified region.
2. **VPC and Subnets**: Creates a VPC and three public subnets across different availability zones.
3. **Security Group**: Sets up a security group to allow inbound traffic on port 5432 (PostgreSQL default port) from any IP address.
4. **IAM Role**: Creates an IAM role with the necessary permissions for the Aurora cluster.
5. **Aurora Cluster and Instances**: Deploys an Aurora PostgreSQL cluster with two instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "db_cluster_identifier" {
  description = "Identifier for the Aurora cluster"
  default     = "my-aurora-cluster"
}

variable "db_instance_class" {
  description = "Instance class for the Aurora instances"
  default     = "db.serverless"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  sensitive   = true
  default     = "securepassword"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "aurora_sg" {
  name        = "aurora-sg"
  description = "Allow PostgreSQL traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_role" {
  name = "aurora-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aurora_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AuroraAccessRolePolicy"
  role       = aws_iam_role.aurora_role.name
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = "aurora-postgresql"
  engine_version          = "13.7"
  database_name           = var.db_name
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.aurora_sg.id]
  iam_database_authentication_enabled = true
