### Description

The Terraform program below will create an Amazon RDS MySQL cluster with three availability zones, each having 100 GB of storage allocated. The program includes necessary IAM roles and policies for the RDS service to operate, and it sets up a VPC with subnets across the specified availability zones. The default database engine version and instance class can be adjusted via variables.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_class" {
  description = "The instance class for the RDS MySQL instances"
  type        = string
  default     = "db.t3.medium"
}

variable "db_engine_version" {
  description = "The MySQL engine version"
  type        = string
  default     = "8.0.mysql_aurora.3.02.0"
}

variable "db_name" {
  description = "The name of the database"
  type        = string
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  type        = string
  sensitive   = true
  default     = "securepassword123"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "subnet" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_db_subnet_group" "default" {
  name       = "my-mysql-subnet-group"
  subnet_ids = aws_subnet.subnet[*].id
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSDb"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = "my-mysql-cluster"
  engine                  = "aurora-mysql"
  engine_version          = var.db_engine_version
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.default.name
  iam_database_authentication_enabled = true
  skip_final_snapshot     = true
  apply_immediately       = true
}

resource "aws_rds_cluster_instance" "mysql_instance" {
  count              = 3
  identifier         = "my-mysql-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.mysql_cluster.id
  instance_class     = var.db_instance_class
  engine             = aws_rds_cluster.mysql_cluster.engine
  engine_version     = aws_rds_cluster.mysql_cluster.engine_version
  db_subnet_group_name = aws_db_subnet_group.default.name
  publicly_accessible = false
  apply_immediately   = true
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the database instance class, engine version, database name, username, password, VPC CIDR block, and subnet CIDR blocks.
3. **VPC and Subnets**: A VPC is created with a specified CIDR block, and three subnets are created across different availability zones.
4. **DB Subnet Group**: An RDS DB subnet group is created to associate the subnets with the RDS cluster.
5. **IAM Role**: An IAM role is created for the RDS service with the necessary permissions.
6. **RDS Cluster and Instances**: An RDS MySQL cluster is created with three instances, each having 100 GB of storage allocated. The instances are spread across the three availability zones.

This configuration ensures that the MySQL cluster is highly available and fault-tolerant, with each instance having sufficient storage capacity.

