### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS cluster"
  default     = "my-mysql-cluster"
}

variable "db_instance_class" {
  description = "Instance class for the RDS instances"
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "Allocated storage for each RDS instance in GB"
  default     = 100
}

variable "engine" {
  description = "Database engine"
  default     = "aurora-mysql"
}

variable "engine_version" {
  description = "Database engine version"
  default     = "8.0.mysql_aurora.3.02.0"
}

variable "master_username" {
  description = "Master username for the database"
  default     = "admin"
}

variable "master_password" {
  description = "Master password for the database"
  default     = "password123"  # Replace with a secure password
  sensitive   = true
}

variable "backup_retention_period" {
  description = "Backup retention period in days"
  default     = 7
}

variable "preferred_backup_window" {
  description = "Preferred backup window"
  default     = "07:00-09:00"
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = var.engine
  engine_version          = var.engine_version
  master_username         = var.master_username
  master_password         = var.master_password
  backup_retention_period = var.backup_retention_period
  preferred_backup_window = var.preferred_backup_window
  iam_database_authentication_enabled = true
  db_subnet_group_name    = aws_db_subnet_group.mysql_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.mysql_sg.id]
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.mysql_cluster_param_group.name
  iam_roles               = [aws_iam_role.rds_iam_role.arn]
}

resource "aws_rds_cluster_instance" "mysql_instance" {
  count                   = 3
  identifier              = "${var.db_cluster_identifier}-instance-${count.index + 1}"
  cluster_identifier      = aws_rds_cluster.mysql_cluster.id
  instance_class          = var.db_instance_class
  engine                  = var.engine
  engine_version          = var.engine_version
  allocated_storage       = var.allocated_storage
  db_subnet_group_name    = aws_db_subnet_group.mysql_subnet_group.name
  publicly_accessible     = false
  auto_minor_version_upgrade = true
  monitoring_interval     = 60
  monitoring_role_arn     = aws_iam_role.rds_iam_role.arn
}

resource "aws_db_subnet_group" "mysql_subnet_group" {
  name       = "${var.db_cluster_identifier}-subnet-group"
  subnet_ids = data.aws_subnet_ids.default.ids

  tags = {
    Name = "${var.db_cluster_identifier}-subnet-group"
  }
}

data "aws_subnet_ids" "default" {
  vpc_id = "vpc-12345678"  # Replace with your VPC ID
  filter {
    name   = "availability-zone"
    values = ["us-east-1a", "us-east-1b", "us-east-1c"]
  }
}

resource "aws_security_group" "mysql_sg" {
  name        = "${var.db_cluster_identifier}-sg"
  description = "Security group for MySQL RDS cluster"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster_parameter_group" "mysql_cluster_param_group" {
  name        = "${var.db_cluster_identifier}-param-group"
  family      = "aurora-mysql8.0"
  description = "Parameter group for MySQL RDS cluster"

  parameter {
    name         = "character_set_server"
    value        = "utf8mb4"
    apply_method = "immediate"
  }

  parameter {
    name         = "collation_server"
    value        = "utf8mb4_unicode_ci"
    apply_method = "immediate"
  }
}
```

### Notes:
- Replace `"vpc-12345678"` with your actual VPC ID.
- Ensure that the security group settings (`cidr_blocks`) are appropriate for your environment.
- The `master_password` variable should be set to a secure password in a real-world scenario.
- The `aws_db_subnet_group` resource assumes that subnets in `us-east-1a`, `us-east-1b`, and `us-east-1c` exist within the specified VPC. Adjust the subnet IDs as necessary.

