### Description

The Terraform program below will create a DAX (DynamoDB Accelerator) cluster in AWS. The configuration includes:

- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role**: Creates an IAM role for the DAX service to interact with DynamoDB.
- **Security Group**: Sets up a security group to allow inbound traffic on the DAX port.
- **Subnet Group**: Defines a subnet group for the DAX cluster.
- **DAX Cluster**: Creates the DAX cluster using the defined IAM role, security group, and subnet group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the DAX cluster"
  type        = string
  default     = "us-west-2"
}

variable "dax_cluster_name" {
  description = "The name of the DAX cluster"
  type        = string
  default     = "my-dax-cluster"
}

variable "dax_node_type" {
  description = "The node type for the DAX cluster"
  type        = string
  default     = "dax.r4.large"
}

variable "dax_subnet_ids" {
  description = "List of subnet IDs for the DAX cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

variable "dax_security_group_name" {
  description = "Name of the security group for the DAX cluster"
  type        = string
  default     = "dax-sg"
}

resource "aws_iam_role" "dax_role" {
  name = "${var.dax_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dax_policy" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXFullAccess"
}

resource "aws_security_group" "dax_sg" {
  name        = var.dax_security_group_name
  description = "Security group for DAX cluster"
  vpc_id      = "vpc-0123456789abcdef0"

  ingress {
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_dax_subnet_group" "dax_subnet_group" {
  name       = "${var.dax_cluster_name}-subnet-group"
  subnet_ids = var.dax_subnet_ids
}

resource "aws_dax_cluster" "dax_cluster" {
  cluster_name       = var.dax_cluster_name
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = var.dax_node_type
  replication_factor = 1
  subnet_group_name  = aws_dax_subnet_group.dax_subnet_group.name
  security_group_ids = [aws_security_group.dax_sg.id]
}
```

### Notes

- **Region**: The default region is set to `us-west-2`, but you can change it by setting the `region` variable.
- **Subnet IDs**: Replace the example subnet IDs with your actual subnet IDs.
- **VPC ID**: Ensure the VPC ID in the security group matches your VPC configuration.
- **IAM Policy**: The IAM role is attached to the `AmazonDAXFullAccess` policy, which provides full access to DAX. Adjust the policy as needed based on your security requirements.

This configuration should be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

