### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "neptune_instance_class" {
  description = "The instance class for the Neptune cluster"
  type        = string
  default     = "db.r5.large"
}

variable "neptune_engine_version" {
  description = "The engine version for the Neptune cluster"
  type        = string
  default     = "1.2.0.1"
}

variable "neptune_cluster_identifier" {
  description = "The identifier for the Neptune cluster"
  type        = string
  default     = "my-neptune-cluster"
}

variable "neptune_parameter_group_name" {
  description = "The name of the Neptune parameter group"
  type        = string
  default     = "my-neptune-parameter-group"
}

variable "neptune_subnet_group_name" {
  description = "The name of the Neptune subnet group"
  type        = string
  default     = "my-neptune-subnet-group"
}

variable "vpc_id" {
  description = "The VPC ID where the Neptune cluster will be deployed"
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the Neptune cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_iam_role" "neptune_role" {
  name = "neptune-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "neptune.amazonaws.com"
        }
      },
    ]
