### Description

The Terraform program below creates an AWS Redshift cluster and sets up SNS topics to receive notifications for specific events related to the Redshift cluster. The program includes:

1. **AWS Provider Configuration**: Sets the region to `us-west-2`.
2. **IAM Role for Redshift**: Creates an IAM role that allows Redshift to access other AWS services.
3. **SNS Topic**: Creates an SNS topic to which Redshift will publish notifications.
4. **Redshift Cluster**: Creates a Redshift cluster with the specified parameters.
5. **Event Subscription**: Subscribes the SNS topic to Redshift cluster events.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "master_username" {
  description = "The username for the master user"
  default     = "admin"
}

variable "master_user_password" {
  description = "The password for the master user"
  default     = "SecurePassword123!"
}

variable "cluster_type" {
  description = "The type of the Redshift cluster (single-node or multi-node)"
  default     = "multi-node"
}

variable "number_of_nodes" {
  description = "The number of nodes in the Redshift cluster"
  default     = 2
}

variable "sns_topic_name" {
  description = "The name of the SNS topic for notifications"
  default     = "redshift-events"
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.redshift_role.name
}

resource "aws_sns_topic" "redshift_events" {
  name = var.sns_topic_name
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier = var.cluster_identifier
  node_type          = var.node_type
  master_username    = var.master_username
  master_user_password = var.master_user_password
  cluster_type       = var.cluster_type
  number_of_nodes    = var.number_of_nodes
  iam_roles          = [aws_iam_role.redshift_role.arn]
}

resource "aws_sns_topic_subscription" "redshift_event_subscription" {
  topic_arn = aws_sns_topic.redshift_events.arn
  protocol  = "email"
  endpoint  = "your-email@example.com"
}

resource "aws_redshift_event_subscription" "example" {
  name                = "redshift-event-subscription"
  sns_topic_arn       = aws_sns_topic.redshift_events.arn
  source_ids          = [aws_redshift_cluster.example.id]
  source_type         = "cluster"
  event_categories    = ["configuration", "management", "monitoring", "security"]
  severity            = "ERROR"
  enabled             = true
}
```

### Notes

- Replace `"your-email@example.com"` with your actual email address to receive notifications.
- Ensure that the IAM role has the necessary permissions to access any S3 buckets or other AWS services required by your Redshift cluster.
- Adjust the `event_categories` and `severity` in the `aws_redshift_event_subscription` resource to match the events you want to be notified about.

