  name = var.iam_user_name
}

resource "aws_iam_access_key" "basic_user_key" {
  user    = aws_iam_user.basic_user.name
  status  = "Active"
}

resource "aws_iam_user_ssh_key" "basic_user_ssh_key" {
  username   = aws_iam_user.basic_user.name
  ssh_public_key = file("${path.module}/id_rsa.pub")
  encoding   = "SSH"
}

output "access_key_id" {
  value = aws_iam_access_key.basic_user_key.id
}

output "secret_access_key" {
  value = aws_iam_access_key.basic_user_key.secret
  sensitive = true
}

output "ssh_public_key_fingerprint" {
  value = aws_iam_user_ssh_key.basic_user_ssh_key.fingerprint
}
```

### Notes

- **SSH Key File**: Ensure that the public SSH key (`id_rsa.pub`) is placed in the same directory as the Terraform configuration file. Alternatively, you can modify the `file()` function to point to the correct path of your public SSH key.
- **Sensitive Data**: The `secret_access_key` is marked as sensitive to prevent it from being displayed in the Terraform output.
- **IAM Roles**: No IAM roles are created in this configuration since the prompt only asks for a basic IAM user with an SSH key. If additional roles are needed, they can be added separately.

