  bucket = var.bucket_name_1
  acl    = "private"

  logging {
    target_bucket = aws_s3_bucket.second_bucket.bucket
    target_prefix = "log/"
  }
}

resource "aws_s3_bucket" "second_bucket" {
  bucket = var.bucket_name_2
  acl    = "log-delivery-write"
}

resource "aws_iam_role" "s3_log_delivery_role" {
  name = "s3-log-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_log_delivery_policy" {
  name        = "s3-log-delivery-policy"
  description = "Policy for S3 log delivery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketAcl",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.second_bucket.arn}",
          "${aws_s3_bucket.second_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_log_delivery_policy_attachment" {
  role       = aws_iam_role.s3_log_delivery_role.name
  policy_arn = aws_iam_policy.s3_log_delivery_policy.arn
}

resource "aws_s3_bucket_policy" "second_bucket_policy" {
  bucket = aws_s3_bucket.second_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:PutObject"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.s3_log_delivery_role.arn
        }
        Resource = "${aws_s3_bucket.second_bucket.arn}/log/*"
      }
    ]
  })
}
```

