### Description

The Terraform program below sets up the infrastructure required for an autograder system using AWS CodeBuild. This setup includes:

1. **AWS CodeBuild Project**: A project that will be triggered to build and test students' code.
2. **IAM Role**: An IAM role with the necessary permissions for CodeBuild to access other AWS services like S3 and ECR.
3. **S3 Bucket**: A bucket to store the build artifacts and results.
4. **GitHub Source**: Configuration to pull the source code from a GitHub repository.

The program assumes that the GitHub repository is already set up with the necessary credentials and webhook to trigger the CodeBuild project.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "github_owner" {
  description = "The owner of the GitHub repository"
  type        = string
}

variable "github_repo" {
  description = "The name of the GitHub repository"
  type        = string
}

variable "github_oauth_token" {
  description = "The OAuth token for accessing the GitHub repository"
  type        = string
  sensitive   = true
}

resource "aws_iam_role" "codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
  role       = aws_iam_role.codebuild_role.name
}

resource "aws_s3_bucket" "build_artifacts" {
  bucket = "autograder-build-artifacts-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_codebuild_project" "autograder" {
  name         = "autograder-project"
  description  = "Autograder for CS class"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_owner}/${var.github_repo}.git"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:${var.region}:${data.aws_caller_identity.current.account_id}:project/autograder-project"
    }
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.build_artifacts.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/autograder-project"
      stream_name = "autograder-stream"
