### Description

The Terraform program below sets up the infrastructure required for an autograder system for a CS class. The system will use AWS S3 to store student code, AWS CodeBuild to execute the grading process, and AWS VPC to ensure that the students' code does not have internet access. The setup includes:

1. **AWS S3 Bucket**: To store the students' code.
2. **AWS VPC**: To create a private network where the grading process will occur.
3. **AWS Subnets**: Private subnets within the VPC to isolate the grading environment.
4. **AWS Security Groups**: To control inbound and outbound traffic, ensuring that the grading environment cannot reach the internet.
5. **AWS IAM Roles and Policies**: To grant necessary permissions to CodeBuild for accessing S3 and operating within the VPC.
6. **AWS CodeBuild Project**: To define the build environment and steps for executing the grading process.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_name" {
  description = "Name of the S3 bucket to store student code"
  type        = string
  default     = "cs-class-autograder-bucket"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

resource "aws_s3_bucket" "student_code_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "CS-Class-Autograder-VPC"
  }
}

resource "aws_subnet" "autograder_subnets" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "CS-Class-Autograder-Subnet-${count.index + 1}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "autograder_sg" {
  name        = "cs-class-autograder-sg"
  description = "Security group for the autograder environment"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "CS-Class-Autograder-SG"
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "cs-class-autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
}

resource "aws_iam_role_policy_attachment" "s3_read_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "cs-class-autograder-project"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "S3"
    location        = "${aws_s3_bucket.student_code_bucket.bucket}/"
    buildspec       = "buildspec.yml"
    insecure_ssl    = false
    report_build_status = true
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  vpc_config {
    vpc_id            = aws_vpc.autograder_vpc.id
    subnets           = aws_subnet.autograder_subnets[*].id
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "CS-Class-Autograder-Project"
  }
}
```

### Explanation

- **AWS S3 Bucket**: The `aws_s3_bucket` resource creates a private S3 bucket to store the students' code.
- **AWS VPC**: The `aws_vpc` resource creates a VPC with a specified CIDR block.
- **AWS Subnets**: The `aws_subnet` resource creates private subnets within the VPC.
- **AWS Security Group**: The `aws_security_group` resource configures security groups to restrict traffic to and from the VPC.
- **AWS IAM Role**: The `aws_iam_role` and `aws_iam_role_policy_attachment` resources create an IAM role with necessary permissions for CodeBuild.
- **AWS CodeBuild Project**: The `aws_codebuild_project` resource defines the CodeBuild project, specifying the source, environment, and VPC configuration.

This setup ensures that the autograding environment is isolated and secure, preventing students' code from reaching the internet.

