### Description

The Terraform program below sets up the infrastructure required for an autograder system for a CS class. The system includes:

1. **AWS S3 Bucket**: To store the results of the autograding process.
2. **AWS CodeBuild Project**: To execute the students' code in a controlled environment.
3. **AWS VPC**: To create a virtual private cloud that isolates the autograding environment.
4. **AWS VPC Subnet**: To provide a subnet within the VPC where the CodeBuild project will run.
5. **AWS Security Group**: To restrict network access, ensuring that the students' code cannot reach the internet.

The configuration ensures that the students' code runs in a secure, isolated environment, with no internet access, and the results are stored in an S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_name" {
  description = "Name of the S3 bucket to store autograding results"
  type        = string
  default     = "autograder-results-bucket"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  type        = string
  default     = "cs-class-autograder"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the VPC subnet"
  type        = string
  default     = "10.0.1.0/24"
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "AutograderVPC"
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"

  tags = {
    Name = "AutograderSubnet"
  }
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg"
  description = "Security group for the autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AutograderSG"
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "CodeBuildAutograderRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
}

resource "aws_codebuild_project" "autograder" {
  name         = var.codebuild_project_name
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location          = "https://github.com/example/repo.git"
    buildspec         = "buildspec.yml"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:us-west-2:123456789012:project/${var.codebuild_project_name}"
    }
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }
}
```

