### Description

The Terraform program defined below will create the following AWS resources:

1. **AWS S3 Bucket**: To store the output of the AWS CodeBuild project.
2. **AWS VPC**: With a CIDR block of `10.0.0.0/16`.
3. **AWS Subnet**: Within the VPC with a CIDR block of `10.0.0.0/24`.
4. **AWS Security Group**: Linked to the VPC with no ingress or egress rules to block internet access.
5. **AWS CodeBuild Project**: Configured to use the S3 bucket for storing build artifacts, with specific environment settings, source configuration from GitHub, and linked to the VPC.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store CodeBuild output"
  default     = "codebuild-output-bucket"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the VPC subnet"
  default     = "10.0.0.0/24"
}

variable "security_group_name" {
  description = "Name of the security group"
  default     = "codebuild-security-group"
}

variable "codebuild_project_name" {
  description = "Name of the CodeBuild project"
  default     = "student-codebuild-project"
}

variable "github_source_location" {
  description = "GitHub repository location"
  default     = "github.com/source-location"
}

resource "aws_s3_bucket" "codebuild_output" {
  bucket = var.s3_bucket_name
  acl    = "private"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"  # Specify your desired availability zone
}

resource "aws_security_group" "codebuild_sg" {
  name        = var.security_group_name
  description = "Security group for CodeBuild with no internet access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    self        = true
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "${var.codebuild_project_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
}

resource "aws_codebuild_project" "student_codebuild" {
  name         = var.codebuild_project_name
  description  = "CodeBuild project for student code"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type  = "S3"
    location = "${aws_s3_bucket.codebuild_output.bucket}/${var.codebuild_project_name}"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/alpine:latest"
    type         = "LINUX_CONTAINER"
  }

  source {
    type         = "GITHUB"
    location     = var.github_source_location
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.main.id
    subnets            = [aws_subnet.main.id]
    security_group_ids = [aws_security_group.codebuild_sg.id]
  }
}
```

### Notes

- The `aws_codebuild_project` resource requires an IAM role with the necessary permissions. In this example, the `AWSCodeBuildDeveloperAccess` policy is attached to the role. You may need to adjust the policy based on your specific requirements.
- Ensure that the GitHub repository is publicly accessible or that the necessary credentials are configured for private repositories.
- The availability zone for the subnet is set to `us-west-2a`. Adjust this to match your desired region and availability zone.
- The S3 bucket name must be globally unique across all existing bucket names in Amazon S3. Adjust the `s3_bucket_name` variable if the default name is already taken.

