### Description

The Terraform program below sets up an AWS infrastructure to host a web server that allows users to upload cat pictures and provides random cat pictures on demand. The solution uses Amazon API Gateway to handle HTTP requests, Amazon S3 to store the uploaded cat pictures, and an IAM role to manage permissions.

- **API Gateway**: Acts as the entry point for HTTP requests. It defines two endpoints: one for uploading cat pictures and another for retrieving random cat pictures.
- **S3 Bucket**: Stores the uploaded cat pictures. The bucket is configured to allow public read access for serving images.
- **IAM Role**: Grants necessary permissions to API Gateway to interact with S3.

### Terraform Configuration

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store cat pictures"
  default     = "cat-pictures-bucket-${random_string.bucket_suffix.result}"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_bucket" "cat_pictures" {
  bucket = var.bucket_name
  acl    = "public-read"

  tags = {
    Name        = "Cat Pictures Bucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "api_gateway_role" {
  name = "api-gateway-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_policy" {
  name = "api-gateway-s3-policy"
  role = aws_iam_role.api_gateway_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "Cat Pictures API"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures.bucket}/"
  credentials             = aws_iam_role.api_gateway_role.arn
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "GET"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures.bucket}/"
  credentials             = aws_iam_role.api_gateway_role.arn
}

resource "aws_api_gateway_deployment" "cat_pictures_deployment" {
  depends_on = [
    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
}
```

### Explanation

1. **Provider Configuration**: Sets the AWS region to `us-west-2` by default.
2. **Variables**: Defines variables for the region and bucket name, with default values.
3. **Random String**: Generates a random suffix for the S3 bucket name to ensure uniqueness.
4. **S3 Bucket**: Creates an S3 bucket with public read access to serve the cat pictures.
5. **IAM Role**: Creates an IAM role that API Gateway can assume to access S3.
6. **IAM Policy**: Attaches a policy to the IAM role allowing API Gateway to perform `GetObject` and `PutObject` operations on the S3 bucket.
7. **API Gateway REST API**: Creates a REST API with two resources (`upload` and `random`) and corresponding methods (`POST` and `GET`).
8. **API Gateway Integrations**: Configures integrations between the API Gateway methods and the S3 bucket.
9. **API Gateway Deployment**: Deploys the API to a `prod` stage.

This configuration sets up a basic infrastructure to handle the specified functionality using AWS services. Adjustments may be needed based on specific requirements or additional features.

