LLM Output #0:
### Description

The Terraform program will define an infrastructure that includes an AWS API Gateway, AWS S3 bucket, and AWS Lambda function. The API Gateway will expose endpoints for uploading cat pictures and retrieving random cat pictures from the S3 bucket. The Lambda function will handle the logic for these operations.

- **AWS S3 Bucket**: This will store the uploaded cat pictures.
- **AWS Lambda Function**: This will process requests to upload and retrieve cat pictures.
- **AWS API Gateway**: This will provide HTTP endpoints for interacting with the Lambda function.

### Terraform Configuration

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store cat pictures"
  default     = "cat-pictures-bucket-${random_string.bucket_suffix.result}"
}

variable "lambda_function_name" {
  description = "The name of the Lambda function"
  default     = "CatPictureServiceLambda"
}

variable "api_gateway_name" {
  description = "The name of the API Gateway"
  default     = "CatPictureAPI"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "${var.lambda_function_name}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_policy" "s3_access_policy" {
  name        = "${var.lambda_function_name}-s3-access-policy"
  description = "Policy to allow Lambda function to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.cat_pictures_bucket.arn,
          "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_s3_access" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}

resource "aws_lambda_function" "cat_picture_service" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "python3.9"
  role          = aws_iam_role.lambda_execution_role.arn

  source_code_hash = filebase64sha256("lambda_function.zip")
  filename         = "lambda_function.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = var.api_gateway_name
  description = "API Gateway for Cat Picture Service"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
