### Description

The Terraform program below sets up an infrastructure on AWS to host a web service that allows users to upload cat pictures and retrieve random cat pictures. The architecture includes:

1. **AWS DynamoDB Table**: To store metadata about the uploaded cat pictures.
2. **AWS S3 Bucket**: To store the actual cat pictures.
3. **AWS Lambda Function**: To handle the logic for uploading and retrieving cat pictures.
4. **AWS Lambda Permission**: To allow API Gateway to invoke the Lambda function.
5. **AWS API Gateway REST API**: To expose the Lambda function as a web service.
6. **AWS API Gateway Resource**: To define the endpoint for the API.
7. **AWS API Gateway Method**: To define the HTTP methods (POST for uploading, GET for retrieving).

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store cat pictures"
  default     = "cat-pictures-bucket"
}

variable "dynamodb_table_name" {
  description = "The name of the DynamoDB table to store metadata"
  default     = "CatPicturesMetadata"
}

variable "lambda_function_name" {
  description = "The name of the Lambda function"
  default     = "CatPictureService"
}

variable "api_gateway_name" {
  description = "The name of the API Gateway"
  default     = "CatPictureAPI"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_dynamodb_table" "cat_pictures_metadata" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "${var.lambda_function_name}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "cat_picture_service" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "python3.9"
  role          = aws_iam_role.lambda_execution_role.arn

  source_code_hash = filebase64sha256("lambda_function.zip")
  filename         = "lambda_function.zip"

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.cat_pictures_metadata.name
      S3_BUCKET_NAME      = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_lambda_permission" "api_gateway_permission" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cat_picture_service.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = aws_api_gateway_rest_api.cat_picture_api.execution_arn
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = var.api_gateway_name
  description = "API Gateway for Cat Picture Service"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "random"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.cat_picture_service.invoke_arn
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_picture_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  integration_http_method = "GET"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.cat_picture_service.invoke_arn
}

resource "aws_api_gateway_deployment" "cat_picture_deployment" {
  depends_on = [
    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  stage_name  = "prod"
}
