### Description

The Terraform program below sets up the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront and AWS S3. The setup includes:

1. **AWS S3 Bucket**: A private S3 bucket to store the video content.
2. **IAM Role and Policy**: An IAM role with permissions to access the S3 bucket.
3. **CloudFront Distribution**: A CloudFront distribution configured to serve the content from the S3 bucket, enabling global content delivery.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "video-streaming-bucket"
}

variable "cloudfront_origin_id" {
  description = "The origin ID for the CloudFront distribution"
  type        = string
  default     = "S3-origin"
}

resource "aws_s3_bucket" "video_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "cloudfront_role" {
  name = "cloudfront-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_policy" {
  name        = "cloudfront-s3-access-policy"
  description = "Policy to allow CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_bucket.id}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudfront_policy_attachment" {
  role       = aws_iam_role.cloudfront_role.name
  policy_arn = aws_iam_policy.cloudfront_policy.arn
}

resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = "${aws_s3_bucket.video_bucket.bucket_regional_domain_name}"
    origin_id   = var.cloudfront_origin_id

    s3_origin_config {
      origin_access_identity = aws_iam_role.cloudfront_role.name
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming CloudFront Distribution"
  default_root_object = "index.html"

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured with a default region (`us-east-1`), which can be overridden using the `region` variable.
- **S3 Bucket**: A private S3 bucket is created to store the video content. Versioning is enabled for data protection.
- **IAM Role and Policy**: An IAM role is created for CloudFront to access the S3 bucket. The role has an attached policy that allows `s3:GetObject` actions on the bucket.
- **CloudFront Distribution**: A CloudFront distribution is set up to serve content from the S3 bucket. It uses the IAM role for authentication and has IPv6 enabled for global reach.

This configuration ensures that the video content is securely stored in S3 and distributed globally via CloudFront.

