### Description

The Terraform program below sets up the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront, AWS Route53, and AWS S3. The architecture includes:

1. **AWS S3 Bucket**: To store the video content.
2. **AWS CloudFront Distribution**: To cache and deliver the video content globally.
3. **AWS Route53 Hosted Zone**: To manage DNS records for the domain.
4. **IAM Roles and Policies**: To ensure secure access between services.

The program also includes a basic setup for logging and monitoring, which can be expanded based on specific requirements.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  type        = string
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store video content"
  type        = string
}

variable "cloudfront_origin_id" {
  description = "The origin ID for the CloudFront distribution"
  default     = "S3-origin"
}

resource "aws_s3_bucket" "video_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = aws_s3_bucket.logging_bucket.bucket
    target_prefix = "log/"
  }
}

resource "aws_s3_bucket" "logging_bucket" {
  bucket = "${var.s3_bucket_name}-logs"
  acl    = "log-delivery-write"
}

resource "aws_iam_role" "cloudfront_logging_role" {
  name = "CloudFrontLoggingRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_logging_policy" {
  name        = "CloudFrontLoggingPolicy"
  description = "Policy to allow CloudFront to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketAcl",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.logging_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudfront_logging_policy_attachment" {
  role       = aws_iam_role.cloudfront_logging_role.name
  policy_arn = aws_iam_policy.cloudfront_logging_policy.arn
}

resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = var.cloudfront_origin_id

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Site Distribution"
  default_root_object = "index.html"

  logging_config {
    enabled          = true
    include_cookies  = false
    bucket           = aws_s3_bucket.logging_bucket.bucket
    prefix           = "cloudfront-logs/"
    iam_role_arn     = aws_iam_role.cloudfront_logging_role.arn
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "OAI for ${aws_s3_bucket.video_bucket.bucket}"
}

resource "aws_route53_zone" "video_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_record" {
  zone_id = aws_route53_zone.video_zone.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

### Explanation

- **AWS S3 Bucket**: Two S3 buckets are created: one for storing video content (`video_bucket`) and another for storing CloudFront logs (`logging_bucket`).
- **IAM Role and Policy**: An IAM role (`cloudfront_logging_role`) and policy (`cloudfront_logging_policy`) are created to allow CloudFront to write logs to the logging bucket.
- **AWS CloudFront Distribution**: A CloudFront distribution is set up to cache and deliver video content from the S3 bucket. It uses an Origin Access Identity (OAI) to securely access the S3 bucket.
- **AWS Route53 Hosted Zone and Record**: A Route53 hosted zone and record are created to map the domain name to the CloudFront distribution.

This configuration ensures that the video streaming site is globally accessible and secure. Adjust the variables and configurations as needed for your specific use case.

