### Description

The Terraform program below sets up the infrastructure for a video streaming site that distributes video content globally. It includes:

1. **AWS S3 Bucket**: To store the video content.
2. **AWS CloudFront Origin Access Control (OAC)**: To restrict access to the S3 bucket from CloudFront only.
3. **AWS CloudFront Distribution**: To cache and deliver the video content globally.
4. **AWS Route53 Hosted Zone**: To manage DNS records for the domain.
5. **AWS Route53 Record Set**: To create a DNS record pointing to the CloudFront distribution.

### Terraform Configuration

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  type        = string
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store video content"
  type        = string
}

resource "aws_s3_bucket" "video_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "cloudfront_origin_access_role" {
  name = "cloudfront-origin-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_origin_access_policy" {
  name        = "cloudfront-origin-access-policy"
  description = "Policy to allow CloudFront to access the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.video_bucket.arn}/*"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_distribution.arn
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudfront_origin_access_policy_attachment" {
  role       = aws_iam_role.cloudfront_origin_access_role.name
  policy_arn = aws_iam_policy.cloudfront_origin_access_policy.arn
}

resource "aws_cloudfront_origin_access_control" "video_oac" {
  name                   = "video-origin-access-control"
  origin_access_control_origin_type = "s3"
  signing_behavior         = "never"
  signing_protocol         = "sigv4"
}

resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.video_bucket.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_control.video_oac.origin_access_identity
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Site Distribution"
  default_root_object = "index.html"

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_route53_zone" "video_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_record" {
  zone_id = aws_route53_zone.video_zone.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

### Explanation

- **AWS S3 Bucket**: The `aws_s3_bucket` resource creates a private S3 bucket to store the video content.
- **IAM Role and Policy**: An IAM role and policy are created to allow CloudFront to access the S3 bucket.
- **CloudFront Origin Access Control**: The `aws_cloudfront_origin_access_control` resource restricts access to the S3 bucket from CloudFront only.
- **CloudFront Distribution**: The `aws_cloudfront_distribution` resource creates a CloudFront distribution to cache and deliver the video content globally.
- **Route53 Zone and Record**: The `aws_route53_zone` and `aws_route53_record` resources manage the DNS records for the domain, pointing it to the CloudFront distribution.

This configuration ensures that the video content is securely stored in S3, delivered globally via CloudFront, and accessible through a custom domain managed by Route53.

