### Description

The Terraform program below sets up the infrastructure for a video streaming site using AWS Load Balancing. It includes:

1. **AWS Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Role and Policy**: Creates an IAM role with necessary permissions for the load balancer and EC2 instances.
3. **Security Groups**: Sets up security groups to allow HTTP traffic on port 80 and SSH access on port 22.
4. **EC2 Instances**: Launches multiple EC2 instances to handle the load.
5. **Target Group**: Defines a target group for the EC2 instances.
6. **Application Load Balancer (ALB)**: Creates an ALB to distribute incoming traffic across the EC2 instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to launch"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
}

variable "key_name" {
  description = "The name of the SSH key pair to use for the EC2 instances"
  default     = "my-key-pair"
}

variable "instance_count" {
  description = "The number of EC2 instances to launch"
  default     = 2
}

resource "aws_iam_role" "lb_role" {
  name = "video-streaming-lb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "lb_policy" {
  name = "video-streaming-lb-policy"
  role = aws_iam_role.lb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_security_group" "web_sg" {
  name        = "video-streaming-web-sg"
  description = "Allow web traffic"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
  default = true
}

resource "aws_instance" "web" {
  count         = var.instance_count
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = data.aws_subnet.default[count.index].id

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

data "aws_subnet" "default" {
  count = var.instance_count
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

resource "aws_lb_target_group" "web" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = data.aws_vpc.default.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb" "web" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [for s in data.aws_subnet.default : s.id]

  security_groups = [aws_security_group.web_sg.id]

  enable_deletion_protection = false
}

resource "aws_lb_listener" "web" {
  load_balancer_arn = aws_lb.web.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }
}

resource "aws_lb_target_group_attachment" "web" {
  count            = var.instance_count
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = aws_instance.web[count.index].id
  port             = 80
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region by default, but this can be changed via the `region` variable.
- **IAM Role and Policy**: An IAM role named `video-streaming-lb-role` is created with a policy that allows the load balancer to describe and manage EC2 instances.
- **Security Groups**: A security group named `video-streaming-web-sg` is created to allow HTTP traffic on port 80 and SSH access on port 22.
- **EC2 Instances**: Multiple EC2 instances are launched using the specified AMI, instance type, and key pair. They are placed in the default VPC's subnets.
- **Target Group**: A target group named `video-streaming-target-group` is created to manage the health checks and routing of traffic to the EC2 instances.
- **Application Load Balancer (ALB)**: An ALB named `video-streaming-alb` is created to distribute incoming HTTP traffic across the EC2 instances.
- **Listener and Target Group Attachment**: A listener is set up on port 80 to forward traffic to the target group, and each EC2 instance is attached to the target group.

This configuration ensures that the video streaming site has a scalable and balanced infrastructure using AWS Load Balancing.

