### Description

The Terraform program below sets up the infrastructure for a video streaming site that includes multiple servers to balance load. It uses AWS services such as:

- **AWS VPC**: To create a virtual private cloud where all resources will reside.
- **AWS EC2**: To launch multiple EC2 instances that will serve as the backend servers for the video streaming site.
- **AWS Load Balancing**: To distribute incoming traffic across the EC2 instances, ensuring high availability and scalability.
- **AWS Route53**: To manage DNS records for the video streaming site.

The program also creates necessary IAM roles and policies to ensure proper access control. Default values are provided for variables to facilitate easy deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to use"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
}

variable "instance_count" {
  description = "The number of EC2 instances to launch"
  default     = 3
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 4.0"

  name         = "video-streaming-vpc"
  cidr         = "10.0.0.0/16"
  azs          = ["${var.region}a", "${var.region}b", "${var.region}c"]
  public_subnets = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnets = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  enable_nat_gateway = true
  single_nat_gateway = true
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_security_group" "web_sg" {
  name        = "video-streaming-web-sg"
  description = "Security group for web traffic"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web" {
  count         = var.instance_count
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = element(module.vpc.public_subnets, count.index)
  security_groups = [aws_security_group.web_sg.name]

  iam_instance_profile = aws_iam_role.ec2_instance_role.name

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

resource "aws_lb" "web" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = module.vpc.public_subnets
  security_groups    = [aws_security_group.web_sg.id]
}

resource "aws_lb_target_group" "web" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "web" {
  load_balancer_arn = aws_lb.web.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }
}

resource "aws_route53_record" "web" {
  zone_id = data.aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_lb.web.dns_name
    zone_id                = aws_lb.web.hosted_zone_id
    evaluate_target_health = true
  }
}

data "aws_route53_zone" "main" {
  name = var.domain_name
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`).
2. **Variables**: Several variables are defined with default values to customize the deployment.
3. **VPC Module**: The `terraform-aws-modules/vpc/aws` module is used to create a VPC with public and private subnets.
4. **IAM Role**: An IAM role is created for the EC2 instances with an attached policy allowing S3 read-only access.
5. **Security Group**: A security group is created to allow HTTP and HTTPS traffic.
6. **EC2 Instances**: Multiple EC2 instances are launched in the public subnets.
7. **Application Load Balancer (ALB)**: An ALB is created to distribute traffic across the EC2 instances.
8. **Target Group**: A target group is associated with the ALB to manage the instances.
9. **Route53 Record**: A DNS record is created in Route53 to point the domain name to the ALB.

This configuration ensures that the video streaming site is highly available and scalable, with traffic balanced across multiple servers.

