### Description

The Terraform program below sets up the infrastructure for a video streaming site with load balancing. It includes:

- **AWS VPC**: A Virtual Private Cloud to host the network resources.
- **AWS Subnets**: Two subnets within the VPC for redundancy.
- **AWS Security Group**: To control inbound and outbound traffic to the EC2 instances.
- **AWS EC2 Instances**: Multiple EC2 instances to handle the load.
- **AWS Load Balancer**: An Application Load Balancer (ALB) to distribute incoming traffic across the EC2 instances.
- **AWS Target Group**: A target group for the ALB to manage the health of the EC2 instances.
- **AWS Route53 Zone**: A hosted zone for the domain.
- **AWS Route53 Record**: A DNS record to map the domain to the ALB.

This setup ensures high availability and scalability for the video streaming site.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to use"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
}

variable "key_name" {
  description = "The name of the SSH key pair to use for the EC2 instances"
  default     = ""
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name         = "video-streaming-vpc"
  cidr         = "10.0.0.0/16"
  azs          = ["${var.region}a", "${var.region}b"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.101.0/24", "10.0.102.0/24"]

  enable_nat_gateway = true
  single_nat_gateway = true

  tags = {
    Name = "video-streaming-vpc"
  }
}

resource "aws_security_group" "web" {
  name        = "video-streaming-sg"
  description = "Allow web traffic"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-sg"
  }
}

resource "aws_instance" "web" {
  count         = 2
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = element(module.vpc.private_subnets, count.index)
  vpc_security_group_ids = [aws_security_group.web.id]

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

resource "aws_lb" "web" {
  name               = "video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = module.vpc.public_subnets

  tags = {
    Name = "video-streaming-alb"
  }
}

resource "aws_lb_target_group" "web" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-tg"
  }
}

resource "aws_lb_listener" "web" {
  load_balancer_arn = aws_lb.web.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }
}

resource "aws_lb_target_group_attachment" "web" {
  count            = length(aws_instance.web)
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = element(aws_instance.web[*].id, count.index)
  port             = 80
}

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = "video-streaming-zone"
  }
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_lb.web.dns_name
    zone_id                = aws_lb.web.zone_id
    evaluate_target_health = true
  }
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`).
- **Variables**: Several variables are defined to allow customization, such as the region, instance type, AMI ID, key name, and domain name.
- **VPC Module**: The `terraform-aws-modules/vpc/aws` module is used to create a VPC with public and private subnets.
- **Security Group**: A security group is created to allow HTTP and HTTPS traffic.
- **EC2 Instances**: Two EC2 instances are launched in the private subnets.
- **Load Balancer and Target Group**: An Application Load Balancer and a target group are set up to distribute traffic to the EC2 instances.
- **Route53 Zone and Record**: A Route53 hosted zone and record are created to map the domain to the ALB.

This configuration provides a robust and scalable infrastructure for a video streaming site.

