### Description

The Terraform program below defines an AWS infrastructure setup that includes:

1. **VPC**: A Virtual Private Cloud with a CIDR block of `10.0.0.0/16`.
2. **Subnets**: Three subnets within the VPC, each with their own CIDR blocks (`10.0.4.0/24`, `10.0.5.0/24`, and `10.0.6.0/24`).
3. **Security Group**: A security group associated with the VPC that allows inbound traffic on port 80 from the VPC's IP range and outbound traffic on port 80 to any IP.
4. **Application Load Balancer (ALB)**: An ALB configured with the previously created security group and subnets.
5. **Target Group**: A target group linked to the ALB, listening on port 80 with the HTTP protocol.
6. **Listener**: A listener attached to the ALB that forwards traffic to the target group.
7. **EC2 Instance**: An EC2 instance running the latest Ubuntu AMI, attached to the target group.
8. **Route53 Zone**: A Route53 hosted zone for the domain `test-video-stream.com`.
9. **Route53 Alias Records**: Two alias records (`lb.test-video-stream.com`) pointing to the ALB's DNS name, with health evaluation enabled.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for the subnets"
  default     = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

variable "instance_ami" {
  description = "AMI ID for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Ubuntu, replace with the latest
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

resource "aws_subnet" "subnet" {
  count             = length(var.subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "web" {
  name        = "web-sg"
  description = "Allow web traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "app" {
  name               = "app-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.web.id]
  subnets            = aws_subnet.subnet[*].id
}

resource "aws_lb_target_group" "app" {
  name     = "app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_instance" "web" {
  ami           = var.instance_ami
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet[0].id

  tags = {
    Name = "web-server"
  }
}

resource "aws_lb_target_group_attachment" "web" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.web.id
  port             = 80
}

resource "aws_route53_zone" "primary" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "lb"
  type    = "A"
  alias {
    name                   = aws_lb.app.dns_name
    zone_id                = aws_lb.app.hosted_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "ipv6" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = ""
  type    = "AAAA"
  alias {
    name                   = aws_lb.app.dns_name
    zone_id                = aws_lb.app.hosted_zone_id
    evaluate_target_health = true
  }
}
```

### Notes

- The `instance_ami` variable is set to a default Ubuntu AMI ID. You should replace this with the latest Ubuntu AMI ID for your desired region.
- The `aws_availability_zones` data source is used to ensure that subnets are created in different availability zones.
- The Route53 records are configured to use the ALB's DNS name as an alias, with health evaluation enabled.

