### Description

The Terraform program below sets up a Virtual Private Cloud (VPC) with public subnets in AWS. It also creates a security group specifically for database access. A PostgreSQL database instance is then provisioned within this VPC, secured by the designated security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  description = "The instance class for the RDS PostgreSQL instance"
  type        = string
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "The database engine for the RDS instance"
  type        = string
  default     = "postgres"
}

variable "db_engine_version" {
  description = "The version of the database engine"
  type        = string
  default     = "13.7"
}

variable "db_name" {
  description = "The name of the database"
  type        = string
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  type        = string
  sensitive   = true
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "PublicSubnet-${count.index + 1}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainIGW"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db_access" {
  name        = "db-access-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to restrict access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBAccessSG"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "MainDBSubnetGroup"
  }
}

resource "aws_db_instance" "postgres" {
  allocated_storage    = 20
  engine               = var.db_engine
  engine_version       = var.db_engine_version
  instance_class       = var.db_instance_class
  name                 = var.db_name
  username             = var.db_username
  password             = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db_access.id]

  skip_final_snapshot = true

  tags = {
    Name = "PostgreSQLInstance"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the deployment, such as the VPC CIDR block, public subnet CIDR blocks, database instance class, and database credentials.

3. **VPC and Subnets**: A VPC is created with the specified CIDR block. Public subnets are created within the VPC, one in each availability zone.

4. **Internet Gateway and Route Table**: An internet gateway is attached to the VPC, and a route table is configured to route traffic to the internet gateway.

5. **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address. This can be restricted further as needed.

6. **Database Subnet Group**: A database subnet group is created to associate the public subnets with the RDS instance.

7. **PostgreSQL Database Instance**: A PostgreSQL RDS instance is launched within the VPC, using the specified instance class, engine, and version. The instance is associated with the database subnet group and the security group.

This configuration ensures that the PostgreSQL database is securely deployed within a VPC with public subnets, accessible via the designated security group.

