### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "my-postgres-db"
}

variable "db_username" {
  description = "Username for the RDS instance"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS instance"
  sensitive   = true
  default     = "securepassword123"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS instance in GB"
  default     = 5
}

variable "db_engine_version" {
  description = "Engine version for the RDS instance"
  default     = "17.1"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db_access" {
  name        = "db-access-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to restrict access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = "db.t3.micro"
  allocated_storage       = var.db_allocated_storage
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.default.name
  vpc_security_group_ids  = [aws_security_group.db_access.id]
  skip_final_snapshot     = true
  publicly_accessible     = true
}

resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = aws_subnet.public[*].id
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the VPC, subnets, and database instance settings.
3. **VPC and Subnets**: A VPC is created with a specified CIDR block. Public subnets are created within this VPC.
4. **Internet Gateway and Route Table**: An internet gateway is attached to the VPC, and a route table is configured to route traffic to the internet.
5. **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address. Outbound traffic is allowed to any destination.
6. **Database Instance**: A PostgreSQL database instance is created within the VPC, using the specified version and storage capacity. The instance is associated with the security group and subnet group.

This configuration ensures that the PostgreSQL database is securely set up within a VPC, with appropriate network access controls.

