### Description

The Terraform program below provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services such as RDS, subnets, and KMS for encryption. The configuration includes:

- **VPC**: A pre-existing Virtual Private Cloud where the database will be deployed.
- **Subnets**: Two public subnets within the VPC for high availability.
- **KMS Key**: A customer-managed AWS Key Management Service (KMS) key for encrypting the database.
- **Parameter Group**: A custom PostgreSQL parameter group to configure specific settings.
- **Security Group**: A security group to control inbound traffic to the database.
- **RDS Instance**: A PostgreSQL database instance with multi-AZ deployment for high availability, encrypted storage, and specified configurations like storage size and engine version.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "A list of two subnet IDs within the VPC for high availability"
  type        = list(string)
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  type        = string
  default     = "secure-postgres-db"
}

variable "db_name" {
  description = "The name of the database"
  type        = string
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database administrator"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database administrator"
  type        = string
  sensitive   = true
}

variable "db_engine_version" {
  description = "The version of the PostgreSQL engine"
  type        = string
  default     = "13.6"
}

variable "db_storage_size" {
  description = "The storage size of the database in gigabytes"
  type        = number
  default     = 20
}

variable "kms_key_arn" {
  description = "The ARN of the KMS key for encryption"
  type        = string
}

resource "aws_kms_key" "db_encryption_key" {
  count         = var.kms_key_arn == "" ? 1 : 0
  description   = "KMS key for RDS encryption"
  deletion_window_in_days = 7
  enable_key_rotation = true
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name        = "${var.db_instance_identifier}-param-group"
  family      = "postgres${replace(var.db_engine_version, ".", "")}"
  description = "Custom parameter group for PostgreSQL"

  parameter {
    name  = "rds.logical_replication"
    value = "1"
  }
}

resource "aws_security_group" "db_security_group" {
  name        = "${var.db_instance_identifier}-security-group"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to restrict access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db" {
  identifier              = var.db_instance_identifier
  allocated_storage       = var.db_storage_size
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = "db.t3.medium"
  name                    = var.db_name
  username                = var.db_username
  password                = var.db_password
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  db_subnet_group_name    = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
  multi_az                = true
  storage_encrypted       = true
  kms_key_id              = var.kms_key_arn != "" ? var.kms_key_arn : aws_kms_key.db_encryption_key[0].arn
  backup_retention_period = 7
  skip_final_snapshot     = true
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "${var.db_instance_identifier}-subnet-group"
  subnet_ids = var.subnet_ids
}
```

### Notes

- **Variables**: The configuration uses several variables to allow customization, such as the VPC ID, subnet IDs, and database credentials. Default values are provided where applicable.
- **KMS Key**: If a KMS key ARN is not provided, a new KMS key is created automatically.
- **Security Group**: The security group allows inbound traffic on port 5432 from any IP address (`0.0.0.0/0`). This should be restricted to specific IP addresses or CIDR blocks for security purposes.
- **Multi-AZ Deployment**: The database instance is configured for high availability with multi-AZ deployment.
- **Encryption**: The database storage is encrypted using the specified KMS key or a newly created one if none is provided.

This Terraform configuration is designed to be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. Ensure that the necessary permissions are granted to the IAM role or user executing the Terraform commands.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region  = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"

  name = "main-vpc"
  cidr = "10.0.0.0/16"

  azs                  = data.aws_availability_zones.available.names
  public_subnets       = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

resource "aws_db_subnet_group" "db-subnet-group" {
  name       = "db-subnet-group"
  subnet_ids = module.vpc.public_subnets
}

resource "aws_security_group" "db-sg" {
  name = "db-sg"
  vpc_id = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "db-sg-ingress-rule" {
  from_port       = 5432
  to_port         = 5432
  ip_protocol     = "tcp"
  cidr_ipv4       = "0.0.0.0/0"
  security_group_id = aws_security_group.db-sg.id
}

resource "aws_vpc_security_group_egress_rule" "db-sg-egress-rule" {
  from_port       = 5432
  to_port         = 5432
  ip_protocol     = "tcp"
  cidr_ipv4       = "0.0.0.0/0"
  security_group_id = aws_security_group.db-sg.id
}

resource "aws_db_parameter_group" "postgre-param-group" {
  name   = "pgparamgrp15"
  family = "postgres15"

  parameter {
    name  = "password_encryption"
    value = "scram-sha-256"
  }

  parameter {
    name  = "rds.force_ssl"
    value = "0"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_kms_key" "rds-key" {
  description             = "kmsrds"
  deletion_window_in_days = 14
}

resource "aws_db_instance" "postgres" {
  identifier                      = "pg"
  skip_final_snapshot             = true
  allocated_storage               = 50
  backup_retention_period         = 7
  db_subnet_group_name            = aws_db_subnet_group.db-subnet-group.id
  parameter_group_name            = aws_db_parameter_group.postgre-param-group.name
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]
  engine                          = "postgres"
  engine_version                  = "15"
  instance_class                  = "db.t3.micro"
  db_name                         = "postgres" # Initial database name
  username                        = "myusername"
  password                        = "mypassword"
  vpc_security_group_ids          = [aws_security_group.db-sg.id]
  # Other security settings
  publicly_accessible             = true
  multi_az                        = true
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.rds-key.arn
  # Default daily backup window
  # https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html#USER_WorkingWithAutomatedBackups.BackupWindow
}

