}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  default     = "my-postgres-db"
}

variable "db_username" {
  description = "The username for the RDS instance"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the RDS instance"
  sensitive   = true
}

variable "db_allocated_storage" {
  description = "The allocated storage size for the RDS instance (in GB)"
  default     = 20
}

variable "db_engine_version" {
  description = "The engine version for the RDS instance"
  default     = "13.6"
}

variable "db_instance_class" {
  description = "The instance class for the RDS instance"
  default     = "db.t3.medium"
}

resource "aws_kms_key" "rds_kms_key" {
  description             = "KMS key for RDS encryption"
  deletion_window_in_days = 10
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name   = "${var.db_instance_identifier}-param-group"
  family = "postgres${replace(var.db_engine_version, ".", "")}"

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "pending-reboot"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${var.db_instance_identifier}-sg"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to your desired IP range
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db" {
  identifier              = var.db_instance_identifier
  username                = var.db_username
  password                = var.db_password
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  allocated_storage       = var.db_allocated_storage
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  kms_key_id              = aws_kms_key.rds_kms_key.arn
  multi_az                = true
  final_snapshot_identifier = "pgsnapshot"

  skip_final_snapshot = false
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "${var.db_instance_identifier}-subnet-group"
  subnet_ids = var.subnet_ids
}
```

### Notes

- **Security Group**: The security group allows inbound traffic on port 5432 from any IP address (`0.0.0.0/0`). This should be adjusted to restrict access to specific IP ranges for security purposes.
- **Final Snapshot**: The `final_snapshot_identifier` is set to "pgsnapshot". Ensure that this identifier is unique across your AWS account.
- **Provider and Region**: The provider is configured for the `us-west-2` region by default, but this can be changed via the `region` variable.
- **Variables**: All necessary variables are defined with default values where applicable. Ensure that sensitive information like passwords is handled securely.

