  type        = string
}

variable "public_subnet_ids" {
  description = "A list of public subnet IDs where the RDS instance will be deployed"
  type        = list(string)
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  default     = "airbyte-postgres"
}

variable "db_name" {
  description = "The name of the database"
  default     = "airbyte_db"
}

variable "db_username" {
  description = "The username for the database"
  default     = "airbyte_user"
}

variable "db_password" {
  description = "The password for the database"
  type        = string
  sensitive   = true
}

resource "aws_iam_role" "rds_iam_role" {
  name = "${var.db_instance_identifier}-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_rds_instance" "postgres_instance" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = "15"
  instance_class          = "db.m6.large"
  allocated_storage       = 500
  storage_type            = "gp3"
  db_name                 = var.db_name
  username                = var.db_username
  password                = var.db_password
  vpc_security_group_ids  = [aws_security_group.postgres_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.postgres_subnet_group.name
  publicly_accessible     = true
  iam_database_authentication_enabled = true
  monitoring_interval     = 60
  monitoring_role_arn     = aws_iam_role.rds_iam_role.arn
}

resource "aws_security_group" "postgres_sg" {
  name        = "${var.db_instance_identifier}-sg"
  description = "Security group for RDS PostgreSQL instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name       = "${var.db_instance_identifier}-subnet-group"
  subnet_ids = var.public_subnet_ids
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden by setting the `region` variable.

2. **Variables**: Several variables are defined to allow customization of the deployment, such as the VPC ID, public subnet IDs, database instance identifier, database name, username, and password.

3. **IAM Role and Policy**: An IAM role is created with the necessary permissions to manage the RDS instance. The role is attached to the `AmazonRDSFullAccess` policy.

4. **RDS Instance**: A PostgreSQL 15 instance is created with the specified parameters, including storage size, instance class, and security group. The instance is publicly accessible and uses IAM database authentication.

5. **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address.

6. **DB Subnet Group**: A DB subnet group is created to specify the subnets where the RDS instance will be deployed.

This configuration ensures that the PostgreSQL instance is set up with minimal maintenance requirements while being accessible for running Airbyte connector test cases.

