The Terraform program below sets up a 5 GB PostgreSQL database instance in AWS. It includes the following configurations:

- **Engine Version**: PostgreSQL 13
- **Instance Size**: db.t3.micro
- **Storage**: 5 GB with a maximum allocated storage of 50 GB
- **Maintenance Window**: 0:00 to 3:00 AM on Monday
- **Networking Resources**: Custom VPC and Subnet

The program also creates necessary IAM roles and policies for the RDS instance. All resources are defined within a valid AWS region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "my-postgres-db"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  default     = "securepassword123"
  sensitive   = true
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Security group for RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.main.id]
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_db_instance" "postgres" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = "13"
  instance_class          = "db.t3.micro"
  allocated_storage       = 5
  max_allocated_storage   = 50
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db_sg.id]
  maintenance_window      = "mon:00:00-mon:03:00"
  backup_retention_period = 7
  skip_final_snapshot     = true
  iam_database_authentication_enabled = true
  iam_roles               = [aws_iam_role.rds_iam_role.arn]
}
```

