  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage for the RDS instance in GB"
  default     = 20
}

variable "engine_version" {
  description = "Engine version for the RDS instance"
  default     = "13.7"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  default     = "securepassword123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "db_sg" {
  name        = "db-security-group"
  description = "Security group for RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_rds_instance" "postgres" {
  identifier              = var.db_instance_identifier
  instance_class          = var.db_instance_class
  allocated_storage       = var.allocated_storage
  engine                  = "postgres"
  engine_version          = var.engine_version
  name                    = var.db_name
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db_sg.id]
  publicly_accessible     = false
  auto_minor_version_upgrade = true
  allow_major_version_upgrade = true
  iam_database_authentication_enabled = true
  iam_roles               = [aws_iam_role.rds_iam_role.name]
}

resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.main.id]
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`).
- **Variables**: Various variables are defined to allow customization of the deployment, such as the region, VPC CIDR block, subnet CIDR block, and database instance details.
- **VPC and Subnet**: A VPC and subnet are created to host the RDS instance.
- **Security Group**: A security group is configured to allow inbound traffic on port 5432 from within the VPC and outbound traffic to any destination.
- **IAM Role**: An IAM role is created for the RDS instance to manage its operations.
- **RDS Instance**: An Amazon RDS PostgreSQL instance is created with the specified configurations, including automatic minor version upgrades and the ability to perform major version upgrades. The instance is not publicly accessible.

This configuration is deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`.

