### Description

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with an associated proxy for enhanced connection management. The setup includes:

- **VPC**: A Virtual Private Cloud (VPC) to host the Aurora cluster and proxy.
- **Subnets**: Two public and two private subnets within the VPC.
- **Security Groups**: Security groups for both the Aurora cluster and the proxy to control inbound and outbound traffic.
- **IAM Roles**: An IAM role for the Aurora proxy to access the Aurora cluster.
- **Secrets Manager**: A secret to store the database credentials securely.
- **RDS Aurora Cluster**: An Aurora MySQL cluster configured with the specified settings.
- **RDS Proxy**: A proxy associated with the Aurora cluster to manage connections efficiently.

The RDS proxy is configured with an idle client timeout of 1800 seconds and debug logging disabled.

### Terraform Configuration

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_name" {
  description = "The name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  default     = "securepassword123"
}

variable "instance_class" {
  description = "The instance class for the Aurora cluster"
  default     = "db.r5.large"
}

variable "allocated_storage" {
  description = "The allocated storage for the Aurora cluster"
  default     = 20
}

variable "engine_version" {
  description = "The engine version for the Aurora cluster"
  default     = "8.0.mysql_aurora.3.02.0"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "aurora_sg" {
  name        = "aurora-sg"
  description = "Allow inbound traffic from the proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_rds_proxy.proxy.endpoint]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "proxy_sg" {
  name        = "proxy-sg"
  description = "Allow inbound traffic from the application"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to your application's IP range
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "proxy_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/RDSProxyRolePolicy"
  role       = aws_iam_role.proxy_role.name
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = var.engine_version
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.aurora_sg.id]
  skip_final_snapshot     = true
  iam_database_authentication_enabled = true
}

resource "aws_rds_cluster_instance" "aurora_instance" {
  count              = 2
  identifier         = "aurora-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.aurora.id
  instance_class     = var.instance_class
  engine             = aws_rds_cluster.aurora.engine
  engine_version     = aws_rds_cluster.aurora.engine_version
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
}

resource "aws_rds_proxy" "proxy" {
  name                   = "aurora-proxy"
  db_cluster_identifier  = aws_rds_cluster.aurora.id
  role_arn               = aws_iam_role.proxy_role.arn
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]
  vpc_subnet_ids         = aws_subnet.public[*].id
  idle_client_timeout    = 1800
  debug_logging          = false
  require_tls            = true
}

resource "aws_rds_proxy_default_target_group" "default" {
  db_proxy_name = aws_rds_proxy.proxy.name
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Default values are provided for database name, username, password, instance class, allocated storage, and engine version.
- **VPC and Subnets**: A VPC is created with four subnets (two public and two private).
- **Security Groups**: Security groups are defined for the Aurora cluster and the proxy.
- **IAM Role**: An IAM role is created for the RDS proxy with the necessary permissions.
- **Secrets Manager**: A secret is stored in Secrets Manager to hold the database credentials.
- **RDS Aurora Cluster**: An Aurora MySQL cluster is set up with the specified configurations.
- **RDS Proxy**: A proxy is created to manage connections to the Aurora cluster with the specified settings.

This configuration ensures a secure and efficient setup for managing database connections using AWS RDS Aurora and RDS Proxy.

