### Description

This Terraform configuration sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. The setup includes:

- **VPC**: A Virtual Private Cloud (VPC) to host the database resources.
- **Subnets**: Two public and two private subnets within the VPC.
- **Security Groups**: Security groups to control inbound and outbound traffic to the RDS cluster and the proxy.
- **IAM Roles**: An IAM role for the RDS proxy to access the RDS cluster.
- **Secrets Manager**: A secret to store the database credentials securely.

The RDS cluster uses the Aurora MySQL engine version `8.0.mysql_aurora.3.08.0`.

### Terraform Configuration

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for the RDS Aurora MySQL cluster"
  default     = "db.r5.large"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  sensitive   = true
  default     = "securepassword123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for RDS Aurora MySQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "proxy_sg" {
  name        = "proxy-sg"
  description = "Security group for RDS Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_proxy_role" {
  name = "rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_proxy_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/RDSProxyRolePolicy"
  role       = aws_iam_role.rds_proxy_role.name
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "aurora-cluster-demo"
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.08.0"
  database_name           = var.db_name
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db_sg.id]
  iam_database_authentication_enabled = true
}

resource "aws_db_subnet_group" "main" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"
}

resource "aws_secretsmanager_secret_version" "db_credentials_version" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_rds_proxy" "main" {
  name                   = "aurora-proxy-demo"
  db_cluster_identifier  = aws_rds_cluster.main.id
  role_arn               = aws_iam_role.rds_proxy_role.arn
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]
  vpc_subnet_ids         = aws_subnet.public[*].id
  require_tls            = true
}

output "db_cluster_endpoint" {
  value = aws_rds_cluster.main.endpoint
}

output "db_proxy_endpoint" {
  value = aws_rds_proxy.main.endpoint
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Several variables are defined to allow customization of the VPC, subnets, instance class, database name, username, and password.
- **VPC and Subnets**: A VPC is created with public and private subnets.
- **Security Groups**: Security groups are set up for the RDS cluster and the proxy to allow necessary traffic.
- **IAM Role**: An IAM role is created for the RDS proxy with the necessary permissions.
- **RDS Cluster**: An Aurora MySQL cluster is created with the specified engine and version.
- **DB Subnet Group**: A subnet group is created for the RDS cluster.
- **Secrets Manager**: A secret is created to store the database credentials securely.
- **RDS Proxy**: An RDS proxy is created to manage connections to the RDS cluster.
- **Outputs**: The endpoints for the RDS cluster and the proxy are outputted for easy reference.

