### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the Lightsail instance"
  type        = string
  default     = "us-east-1"
}

variable "instance_name" {
  description = "The name of the Lightsail instance"
  type        = string
  default     = "my-lightsail-instance"
}

variable "availability_zone" {
  description = "The availability zone for the Lightsail instance"
  type        = string
  default     = "us-east-1a"
}

variable "blueprint_id" {
  description = "The blueprint ID for the Lightsail instance"
  type        = string
  default     = "ubuntu_20_04"
}

variable "bundle_id" {
  description = "The bundle ID for the Lightsail instance"
  type        = string
  default     = "nano_1_0"
}

variable "user_data" {
  description = "User data to run on the instance at launch time"
  type        = string
  default     = <<-EOF
                #!/bin/bash
                echo "Hello, World!" > /var/www/html/index.html
                EOF
}

resource "aws_iam_role" "lightsail_role" {
  name = "LightsailInstanceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.lightsail_role.name
}

