### Description

The Terraform program below creates an AWS Lightsail instance with multiple attached disks. The configuration includes:

- A Lightsail instance with a specified blueprint and bundle.
- Multiple Lightsail disks attached to the instance.
- An IAM role with necessary permissions for Lightsail operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the Lightsail instance"
  default     = "us-east-1"
}

variable "instance_name" {
  description = "The name of the Lightsail instance"
  default     = "my-lightsail-instance"
}

variable "blueprint_id" {
  description = "The ID of the Lightsail blueprint"
  default     = "ubuntu_20_04"
}

variable "bundle_id" {
  description = "The ID of the Lightsail bundle"
  default     = "small_2_0"
}

variable "disk_names" {
  description = "List of disk names to attach to the Lightsail instance"
  type        = list(string)
  default     = ["disk1", "disk2"]
}

variable "disk_sizes" {
  description = "List of disk sizes (in GB) corresponding to the disk names"
  type        = list(number)
  default     = [20, 30]
}

resource "aws_iam_role" "lightsail_role" {
  name = "LightsailInstanceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
  role       = aws_iam_role.lightsail_role.name
}

resource "aws_lightsail_instance" "example" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = var.key_pair_name
  iam_role_name     = aws_iam_role.lightsail_role.name
}

resource "aws_lightsail_disk" "example" {
  count = length(var.disk_names)

  name              = element(var.disk_names, count.index)
  size_in_gb        = element(var.disk_sizes, count.index)
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "aws_lightsail_disk_attachment" "example" {
  count = length(var.disk_names)

  disk_name   = element(aws_lightsail_disk.example[*].name, count.index)
  instance_name = aws_lightsail_instance.example.name
}

data "aws_availability_zones" "available" {
  state = "available"
}
```

### Notes

- **IAM Role**: An IAM role with the `AmazonLightsailFullAccess` policy is created to allow the Lightsail instance to perform necessary operations.
- **Disks**: Multiple disks can be attached to the instance by specifying their names and sizes in the `disk_names` and `disk_sizes` variables.
- **Availability Zone**: The instance and disks are deployed in the first available availability zone in the specified region.
- **Key Pair**: Ensure that the `key_pair_name` variable is set to an existing Lightsail key pair in your AWS account to enable SSH access to the instance.

