  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name        = "LongTermDataBackup"
    Environment = "production"
  }
}

resource "aws_iam_role" "s3_access_role" {
  name = "S3AccessRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "s3_access_policy" {
  name        = "S3AccessPolicy"
  description = "Policy to allow read/write access to the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.long_term_data_backup.arn}",
          "${aws_s3_bucket.long_term_data_backup.arn}/*"
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_role" {
  role       = aws_iam_role.s3_access_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.

2. **Variables**:
   - `region`: Specifies the AWS region where the resources will be deployed.
   - `bucket_name`: Specifies the name of the S3 bucket.

3. **S3 Bucket**:
   - The `aws_s3_bucket` resource creates a private S3 bucket with versioning enabled to ensure data durability and recovery.
   - Server-side encryption is enabled using AES256 to protect data at rest.
   - Tags are added for better management and identification.

4. **IAM Role and Policy**:
   - An IAM role (`S3AccessRole`) is created with a trust policy allowing EC2 instances to assume the role.
   - An IAM policy (`S3AccessPolicy`) is defined to grant read/write access to the S3 bucket.
   - The policy is attached to the IAM role using `aws_iam_role_policy_attachment`.

