The Terraform program below will create an S3 Glacier vault and configure AWS Data Lifecycle Manager (DLM) to transition objects from an S3 bucket to the Glacier vault after a specified number of days. The program includes the necessary IAM roles and policies to ensure proper access and permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "my-s3-bucket"
}

variable "glacier_vault_name" {
  description = "The name of the S3 Glacier vault"
  type        = string
  default     = "my-glacier-vault"
}

variable "transition_days" {
  description = "Number of days after which objects should be transitioned to Glacier"
  type        = number
  default     = 30
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = var.bucket_name
  acl    = "private"
}

resource "aws_s3_glacier_vault" "my_vault" {
  name = var.glacier_vault_name
}

resource "aws_iam_role" "dlm_role" {
  name = "dlm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "dlm_policy" {
  name = "dlm-policy"
  role = aws_iam_role.dlm_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:GetObjectAcl",
          "s3:PutObjectAcl",
          "s3:DeleteObject",
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
          "glacier:InitiateJob",
          "glacier:UploadMultipartPart",
          "glacier:CompleteMultipartUpload",
          "glacier:AbortMultipartUpload",
          "glacier:GetJobOutput",
          "glacier:DescribeVault"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.my_bucket.arn}",
          "${aws_s3_bucket.my_bucket.arn}/*",
          "${aws_s3_glacier_vault.my_vault.arn}"
        ]
      },
    ]
  })
}

resource "aws_dlm_lifecycle_policy" "my_policy" {
  description = "Transition objects to Glacier after ${var.transition_days} days"
  state       = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    schedule {
      name = "transition-to-glacier"

      create_rule {
        interval      = var.transition_days
        interval_unit = "DAY"
        times         = ["23:45"]
      }

      transition {
        count          = 1
        storage_class  = "GLACIER"
        transition_to  = "GLACIER"
      }
    }

    target_tags = {
      Name = "MyLifecyclePolicy"
    }

    parameters {
      exclude_boot_volume = true
    }
  }

  execution_role_arn = aws_iam_role.dlm_role.arn
}
