### Description

The Terraform program below defines an AWS S3 Glacier vault and sets up a notification configuration to send a message to an Amazon SNS topic when an archive retrieval is completed. The program includes the necessary IAM roles and policies to allow the S3 Glacier service to publish messages to the SNS topic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "vault_name" {
  description = "The name of the S3 Glacier vault"
  type        = string
  default     = "my-glacier-vault"
}

variable "sns_topic_name" {
  description = "The name of the SNS topic for notifications"
  type        = string
  default     = "glacier-retrieval-notifications"
}

resource "aws_sns_topic" "glacier_retrieval_notifications" {
  name = var.sns_topic_name
}

resource "aws_iam_role" "glacier_notification_role" {
  name = "${var.vault_name}-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glacier_notification_policy" {
  name        = "${var.vault_name}-notification-policy"
  description = "Policy allowing Glacier to publish to SNS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect   = "Allow"
        Resource = aws_sns_topic.glacier_retrieval_notifications.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glacier_notification_policy_attachment" {
  role       = aws_iam_role.glacier_notification_role.name
  policy_arn = aws_iam_policy.glacier_notification_policy.arn
}

resource "aws_s3_glacier_vault" "my_glacier_vault" {
  name = var.vault_name

  notification {
    sns_topic = aws_sns_topic.glacier_retrieval_notifications.arn
    events    = ["ArchiveRetrievalCompleted"]
  }

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput"
        ]
        Effect   = "Allow"
        Resource = aws_s3_glacier_vault.my_glacier_vault.arn
        Principal = "*"
      }
    ]
  })

  tags = {
    Name = var.vault_name
  }
}
```

