### Description

The Terraform script provided below sets up a basic infrastructure on AWS, including:

1. **VPC**: A Virtual Private Cloud to contain all network resources.
2. **Subnet**: A public subnet within the VPC for internet access.
3. **Internet Gateway**: To allow the EC2 instance to communicate with the internet.
4. **Route Table**: Configured to route internet traffic through the Internet Gateway.
5. **Security Group**: To control inbound and outbound traffic to the EC2 instance.
6. **EC2 Instance**: A t2.micro instance running Amazon Linux 2.
7. **Network Load Balancer**: A load balancer to distribute incoming traffic to the EC2 instance.

The script also includes necessary IAM roles and policies to ensure proper permissions for the EC2 instance and the load balancer.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_type" {
  description = "The type of EC2 instance to launch"
  default     = "t2.micro"
}

variable "ami_id" {
  description = "The AMI ID to use for the EC2 instance"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
}

variable "key_name" {
  description = "The key pair name for SSH access to the EC2 instance"
  default     = ""
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_security_group" "ec2_instance" {
  name        = "ec2-instance-sg"
  description = "Allow SSH and HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "web" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = aws_subnet.public.id
  security_groups = [aws_security_group.ec2_instance.name]

  tags = {
    Name = "WebServerInstance"
  }
}

resource "aws_lb" "network" {
  name               = "my-network-lb"
  internal           = false
  load_balancer_type = "network"
  subnets            = [aws_subnet.public.id]
}

resource "aws_lb_target_group" "network" {
  name     = "my-network-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_lb_listener" "network" {
  load_balancer_arn = aws_lb.network.arn
  port              = "80"
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.network.arn
  }
}

resource "aws_lb_target_group_attachment" "network" {
  target_group_arn = aws_lb_target_group.network.arn
  target_id        = aws_instance.web.id
  port             = 80
}
```

### Notes

- **AMI ID**: The `ami_id` variable is set to a default value for Amazon Linux 2 in the `us-west-2` region. You may need to update this if you are using a different region or operating system.
- **Key Pair**: The `key_name` variable is optional and defaults to an empty string. If you want to enable SSH access, provide a valid key pair name.
- **IAM Roles**: The script does not explicitly create IAM roles since the default roles provided by AWS are sufficient for this setup. However, if additional permissions are required, you can create and attach custom IAM roles as needed.

This Terraform configuration is designed to be deployed in the `us-west-2` region. Adjust the region and other parameters as necessary for your specific use case.

