LLM Output #0:
### Description

The Terraform program below creates an AWS Elastic Load Balancer (ELB) with specified Elastic IPs (EIPs). The ELB will distribute incoming traffic across multiple EC2 instances. The program includes the necessary IAM roles and policies to ensure proper permissions for the ELB to manage the EIPs. Additionally, it sets up a basic security group to allow HTTP traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_ids" {
  type        = list(string)
  description = "List of EC2 instance IDs to attach to the load balancer"
  default     = ["i-1234567890abcdef0", "i-0987654321fedcba0"]
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the load balancer will be created"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  type        = list(string)
  description = "Subnet IDs where the load balancer will be deployed"
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_group_name" {
  type        = string
  description = "Name of the security group to allow HTTP traffic"
  default     = "elb-sg"
}

resource "aws_iam_role" "elb_role" {
  name = "elb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "elb_policy" {
  name        = "elb-policy"
  description = "Policy for ELB to manage EIPs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:AssociateAddress",
          "ec2:DisassociateAddress"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "elb_policy_attach" {
  role       = aws_iam_role.elb_role.name
  policy_arn = aws_iam_policy.elb_policy.arn
}

resource "aws_security_group" "elb_sg" {
  name        = var.security_group_name
  description = "Security group for ELB"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elb" "example" {
  name               = "example-elb"
  availability_zones = ["us-west-2a", "us-west-2b"]

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    unhealthy_threshold = 2
    healthy_threshold   = 2
  }

  instances = var.instance_ids

  security_groups = [aws_security_group.elb_sg.id]

  tags = {
    Name = "example-elb"
  }
}

resource "aws_eip" "elb_eip" {
  count = length(var.subnet_ids)

  vpc = true
  associate_with_private_ip = true
  network_interface = aws_elb.example.instances[count.index].network_interface_id

  tags = {
    Name = "elb-eip-${count.index}"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the configuration, such as instance IDs, VPC ID, subnet IDs, and security group name.
3. **IAM Role and Policy**: An IAM role (`elb-role`) is created with a trust policy allowing the Elastic Load Balancing service to assume it. An IAM policy (`elb-policy`) is created to grant the necessary permissions for the ELB to manage Elastic IPs.
4. **Security Group**: A security group (`elb-sg`) is created to allow HTTP traffic on port 80.
5. **Elastic Load Balancer**: An ELB (`example-elb`) is created with listeners and health checks configured to distribute traffic to the specified EC2 instances.
6. **Elastic IPs**: Elastic IPs (`elb_eip`) are associated with the ELB's network interfaces in the specified subnets.

This configuration ensures that the ELB is properly set up with the necessary permissions and resources to manage Elastic IPs and distribute traffic to the specified EC2 instances.

