### Description

The Terraform program below defines an AWS Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The configuration includes:

- **Provider Configuration**: Sets up the AWS provider with a specified region.
- **Security Group**: Defines a security group to allow HTTP and HTTPS traffic to the load balancer.
- **Target Group**: Creates a target group for the EC2 instances.
- **Load Balancer**: Sets up an Application Load Balancer that listens on port 80 (HTTP) and forwards traffic to the target group.
- **IAM Role**: Creates an IAM role with necessary permissions for the load balancer to register targets.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "The VPC ID where the load balancer and instances will be deployed"
  type        = string
}

variable "instance_ids" {
  description = "List of instance IDs to register in the target group"
  type        = list(string)
  default     = []
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb" "alb" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = data.aws_subnet_ids.default.ids

  listener {
    protocol    = "HTTP"
    port        = 80
    default_action {
      type             = "forward"
      target_group_arn = aws_lb_target_group.target_group.arn
    }
  }
}

resource "aws_iam_role" "lb_role" {
  name = "alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ReadOnlyAccess"
  role       = aws_iam_role.lb_role.name
}

resource "aws_lb_target_group_attachment" "attachment" {
  count            = length(var.instance_ids)
  target_group_arn = aws_lb_target_group.target_group.arn
  target_id        = element(var.instance_ids, count.index)
  port             = 80
}

data "aws_subnet_ids" "default" {
  vpc_id = var.vpc_id
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **Security Group**: The `aws_security_group` resource allows inbound traffic on ports 80 and 443 for HTTP and HTTPS, respectively.
- **Target Group**: The `aws_lb_target_group` resource defines a target group for the EC2 instances, specifying HTTP as the protocol and port 80.
- **Load Balancer**: The `aws_lb` resource creates an Application Load Balancer that listens on port 80 and forwards traffic to the target group.
- **IAM Role**: The `aws_iam_role` and `aws_iam_role_policy_attachment` resources create an IAM role with the necessary permissions for the load balancer to register targets.
- **Target Group Attachment**: The `aws_lb_target_group_attachment` resource registers the specified EC2 instances in the target group.
- **Subnet Data Source**: The `aws_subnet_ids` data source retrieves the subnet IDs for the specified VPC, which are used by the load balancer.

This configuration ensures that the load balancer is properly set up to forward traffic to the specified EC2 instances.

