LLM Output #0:
### Description

The Terraform program below defines an AWS Application Load Balancer (ALB) with a fixed-response action. The ALB listens on port 80 and responds with a fixed HTML content when a request is received. This setup is useful for serving static content or providing a simple HTTP response without routing traffic to backend instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "alb_name" {
  description = "The name of the Application Load Balancer"
  type        = string
  default     = "fixed-response-alb"
}

variable "vpc_id" {
  description = "The ID of the VPC where the ALB will be deployed"
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the ALB will be deployed"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

resource "aws_lb" "fixed_response_alb" {
  name               = var.alb_name
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = var.subnet_ids
}

resource "aws_lb_listener" "fixed_response_listener" {
  load_balancer_arn = aws_lb.fixed_response_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/html"
      message_body = "<html><body><h1>Hello, World!</h1></body></html>"
      status_code  = "200"
    }
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "${var.alb_name}-sg"
  description = "Security group for the Application Load Balancer"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: 
   - `alb_name`: The name of the Application Load Balancer.
   - `vpc_id`: The ID of the VPC where the ALB will be deployed.
