### Description

The Terraform program below defines an AWS Application Load Balancer (ALB) with an "authenticate-cognito" action. This setup involves creating an ALB, a target group, and an authentication configuration using Cognito User Pools. The ALB listens on port 443 for HTTPS traffic and uses the Cognito authentication action to authenticate users before routing them to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "alb_name" {
  description = "Name of the Application Load Balancer"
  type        = string
  default     = "my-alb"
}

variable "target_group_name" {
  description = "Name of the Target Group"
  type        = string
  default     = "my-target-group"
}

variable "vpc_id" {
  description = "ID of the VPC where the ALB and Target Group will be deployed"
  type        = string
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "List of subnet IDs where the ALB will be deployed"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "cognito_user_pool_arn" {
  description = "ARN of the Cognito User Pool"
  type        = string
  default     = "arn:aws:cognito-idp:us-west-2:123456789012:userpool/us-west-2_abcdef123"
}

variable "cognito_client_id" {
  description = "Client ID of the Cognito App Client"
  type        = string
  default     = "abcdef123456"
}

variable "cognito_domain" {
  description = "Domain name of the Cognito User Pool"
  type        = string
  default     = "mydomain.auth.us-west-2.amazoncognito.com"
}

resource "aws_lb" "example" {
  name               = var.alb_name
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.example.id]
  subnets            = var.subnet_ids
}

resource "aws_lb_target_group" "example" {
  name     = var.target_group_name
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = var.cognito_user_pool_arn
      user_pool_client_id = var.cognito_client_id
      user_pool_domain    = var.cognito_domain
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}

resource "aws_security_group" "example" {
  name        = "${var.alb_name}-sg"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the ALB, target group, VPC, subnets, and Cognito settings.
3. **Application Load Balancer (ALB)**: An ALB is created with the specified name, VPC, and subnets. It uses a security group to allow HTTP and HTTPS traffic.
4. **Target Group**: A target group is created to route traffic to the backend instances.
5. **Listener**: A listener is set up on port 443 with an SSL policy and a certificate ARN. The listener includes an "authenticate-cognito" action to authenticate users using Cognito, followed by a forward action to the target group.
6. **Security Group**: A security group is created to allow inbound traffic on ports 80 and 443.

This configuration ensures that the ALB is properly set up to authenticate users using Cognito before routing them to the target group.

