### Description

The Terraform program below defines an AWS Application Load Balancer (ALB) with an Authenticate-OIDC action. This setup includes creating an ALB, a target group, and an IAM role necessary for OIDC authentication. The configuration also sets up a listener rule that triggers the Authenticate-OIDC action when a specific path is accessed.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "alb_name" {
  description = "Name of the Application Load Balancer"
  default     = "my-alb"
}

variable "target_group_name" {
  description = "Name of the Target Group"
  default     = "my-target-group"
}

variable "vpc_id" {
  description = "VPC ID where the ALB and Target Group will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for the ALB"
  type        = list(string)
}

variable "oidc_issuer" {
  description = "OIDC issuer URL"
  type        = string
}

variable "oidc_authorization_endpoint" {
  description = "OIDC authorization endpoint"
  type        = string
}

variable "oidc_token_endpoint" {
  description = "OIDC token endpoint"
  type        = string
}

variable "oidc_user_info_endpoint" {
  description = "OIDC user info endpoint"
  type        = string
}

variable "oidc_client_id" {
  description = "OIDC client ID"
  type        = string
}

variable "oidc_client_secret" {
  description = "OIDC client secret"
  type        = string
  sensitive   = true
}

variable "oidc_scope" {
  description = "OIDC scope"
  type        = string
  default     = "openid email profile"
}

variable "oidc_session_cookie_name" {
  description = "Name of the session cookie"
  type        = string
  default     = "AWSELBAuthSessionCookie"
}

variable "oidc_session_timeout" {
  description = "Session timeout in seconds"
  type        = number
  default     = 3600
}

resource "aws_lb" "example" {
  name               = var.alb_name
  internal           = false
  load_balancer_type = "application"
  security_groups    = []
  subnets            = var.subnet_ids
}

resource "aws_lb_target_group" "example" {
  name     = var.target_group_name
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Default response"
      status_code  = "404"
    }
  }
}

resource "aws_lb_listener_rule" "authenticate_oidc" {
  listener_arn = aws_lb_listener.example.arn
  priority     = 100

  condition {
    field  = "path-pattern"
    values = ["/secure/*"]
  }

  action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = var.oidc_authorization_endpoint
      client_id              = var.oidc_client_id
      client_secret          = var.oidc_client_secret
      issuer                 = var.oidc_issuer
      token_endpoint         = var.oidc_token_endpoint
      user_info_endpoint     = var.oidc_user_info_endpoint
      scope                  = var.oidc_scope
      session_cookie_name    = var.oidc_session_cookie_name
      session_timeout        = var.oidc_session_timeout
    }
  }

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}

resource "aws_iam_role" "oidc_auth_role" {
  name = "oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "oidc_auth_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticLoadBalancingforAWSIAM"
  role       = aws_iam_role.oidc_auth_role.name
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the ALB, target group, and OIDC settings.
3. **Application Load Balancer (ALB)**: An ALB is created with the specified name, VPC, and subnets.
4. **Target Group**: A target group is set up to forward traffic to the specified port and protocol.
5. **Listener**: A listener is created on port 443 with HTTPS protocol.
6. **Listener Rule**: A listener rule is defined to trigger the Authenticate-OIDC action when the path pattern `/secure/*` is matched.
7. **IAM Role**: An IAM role is created for the ALB to perform OIDC authentication.
8. **IAM Policy Attachment**: The necessary policy is attached to the IAM role to allow the ALB to perform OIDC authentication.

This configuration ensures that the ALB is properly set up to handle OIDC authentication for secure paths.

