### Description

The Terraform program below creates a basic AWS RDS instance. It includes the necessary provider configuration, IAM role for the RDS instance, and the RDS instance itself. The configuration uses default values for variables where possible, ensuring that the setup is straightforward and deployable with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the RDS instance"
  type        = string
  default     = "us-west-2"
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  type        = string
  default     = "my-basic-rds-instance"
}

variable "db_instance_class" {
  description = "The instance class for the RDS instance"
  type        = string
  default     = "db.t3.micro"
}

variable "engine" {
  description = "The database engine to use"
  type        = string
  default     = "mysql"
}

variable "engine_version" {
  description = "The version of the database engine"
  type        = string
  default     = "8.0"
}

variable "allocated_storage" {
  description = "The allocated storage size in gigabytes"
  type        = number
  default     = 20
}

variable "master_username" {
  description = "The master username for the RDS instance"
  type        = string
  default     = "admin"
}

variable "master_password" {
  description = "The master password for the RDS instance"
  type        = string
  sensitive   = true
  default     = "password123"
}

resource "aws_iam_role" "rds_iam_role" {
  name = "${var.db_instance_identifier}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_rds_instance" "basic_rds" {
  identifier              = var.db_instance_identifier
  instance_class          = var.db_instance_class
  engine                  = var.engine
  engine_version          = var.engine_version
  allocated_storage       = var.allocated_storage
  master_username         = var.master_username
  master_password         = var.master_password
  iam_database_authentication_enabled = true
  db_subnet_group_name    = aws_db_subnet_group.default.name
  vpc_security_group_ids  = [aws_security_group.default.id]
  skip_final_snapshot     = true
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.db_instance_identifier}-subnet-group"
  subnet_ids = data.aws_subnet_ids.default.ids

  tags = {
    Name = "${var.db_instance_identifier}-subnet-group"
  }
}

data "aws_subnet_ids" "default" {
  vpc_id = var.vpc_id
}

variable "vpc_id" {
  description = "The VPC ID where the RDS instance will be deployed"
  type        = string
  default     = "vpc-12345678"
}

resource "aws_security_group" "default" {
  name        = "${var.db_instance_identifier}-security-group"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

### Notes

- **IAM Role**: An IAM role is created for the RDS instance to allow it to perform certain actions. This role assumes the `rds.amazonaws.com` service.
- **RDS Instance**: The RDS instance is configured with default values for the instance class, engine, engine version, and allocated storage.
- **Security Group**: A security group is created to allow inbound traffic on port 3306 (MySQL default port) from any IP address (`0.0.0.0/0`). Adjust the CIDR block as needed for your security requirements.
- **Subnet Group**: A DB subnet group is created using the subnets associated with the specified VPC.

Make sure to replace the default values for `vpc_id`, `master_username`, and `master_password` with appropriate values for your environment.

