### Description

The Terraform program below creates a basic AWS SQL database using Amazon RDS. It includes the following components:

1. **AWS Provider Configuration**: Sets up the AWS provider with a specified region.
2. **VPC and Subnets**: Creates a Virtual Private Cloud (VPC) and two public subnets.
3. **Security Group**: Configures a security group to allow inbound traffic on port 3306 (MySQL) from anywhere.
4. **RDS Instance**: Deploys a MySQL RDS instance within the VPC and subnet, using the security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "db_instance_identifier" {
  description = "The identifier for the RDS instance"
  default     = "my-basic-db"
}

variable "db_name" {
  description = "The name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  default     = "password123"
  sensitive   = true
}

variable "instance_class" {
  description = "The instance class for the RDS instance"
  default     = "db.t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "MyVPC"
  }
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "PublicSubnet-${count.index}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Allow MySQL access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

resource "aws_db_instance" "basic_db" {
  identifier              = var.db_instance_identifier
  engine                  = "mysql"
  engine_version          = "8.0"
  instance_class          = var.instance_class
  allocated_storage       = 20
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.default.name
  vpc_security_group_ids  = [aws_security_group.db_sg.id]
  skip_final_snapshot     = true

  tags = {
    Name = "BasicDBInstance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "DefaultDBSubnetGroup"
  }
}
```

### Explanation

- **Provider Configuration**: The `aws` provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **VPC and Subnets**: A VPC with a CIDR block of `10.0.0.0/16` is created, along with two public subnets in different availability zones.
- **Security Group**: A security group is set up to allow inbound traffic on port 3306 from any IP address.
- **RDS Instance**: A MySQL RDS instance is deployed with the specified instance class, storage, and credentials. The instance is associated with the VPC, subnets, and security group.

This configuration is deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

