}

variable "allocated_storage" {
  description = "Allocated storage size in gigabytes"
  default     = 20
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  default     = "13.7"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "db" {
  name        = "db-sg"
  description = "Allow PostgreSQL traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id
}

resource "aws_iam_role" "rds" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds-policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds.name
}

resource "aws_db_instance" "postgres" {
  identifier              = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.engine_version
  instance_class          = "db.t4g.large"
  allocated_storage       = var.allocated_storage
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids  = [aws_security_group.db.id]
  skip_final_snapshot     = true
  iam_database_authentication_enabled = true
  iam_roles               = [aws_iam_role.rds.arn]
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the RDS instance, such as the instance identifier, database name, username, password, allocated storage, and engine version.
3. **VPC and Subnets**: A VPC and two public subnets are created to host the RDS instance.
4. **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL).
5. **DB Subnet Group**: A DB subnet group is created to associate the subnets with the RDS instance.
6. **IAM Role**: An IAM role is created with the necessary permissions for the RDS instance.
7. **RDS Instance**: The RDS PostgreSQL instance is created with the specified parameters, including the instance class `db.t4g.large`.

This configuration ensures that the RDS instance is properly set up with the necessary networking and security configurations.

