  description = "The username for the database"
  default     = "admin"
}

variable "password" {
  description = "The password for the database"
  sensitive   = true
  default     = "securepassword123"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  default     = "my-db-subnet-group"
}

variable "vpc_security_group_ids" {
  description = "A list of VPC security group IDs"
  type        = list(string)
  default     = ["sg-12345678"]
}

resource "aws_db_instance" "primary" {
  identifier             = var.db_instance_identifier
  instance_class         = var.db_instance_class
  allocated_storage      = var.allocated_storage
  engine                 = var.engine
  engine_version         = var.engine_version
  username               = var.username
  password               = var.password
  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = var.vpc_security_group_ids
  skip_final_snapshot    = true
}

resource "aws_db_instance" "replica" {
  identifier             = "${var.db_instance_identifier}-replica"
  instance_class         = var.db_instance_class
  source_db_instance_identifier = aws_db_instance.primary.identifier
  db_subnet_group_name   = var.db_subnet_group_name
  vpc_security_group_ids = var.vpc_security_group_ids
  skip_final_snapshot    = true
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined with default values to customize the database instance and its replica.
3. **Primary Database Instance**: An RDS instance (`aws_db_instance.primary`) is created using the specified parameters.
4. **Replica Database Instance**: A read replica (`aws_db_instance.replica`) is created, which replicates data from the primary instance.
5. **IAM Role and Policy**: An IAM role (`aws_iam_role.rds_iam_role`) is created with a trust policy allowing RDS to assume the role. The role is attached to the `AmazonRDSFullAccess` policy to grant necessary permissions.

This configuration ensures that both the primary and replica database instances are set up correctly with the necessary IAM roles and policies.

