### Description

The Terraform program below creates an AWS RDS database instance configured to use AWS Secrets Manager for managing the master password. The default AWS KMS key is used for encrypting the secrets stored in Secrets Manager. The program includes necessary IAM roles and policies to ensure proper access control.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_identifier" {
  description = "The identifier for the DB instance"
  type        = string
  default     = "my-rds-instance"
}

variable "db_instance_class" {
  description = "The instance class for the DB instance"
  type        = string
  default     = "db.t3.micro"
}

variable "engine" {
  description = "The database engine to use"
  type        = string
  default     = "mysql"
}

variable "engine_version" {
  description = "The version of the database engine"
  type        = string
  default     = "8.0"
}

variable "allocated_storage" {
  description = "The allocated storage size in gigabytes"
  type        = number
  default     = 20
}

variable "master_username" {
  description = "The username for the master database user"
  type        = string
  default     = "admin"
}

resource "aws_kms_key" "default" {
  description             = "Default KMS Key for Secrets Manager"
  deletion_window_in_days = 10
}

resource "aws_iam_role" "rds_secrets_manager_role" {
  name = "rds-secrets-manager-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "rds_secrets_manager_policy" {
  name        = "rds-secrets-manager-policy"
  description = "Policy for RDS to access Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecretVersionIds"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_secrets_manager_policy_attachment" {
  role       = aws_iam_role.rds_secrets_manager_role.name
  policy_arn = aws_iam_policy.rds_secrets_manager_policy.arn
}

resource "aws_db_instance" "example" {
  identifier              = var.db_instance_identifier
  instance_class          = var.db_instance_class
  engine                  = var.engine
  engine_version          = var.engine_version
  allocated_storage       = var.allocated_storage
  master_username         = var.master_username
  manage_master_password  = true
  master_password_secret_arn = aws_secretsmanager_secret.example.arn
  kms_key_id              = aws_kms_key.default.key_id
  skip_final_snapshot     = true
}

resource "aws_secretsmanager_secret" "example" {
  name = "${var.db_instance_identifier}-secret"

  kms_key_id = aws_kms_key.default.key_id

  tags = {
    Name = "${var.db_instance_identifier}-secret"
  }
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.password.result
  })

  depends_on = [aws_db_instance.example]
}

resource "random_password" "password" {
  length           = 16
  special          = true
  override_special = "_%@"
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined with default values to customize the RDS instance.
3. **KMS Key**: A default KMS key is created for encrypting secrets.
4. **IAM Role and Policy**: An IAM role and policy are created to allow the RDS service to access Secrets Manager.
5. **RDS Instance**: An RDS instance is created with `manage_master_password` set to `true`, which enables Secrets Manager to manage the master password.
6. **Secrets Manager Secret**: A Secrets Manager secret is created to store the master username and password.
7. **Random Password**: A random password is generated using the `random_password` resource and stored in the Secrets Manager secret.

This configuration ensures that the RDS instance uses AWS Secrets Manager to manage the master password securely.

