  name                     = "rds-master-password-${var.db_instance_identifier}"
  description              = "Master password for RDS instance ${var.db_instance_identifier}"
  kms_key_id               = var.kms_key_arn != "" ? var.kms_key_arn : aws_kms_key.example[0].arn
  recovery_window_in_days  = 7
  force_delete_without_recovery = false
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master_password.result
  })

  depends_on = [aws_db_instance.example]
}

resource "random_password" "master_password" {
  length           = 16
  special          = true
  override_special = "_%@"
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Several variables are defined to allow customization of the RDS instance, such as the instance identifier, class, engine, and storage size.
3. **KMS Key**: A KMS key is created if no ARN is provided in the `kms_key_arn` variable.
4. **IAM Role and Policy**: An IAM role and policy are created to allow the RDS service to access Secrets Manager.
5. **RDS Instance**: The RDS instance is created with `manage_master_password` set to `true`, which enables Secrets Manager to manage the master password.
6. **Secrets Manager Secret**: A Secrets Manager secret is created to store the master password.
7. **Random Password**: A random password is generated using the `random_password` resource and stored in the Secrets Manager secret.

This configuration ensures that the RDS instance uses AWS Secrets Manager for managing the master password, with the specified KMS key for encryption.

