### Description

The Terraform program below creates an Amazon Elastic File System (EFS) in a specified AWS region. It also configures a lifecycle policy for the EFS to transition files from Infrequent Access (IA) storage class to Archive storage class after 30 days. The program includes necessary IAM roles and policies to allow EFS access to the S3 bucket used for archiving.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the EFS"
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the EFS will be created"
  type        = string
}

variable "security_group_ids" {
  description = "A list of security group IDs to associate with the EFS"
  type        = list(string)
}

resource "aws_efs_file_system" "example" {
  creation_token = "my-example-efs"

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = {
    Name = "MyExampleEFS"
  }
}

resource "aws_efs_mount_target" "example" {
  file_system_id  = aws_efs_file_system.example.id
  subnet_id       = element(data.aws_subnet_ids.default.ids, 0)
  security_groups = var.security_group_ids
}

data "aws_subnet_ids" "default" {
  vpc_id = var.vpc_id
}

resource "aws_iam_role" "efs_lifecycle_role" {
  name = "EfsLifecycleRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "efs_lifecycle_policy" {
  name        = "EfsLifecyclePolicy"
  description = "Policy to allow EFS to transition files to IA and Archive"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::my-efs-archive-bucket/*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "efs_lifecycle_policy_attachment" {
  role       = aws_iam_role.efs_lifecycle_role.name
  policy_arn = aws_iam_policy.efs_lifecycle_policy.arn
}

resource "aws_s3_bucket" "archive_bucket" {
  bucket = "my-efs-archive-bucket"
  acl    = "private"
}

output "efs_id" {
  value = aws_efs_file_system.example.id
}

output "efs_dns_name" {
  value = aws_efs_file_system.example.dns_name
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.

2. **Variables**:
   - `region`: Specifies the AWS region.
   - `vpc_id`: Specifies the VPC ID where the EFS will be created.
   - `security_group_ids`: A list of security group IDs to associate with the EFS.

3. **EFS File System**: An EFS file system is created with a lifecycle policy that transitions files to IA storage class after 30 days.

4. **Mount Target**: A mount target is created for the EFS in the first subnet of the specified VPC.

5. **IAM Role and Policy**: An IAM role and policy are created to allow the EFS to transition files to IA and Archive storage classes in an S3 bucket.

6. **S3 Bucket**: An S3 bucket is created for archiving EFS files.

7. **Outputs**: The EFS ID and DNS name are outputted for reference.

This configuration ensures that the EFS is properly set up with a lifecycle policy and the necessary IAM permissions to archive files to S3.

