The Terraform program below creates an Amazon Elastic File System (EFS) in a specified AWS region. It also sets up an IAM role with a system policy that allows access to the EFS. The EFS is configured with a lifecycle policy to transition files to the Infrequent Access (IA) storage class after 30 days of non-access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the EFS"
  type        = string
  default     = "us-west-2"
}

variable "efs_name" {
  description = "The name of the EFS"
  type        = string
  default     = "my-efs"
}

resource "aws_efs_file_system" "example" {
  creation_token = var.efs_name
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = var.efs_name
  }
}

resource "aws_iam_role" "efs_access_role" {
  name = "${var.efs_name}-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "efs_access_policy" {
  name   = "${aws_iam_role.efs_access_role.name}-policy"
  role   = aws_iam_role.efs_access_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Effect = "Allow"
        Resource = aws_efs_file_system.example.arn
      },
    ]
  })
}

resource "aws_efs_lifecycle_configuration" "example" {
  file_system_id = aws_efs_file_system.example.id

