### Description

The Terraform program below sets up an AWS Virtual Private Cloud (VPC) with the following components:

1. **VPC**: A new VPC in the specified AWS region.
2. **Subnets**: Two public subnets in different availability zones.
3. **Internet Gateway**: An internet gateway attached to the VPC.
4. **Route Table**: A route table associated with the subnets to enable internet access.
5. **Security Group**: A security group allowing inbound traffic on the default ports for MySQL (3306) and PostgreSQL (5432) from any IP address.
6. **Database Subnet Group**: A subnet group that includes both subnets for use with RDS instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  count             = length(var.subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "database" {
  name        = "database-sg"
  description = "Allow MySQL and PostgreSQL access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "database-subnet-group"
  subnet_ids = aws_subnet.public[*].id
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **VPC**: A VPC is created with the specified CIDR block (`10.0.0.0/16`).
- **Subnets**: Two public subnets are created in different availability zones, each with its own CIDR block.
- **Internet Gateway**: An internet gateway is attached to the VPC to provide internet access.
- **Route Table**: A route table is created and associated with the subnets to route all traffic to the internet gateway.
- **Security Group**: A security group is created to allow inbound traffic on ports 3306 (MySQL) and 5432 (PostgreSQL) from any IP address.
- **Database Subnet Group**: A subnet group is created to include both subnets, suitable for use with RDS instances.

This configuration ensures that the VPC is properly set up with the necessary components for hosting MySQL and PostgreSQL databases.

