variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "Availability zones for the subnets"
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet" {
  count               = length(var.subnet_cidr_blocks)
  vpc_id              = aws_vpc.main.id
  cidr_block          = element(var.subnet_cidr_blocks, count.index)
  availability_zone   = element(var.availability_zones, count.index)
  map_public_ip_on_launch = true
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.subnet)
  subnet_id      = aws_subnet.subnet[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db_access" {
  name        = "db-access-sg"
  description = "Allow MySQL and PostgreSQL access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-group"
  subnet_ids = aws_subnet.subnet[*].id
}
```

### Explanation

- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Variables are defined for the VPC CIDR block, subnet CIDR blocks, and availability zones. Default values are provided.
- **VPC**: A VPC is created with the specified CIDR block and DNS support enabled.
- **Subnets**: Two subnets are created in different availability zones, each with public IP mapping enabled.
- **Internet Gateway**: An internet gateway is attached to the VPC.
- **Route Table**: A route table is created to route all traffic to the internet gateway.
- **Route Table Association**: The route table is associated with both subnets.
- **Security Group**: A security group is created to allow inbound traffic on ports 3306 (MySQL) and 5432 (PostgreSQL) from any IP address.
- **Database Subnet Group**: A subnet group is created to include both subnets, suitable for deploying RDS instances.

This configuration ensures that the VPC is set up with the necessary components for hosting MySQL and PostgreSQL databases with internet access.

