### Description

The Terraform program below sets up a VPC peering connection between two AWS Virtual Private Clouds (VPCs). The first VPC is named "peer," and the second VPC is named "base." The peering connection is named "pike" and is tagged with `pike = "permissions"` to indicate its purpose or management policy. The program includes necessary IAM roles and policies to allow the peering connection to be established.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_cidr_block_peer" {
  description = "CIDR block for the 'peer' VPC"
  default     = "10.0.0.0/16"
}

variable "vpc_cidr_block_base" {
  description = "CIDR block for the 'base' VPC"
  default     = "10.1.0.0/16"
}

resource "aws_vpc" "peer" {
  cidr_block = var.vpc_cidr_block_peer
  tags = {
    Name = "peer"
  }
}

resource "aws_vpc" "base" {
  cidr_block = var.vpc_cidr_block_base
  tags = {
    Name = "base"
  }
}

resource "aws_iam_role" "peering_role" {
  name = "vpc-peering-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "peering_policy" {
  name        = "vpc-peering-policy"
  description = "Policy for VPC peering"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:AcceptVpcPeeringConnection",
          "ec2:CreateVpcPeeringConnection",
          "ec2:DeleteVpcPeeringConnection",
          "ec2:DescribeVpcPeeringConnections",
          "ec2:ModifyVpcPeeringConnectionOptions"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_peering_policy" {
  role       = aws_iam_role.peering_role.name
  policy_arn = aws_iam_policy.peering_policy.arn
}

resource "aws_vpc_peering_connection" "pike" {
  vpc_id         = aws_vpc.peer.id
  peer_vpc_id    = aws_vpc.base.id
  auto_accept    = true
  tags = {
    Name      = "pike"
    pike      = "permissions"
  }
}

resource "aws_route" "peer_to_base" {
  route_table_id         = aws_vpc.peer.main_route_table_id
  destination_cidr_block = var.vpc_cidr_block_base
  vpc_peering_connection_id = aws_vpc_peering_connection.pike.id
}

resource "aws_route" "base_to_peer" {
  route_table_id         = aws_vpc.base.main_route_table_id
  destination_cidr_block = var.vpc_cidr_block_peer
  vpc_peering_connection_id = aws_vpc_peering_connection.pike.id
}
```

